import React, { useState } from 'react';
import { Task, User, UserRole, TaskStatus, Project } from '../types';
import { getEngineerWorkload } from '../services/mockService';
import { AlertTriangle, Plus, X } from 'lucide-react';

interface TaskManagerProps {
  tasks: Task[];
  users: User[];
  projects: Project[];
  currentUser: User;
  onAddTask: (task: Task) => void;
  onUpdateTask: (id: string, status: TaskStatus) => void;
}

const TaskManager: React.FC<TaskManagerProps> = ({ tasks, users, projects, currentUser, onAddTask, onUpdateTask }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newTaskName, setNewTaskName] = useState('');
  const [selectedEng, setSelectedEng] = useState('');
  const [selectedProject, setSelectedProject] = useState('');
  const [warningMsg, setWarningMsg] = useState<string | null>(null);

  const handleEngineerChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const uid = e.target.value;
    setSelectedEng(uid);
    if (uid) {
      const load = getEngineerWorkload(uid);
      if (load >= 2) {
        setWarningMsg(`警告: 此工程師目前已有 ${load} 個進行中任務。`);
      } else {
        setWarningMsg(null);
      }
    }
  };

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskName || !selectedEng || !selectedProject) return;

    // Simulate warning confirmation
    if (warningMsg && !window.confirm(`${warningMsg} 確定要指派嗎？`)) {
      return;
    }

    const newTask: Task = {
      id: `t-${Date.now()}`,
      name: newTaskName,
      projectId: selectedProject,
      assigneeId: selectedEng,
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      dependencies: [],
      department: users.find(u => u.id === selectedEng)?.department || '一般',
      isAdHoc: true
    };

    onAddTask(newTask);
    setIsModalOpen(false);
    // Reset form
    setNewTaskName('');
    setSelectedEng('');
    setSelectedProject('');
    setWarningMsg(null);
  };

  // Drag and drop would go here, simplified to Status Boards for this output
  const columns = [
    { id: TaskStatus.NOT_STARTED, label: '未開始', color: 'border-slate-300' },
    { id: TaskStatus.IN_PROGRESS, label: '進行中', color: 'border-blue-500' },
    { id: TaskStatus.COMPLETED, label: '已完成', color: 'border-green-500' },
  ];

  // Filter tasks based on role
  const visibleTasks = currentUser.role === UserRole.ENGINEER 
    ? tasks.filter(t => t.assigneeId === currentUser.id)
    : tasks;

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900">任務管理</h2>
        {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 指派任務
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full overflow-hidden">
        {columns.map(col => (
          <div key={col.id} className="bg-slate-100 rounded-xl p-4 flex flex-col h-full">
            <h3 className={`font-semibold text-slate-700 mb-4 pb-2 border-b-2 ${col.color}`}>
              {col.label} <span className="text-xs text-slate-400 ml-2 font-normal">({visibleTasks.filter(t => t.status === col.id).length})</span>
            </h3>
            <div className="flex-1 overflow-y-auto space-y-3">
              {visibleTasks.filter(t => t.status === col.id).map(task => (
                <div key={task.id} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 group">
                   <div className="flex justify-between items-start mb-2">
                     <span className="text-xs font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded">{task.department}</span>
                     {task.isAdHoc && <span className="text-[10px] text-amber-600 bg-amber-50 px-1 rounded border border-amber-100">臨時</span>}
                   </div>
                   <h4 className="font-medium text-slate-800 mb-1">{task.name}</h4>
                   <p className="text-xs text-slate-500 mb-3">{projects.find(p => p.id === task.projectId)?.name}</p>

                   <div className="flex items-center justify-between mt-4 border-t border-slate-50 pt-3">
                      <div className="flex items-center gap-2">
                        <img src={users.find(u => u.id === task.assigneeId)?.avatar} className="w-6 h-6 rounded-full" alt="assignee" />
                      </div>

                      {/* Simple status controls for demo */}
                      <div className="opacity-20 group-hover:opacity-100 transition-opacity flex gap-1">
                        {col.id !== TaskStatus.COMPLETED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.COMPLETED)} className="text-[10px] bg-green-100 text-green-700 px-2 py-1 rounded hover:bg-green-200">完成</button>
                        )}
                        {col.id === TaskStatus.NOT_STARTED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.IN_PROGRESS)} className="text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded hover:bg-blue-200">開始</button>
                        )}
                      </div>
                   </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">指派新任務</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleCreateTask} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">任務名稱</label>
                <input 
                  type="text" 
                  value={newTaskName} 
                  onChange={(e) => setNewTaskName(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">專案</label>
                <select 
                  value={selectedProject} 
                  onChange={(e) => setSelectedProject(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇專案...</option>
                  {projects.filter(p => p.status === 'IN_PROGRESS' || p.status === 'PLANNING').map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">負責人</label>
                <select 
                  value={selectedEng} 
                  onChange={handleEngineerChange}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇工程師...</option>
                  {users.filter(u => u.role === UserRole.ENGINEER).map(u => (
                    <option key={u.id} value={u.id}>{u.name} ({u.department})</option>
                  ))}
                </select>
              </div>

              {warningMsg && (
                <div className="bg-amber-50 border border-amber-200 text-amber-800 text-sm p-3 rounded-lg flex items-start gap-2">
                  <AlertTriangle size={16} className="mt-0.5" />
                  <span>{warningMsg}</span>
                </div>
              )}

              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700">指派任務</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
