import React, { useState, useMemo } from 'react';
import { User, UserRole } from '../types';
import { Users, Edit2, Shield, Briefcase, PlusCircle, Check } from 'lucide-react';

interface TeamManagementProps {
  users: User[];
  onUpdateUser: (user: User) => void;
}

const TeamManagement: React.FC<TeamManagementProps> = ({ users, onUpdateUser }) => {
  // Extract unique departments
  const existingDepartments = useMemo(() => 
    Array.from(new Set(users.map(u => u.department))).sort(), 
  [users]);

  const [departments, setDepartments] = useState<string[]>(existingDepartments);
  const [newDeptName, setNewDeptName] = useState('');
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Group users by department
  const usersByDept = useMemo(() => {
    const grouped: Record<string, User[]> = {};
    departments.forEach(d => grouped[d] = []);
    users.forEach(u => {
      if (grouped[u.department]) {
        grouped[u.department].push(u);
      } else {
        // Handle case where user might be in a department not in our derived list yet
        if (!grouped[u.department]) grouped[u.department] = [];
        grouped[u.department].push(u);
      }
    });
    return grouped;
  }, [users, departments]);

  const handleAddDepartment = () => {
    if (newDeptName && !departments.includes(newDeptName)) {
      setDepartments([...departments, newDeptName]);
      setNewDeptName('');
    }
  };

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onUpdateUser(editingUser);
      setEditingUser(null);
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-900">團隊與部門管理</h2>

        <div className="flex gap-2">
          <input 
            type="text" 
            value={newDeptName}
            onChange={(e) => setNewDeptName(e.target.value)}
            placeholder="新部門名稱..."
            className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand-500"
          />
          <button 
            onClick={handleAddDepartment}
            disabled={!newDeptName}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 disabled:opacity-50 flex items-center gap-2"
          >
            <PlusCircle size={16} /> 新增部門
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {departments.map(dept => (
          <div key={dept} className="bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
              <h3 className="font-bold text-slate-800">{dept}</h3>
              <span className="text-xs bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full">
                {usersByDept[dept]?.length || 0} 人
              </span>
            </div>

            <div className="p-4 flex-1 space-y-3">
              {usersByDept[dept]?.map(u => (
                <div key={u.id} className="flex items-center justify-between group">
                  <div className="flex items-center gap-3">
                    <img src={u.avatar} alt={u.name} className="w-8 h-8 rounded-full bg-slate-200" />
                    <div>
                      <p className="text-sm font-medium text-slate-800">{u.name}</p>
                      <div className="flex items-center gap-1 text-xs text-slate-500">
                        {u.role === UserRole.MANAGER ? (
                          <span className="flex items-center text-amber-600 font-bold">
                            <Shield size={10} className="mr-0.5" /> 主管
                          </span>
                        ) : (
                          <span>工程師</span>
                        )}
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={() => setEditingUser(u)}
                    className="p-1.5 text-slate-400 hover:text-brand-600 hover:bg-brand-50 rounded opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Edit2 size={14} />
                  </button>
                </div>
              ))}
              {(!usersByDept[dept] || usersByDept[dept].length === 0) && (
                <p className="text-xs text-slate-400 text-center py-4 italic">尚無成員</p>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Edit User Modal */}
      {editingUser && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-sm w-full p-6">
            <h3 className="text-lg font-bold text-slate-800 mb-4">編輯成員: {editingUser.name}</h3>
            <form onSubmit={handleSaveUser} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">所屬部門</label>
                <div className="relative">
                  <Briefcase className="absolute left-3 top-2.5 text-slate-400" size={16} />
                  <select 
                    value={editingUser.department}
                    onChange={(e) => setEditingUser({...editingUser, department: e.target.value})}
                    className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-brand-500"
                  >
                    {departments.map(d => (
                      <option key={d} value={d}>{d}</option>
                    ))}
                  </select>
                </div>
              </div>

              <div>
