  getProjects, getTasks, getUsers, getEvents, getNotices, getAssets, 
  getUserById, addTask, updateTaskStatus, updateUser, addEvent 
} from './services/mockService';
import { User, Project, Task, ScheduleEvent, Notice, Asset, TaskStatus, UserRole } from './types';

const App: React.FC = () => {
  // Global App State
  const [currentUser, setCurrentUser] = useState<User | undefined>(undefined);
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);

  // Initialization
  useEffect(() => {
    // Load mock data
    const allUsers = getUsers();
    setUsers(allUsers);
    setCurrentUser(allUsers[0]); // Default to Admin
    setProjects(getProjects());
    setTasks(getTasks());
    setEvents(getEvents());
    setNotices(getNotices());
    setAssets(getAssets());
  }, []);

  const handleSwitchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const handleAddTask = (newTask: Task) => {
    addTask(newTask);
    setTasks([...getTasks()]); // Refresh from service
  };

  const handleUpdateTask = (id: string, status: TaskStatus) => {
    updateTaskStatus(id, status);
    setTasks([...getTasks()]); // Refresh
  };

  const handleUpdateUser = (updatedUser: User) => {
    updateUser(updatedUser);
    setUsers([...getUsers()]); // Refresh
    // If updating current user self
    if (currentUser && currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
    }
  };

  const handleAddEvent = (newEvent: ScheduleEvent) => {
    addEvent(newEvent);
    setEvents([...getEvents()]);
  }

  if (!currentUser) return <div className="flex items-center justify-center h-screen">載入中...</div>;

  return (
    <HashRouter>
      <Layout currentUser={currentUser} onSwitchUser={handleSwitchUser} users={users}>
        <Routes>
          <Route path="/" element={<Dashboard user={currentUser} projects={projects} tasks={tasks} events={events} notices={notices} />} />
          <Route path="/projects" element={<ProjectHub projects={projects} tasks={tasks} currentUser={currentUser} />} />
          <Route path="/projects/:id" element={<ProjectHub projects={projects} tasks={tasks} currentUser={currentUser} />} />
          <Route path="/tasks" element={<TaskManager tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} />} />
          <Route path="/schedule" element={<ScheduleStats events={events} tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddEvent={handleAddEvent} />} />
          <Route path="/assets" element={<AssetBooking assets={assets} />} />

          {/* Admin Only Route */}
          {currentUser.role === UserRole.ADMIN && (
             <Route path="/team" element={<TeamManagement users={users} onUpdateUser={handleUpdateUser} />} />
          )}

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Task, User, UserRole, TaskStatus, Project } from '../types';
import { getEngineerWorkload } from '../services/mockService';
import { AlertTriangle, Plus, X, AlertCircle, Filter } from 'lucide-react';

interface TaskManagerProps {
  tasks: Task[];
  users: User[];
  projects: Project[];
  currentUser: User;
  onAddTask: (task: Task) => void;
  onUpdateTask: (id: string, status: TaskStatus) => void;
}

const TaskManager: React.FC<TaskManagerProps> = ({ tasks, users, projects, currentUser, onAddTask, onUpdateTask }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Filter State
  const [filterDept, setFilterDept] = useState<string>('');
  const [filterProject, setFilterProject] = useState<string>('');
  const [filterAssignee, setFilterAssignee] = useState<string>('');

  // Form State
  const [newTaskName, setNewTaskName] = useState('');
  const [selectedEng, setSelectedEng] = useState('');
  const [selectedProject, setSelectedProject] = useState('');
  const [isAdHoc, setIsAdHoc] = useState(false);
  const [warningMsg, setWarningMsg] = useState<string | null>(null);

  // Derived Options for Filtering
  const uniqueDepts = useMemo(() => Array.from(new Set(users.map(u => u.department))).sort(), [users]);

  const filteredProjects = useMemo(() => {
    if (!filterDept) return projects;
    // Show projects that have at least one department match
    return projects.filter(p => p.departments.includes(filterDept));
  }, [projects, filterDept]);

  const filteredUsers = useMemo(() => {
    let result = users;
    if (filterDept) {
      result = result.filter(u => u.department === filterDept);
    }
    return result;
  }, [users, filterDept]);

  // Derived Visible Tasks
  const visibleTasks = useMemo(() => {
    let result = tasks;

    // Engineer only sees own tasks usually, but let's allow them to see others if they want, 
    // or restrict if strict mode. For this requirement, we implement the requested filter.
    // If we want to strictly follow "Engineer sees own tasks", we should lock the assignee filter to currentUser.id
    if (currentUser.role === UserRole.ENGINEER) {
       result = result.filter(t => t.assigneeId === currentUser.id);
    } else {
       // Apply hierarchical filters for Admin/Manager
       if (filterDept) {
         // Filter tasks where the assignee is in the selected department
         // OR the task itself is marked with that department
         const deptUserIds = users.filter(u => u.department === filterDept).map(u => u.id);
         result = result.filter(t => t.department === filterDept || deptUserIds.includes(t.assigneeId));
       }
       if (filterProject) {
         result = result.filter(t => t.projectId === filterProject);
       }
       if (filterAssignee) {
         result = result.filter(t => t.assigneeId === filterAssignee);
       }
    }
    return result;
  }, [tasks, currentUser, filterDept, filterProject, filterAssignee, users]);


  const handleEngineerChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const uid = e.target.value;
    setSelectedEng(uid);
    if (uid) {
      const load = getEngineerWorkload(uid);
      const user = users.find(u => u.id === uid);
      if (load >= 2) {
        setWarningMsg(`${user?.name || '此工程師'} 目前已有 ${load} 個任務進行中。`);
      } else {
        setWarningMsg(null);
      }
    } else {
      setWarningMsg(null);
    }
  };

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskName || !selectedEng || !selectedProject) return;

    // Simulate warning confirmation
    if (warningMsg && !window.confirm(`警告: ${warningMsg}\n\n您確定要繼續指派此任務嗎？`)) {
      return;
    }

    const newTask: Task = {
      id: `t-${Date.now()}`,
      name: newTaskName,
      projectId: selectedProject,
      assigneeId: selectedEng,
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      dependencies: [],
      department: users.find(u => u.id === selectedEng)?.department || '一般',
      isAdHoc: isAdHoc // Set the Ad-hoc flag
    };

    onAddTask(newTask);
    setIsModalOpen(false);
    // Reset form
    setNewTaskName('');
    setSelectedEng('');
    setSelectedProject('');
    setIsAdHoc(false);
    setWarningMsg(null);
  };

  const columns = [
    { id: TaskStatus.NOT_STARTED, label: '未開始', color: 'border-slate-300' },
    { id: TaskStatus.IN_PROGRESS, label: '進行中', color: 'border-blue-500' },
    { id: TaskStatus.COMPLETED, label: '已完成', color: 'border-green-500' },
  ];

  return (
    <div className="h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-6">
        <h2 className="text-2xl font-bold text-slate-900">任務管理</h2>

        {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2 shadow-sm whitespace-nowrap"
          >
            <Plus size={16} /> 指派任務
          </button>
        )}
      </div>

      {/* Hierarchical Filters */}
      {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 mb-6 flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2 text-slate-500 text-sm font-medium">
            <Filter size={16} />
            <span>篩選:</span>
          </div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">1. 部門</label>
            <select 
              value={filterDept}
              onChange={(e) => {
                setFilterDept(e.target.value);
                setFilterProject('');
                setFilterAssignee('');
              }}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50"
            >
              <option value="">全部部門</option>
              {uniqueDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>

          <div className="text-slate-300">→</div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">2. 專案</label>
            <select 
              value={filterProject}
              onChange={(e) => {
                 setFilterProject(e.target.value);
                 // Optional: Reset assignee if they are not in this project?
                 // For now keep assignee filter as it might be useful to see "User X in Project Y"
              }}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50 max-w-[200px]"
            >
              <option value="">全部專案</option>
              {filteredProjects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>

           <div className="text-slate-300">→</div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">3. 負責人</label>
             <select 
              value={filterAssignee}
              onChange={(e) => setFilterAssignee(e.target.value)}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50"
            >
              <option value="">全部人員</option>
              {filteredUsers.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
            </select>
          </div>

          <button 
            onClick={() => { setFilterDept(''); setFilterProject(''); setFilterAssignee(''); }}
            className="ml-auto text-xs text-slate-400 hover:text-slate-600 underline"
          >
            清除篩選
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full overflow-hidden">
        {columns.map(col => (
          <div key={col.id} className="bg-slate-100 rounded-xl p-4 flex flex-col h-full">
            <h3 className={`font-semibold text-slate-700 mb-4 pb-2 border-b-2 ${col.color}`}>
              {col.label} <span className="text-xs text-slate-400 ml-2 font-normal">({visibleTasks.filter(t => t.status === col.id).length})</span>
            </h3>
            <div className="flex-1 overflow-y-auto space-y-3">
              {visibleTasks.filter(t => t.status === col.id).length === 0 && (
                <div className="text-center py-8 text-slate-400 text-sm italic">無相關任務</div>
              )}
              {visibleTasks.filter(t => t.status === col.id).map(task => (
                <div key={task.id} className={`bg-white p-4 rounded-lg shadow-sm border group relative ${task.isAdHoc ? 'border-l-4 border-l-amber-500 border-slate-200' : 'border-slate-200'}`}>
                   {task.isAdHoc && (
                     <div className="absolute top-3 right-3">
                       <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded font-bold">臨時</span>
                     </div>
                   )}
                   <div className="flex justify-between items-start mb-2 pr-8">
                     <span className="text-xs font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded">{task.department}</span>
                   </div>
                   <h4 className="font-medium text-slate-800 mb-1">{task.name}</h4>
                   <p className="text-xs text-slate-500 mb-3">{projects.find(p => p.id === task.projectId)?.name}</p>

                   <div className="flex items-center justify-between mt-4 border-t border-slate-50 pt-3">
                      <div className="flex items-center gap-2">
                        <img src={users.find(u => u.id === task.assigneeId)?.avatar} className="w-6 h-6 rounded-full" alt="assignee" />
                        <span className="text-xs text-slate-500">{users.find(u => u.id === task.assigneeId)?.name.split(' ')[0]}</span>
                      </div>

                      {/* Simple status controls for demo */}
                      <div className="opacity-20 group-hover:opacity-100 transition-opacity flex gap-1">
                        {col.id !== TaskStatus.COMPLETED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.COMPLETED)} className="text-[10px] bg-green-100 text-green-700 px-2 py-1 rounded hover:bg-green-200">完成</button>
                        )}
                        {col.id === TaskStatus.NOT_STARTED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.IN_PROGRESS)} className="text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded hover:bg-blue-200">開始</button>
                        )}
                      </div>
                   </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">指派新任務</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleCreateTask} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">任務名稱</label>
                <input 
                  type="text" 
                  value={newTaskName} 
                  onChange={(e) => setNewTaskName(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入任務內容..."
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">專案歸屬</label>
                <select 
                  value={selectedProject} 
                  onChange={(e) => setSelectedProject(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇專案...</option>
                  {projects.filter(p => p.status === 'IN_PROGRESS' || p.status === 'PLANNING').map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">指派給</label>
                <select 
                  value={selectedEng} 
                  onChange={handleEngineerChange}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇工程師...</option>
                  {users.filter(u => u.role === UserRole.ENGINEER).map(u => (
                    <option key={u.id} value={u.id}>{u.name} ({u.department})</option>
                  ))}
                </select>
              </div>

              {/* Task Type Toggle */}
              <div className="flex items-center gap-2 pt-1">
                <input 
                  type="checkbox" 
                  id="isAdHoc"
                  checked={isAdHoc}
                  onChange={(e) => setIsAdHoc(e.target.checked)}
                  className="w-4 h-4 text-brand-600 rounded focus:ring-brand-500 border-gray-300"
                />
                <label htmlFor="isAdHoc" className="text-sm font-medium text-slate-700">這是一項臨時任務 (Ad-hoc)</label>
              </div>

              {/* Workload Warning */}
              {warningMsg && (
                <div className="bg-amber-50 border border-amber-200 text-amber-800 text-sm p-4 rounded-lg flex items-start gap-3 mt-2">
                  <AlertTriangle size={20} className="mt-0.5 flex-shrink-0 text-amber-600" />
                  <div className="flex-1">
                    <p className="font-bold mb-1">工作量警示</p>
                    <p>{warningMsg}</p>
                    <p className="text-xs text-amber-600/80 mt-1">您仍可強制指派，但請留意工程師負荷。</p>
                  </div>
                </div>
              )}

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button 
                  type="submit" 
                  className={`px-4 py-2 text-white rounded-lg text-sm font-medium flex items-center gap-2 ${warningMsg ? 'bg-amber-600 hover:bg-amber-700' : 'bg-brand-600 hover:bg-brand-700'}`}
                >
                  {warningMsg ? <><AlertCircle size={16}/> 強制指派</> : <><Plus size={16}/> 確認指派</>}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskManager;

import React, { useState } from 'react';
import { ScheduleEvent, Task, User, UserRole, Project } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Plus, X, Calendar } from 'lucide-react';

interface ScheduleStatsProps {
  events: ScheduleEvent[];
  tasks: Task[];
  users: User[];
  projects: Project[];
  currentUser: User;
  onAddEvent: (event: ScheduleEvent) => void;
}

const ScheduleStats: React.FC<ScheduleStatsProps> = ({ events, tasks, users, projects, currentUser, onAddEvent }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Event Form State
  const [title, setTitle] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [relatedProject, setRelatedProject] = useState('');
  const [selectedAttendees, setSelectedAttendees] = useState<string[]>([]);

  const handleAddEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !date || !time) return;

    const newEvent: ScheduleEvent = {
      id: `e-${Date.now()}`,
      title,
      date,
      time,
      relatedProjectId: relatedProject || undefined,
      attendees: selectedAttendees
    };

    onAddEvent(newEvent);
    setIsModalOpen(false);
    // Reset form
    setTitle('');
    setDate('');
    setTime('');
    setRelatedProject('');
    setSelectedAttendees([]);
  };

  const toggleAttendee = (userId: string) => {
    if (selectedAttendees.includes(userId)) {
      setSelectedAttendees(selectedAttendees.filter(id => id !== userId));
    } else {
      setSelectedAttendees([...selectedAttendees, userId]);
    }
  };

  // Prepare data for Department Workload
  const deptData = React.useMemo(() => {
    const counts: Record<string, number> = {};
    tasks.forEach(t => {
      counts[t.department] = (counts[t.department] || 0) + 1;
    });
    return Object.keys(counts).map(k => ({ name: k, count: counts[k] }));
  }, [tasks]);

  // Prepare data for Task Status Distribution
  const statusMap: Record<string, string> = {
    'NOT_STARTED': '未開始',
    'IN_PROGRESS': '進行中',
    'COMPLETED': '已完成',
    'OVERDUE': '逾期'
  };

  const statusData = React.useMemo(() => {
      const counts: Record<string, number> = {};
      tasks.forEach(t => {
          counts[t.status] = (counts[t.status] || 0) + 1;
      });
      return Object.keys(counts).map(k => ({ name: statusMap[k] || k, value: counts[k] }));
  }, [tasks]);

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

  const canAddEvent = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER;

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-900">行程與統計</h2>
        {canAddEvent && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增行程
          </button>
        )}
      </div>

      {/* Calendar Section (Simplified List) */}
      <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">即將到來的行程</h3>
        <div className="overflow-x-auto">
          <table className="w-full text-sm text-left">
            <thead className="bg-slate-50 text-slate-500">
              <tr>
                <th className="px-6 py-3">日期</th>
                <th className="px-6 py-3">時間</th>
                <th className="px-6 py-3">行程</th>
                <th className="px-6 py-3">相關專案</th>
                <th className="px-6 py-3">參與人</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {events.map(e => (
                <tr key={e.id}>
                  <td className="px-6 py-4 font-medium">{e.date}</td>
                  <td className="px-6 py-4 text-slate-500">{e.time}</td>
                  <td className="px-6 py-4 font-semibold text-slate-700">{e.title}</td>
                   <td className="px-6 py-4 text-slate-500">
                     {projects.find(p => p.id === e.relatedProjectId)?.name || '-'}
                   </td>
                  <td className="px-6 py-4">
                    <div className="flex -space-x-2">
                       {e.attendees.map((uid, idx) => (
                         <div key={idx} className="w-8 h-8 rounded-full border-2 border-white bg-slate-200 flex items-center justify-center overflow-hidden" title={users.find(u => u.id === uid)?.name}>
                           <img src={users.find(u => u.id === uid)?.avatar} alt="" className="w-full h-full object-cover" />
                         </div>
                       ))}
                       {e.attendees.length === 0 && <span className="text-slate-400 text-xs italic">無</span>}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Stats Charts */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Department Workload */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">部門任務分佈</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={deptData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" tick={{fontSize: 12}} />
              <YAxis tick={{fontSize: 12}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="count" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Task Status */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">整體專案健康度</h3>
          <ResponsiveContainer width="100%" height="100%">
             <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {statusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} />
             </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Add Event Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">新增行程</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleAddEvent} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">行程標題</label>
                <input 
                  type="text" 
                  value={title} 
                  onChange={(e) => setTitle(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="例：專案啟動會議"
                  required
