// --- Service Logic ---

export const getProjects = () => PROJECTS;
export const getTasks = () => TASKS;
export const getUsers = () => USERS;
export const getEvents = () => EVENTS;
export const getNotices = () => NOTICES;
export const getAssets = () => ASSETS;
export const getTaskTemplates = () => TASK_TEMPLATES;

export const getTasksByProject = (pid: string) => TASKS.filter(t => t.projectId === pid);
export const getTasksByUser = (uid: string) => TASKS.filter(t => t.assigneeId === uid);

export const getEngineerWorkload = (uid: string): number => {
  return TASKS.filter(t => t.assigneeId === uid && (t.status === TaskStatus.IN_PROGRESS)).length;
};

export const addTask = (task: Task) => {
  TASKS.push(task);
  return task;
};

export const updateTask = (task: Task) => {
  const index = TASKS.findIndex(t => t.id === task.id);
  if (index !== -1) {
    TASKS[index] = task;
  }
};

export const updateTaskStatus = (tid: string, status: TaskStatus) => {
  const t = TASKS.find(task => task.id === tid);
  if (t) t.status = status;
};

export const updateUser = (updatedUser: User) => {
  const index = USERS.findIndex(u => u.id === updatedUser.id);
  if (index !== -1) {
    USERS[index] = updatedUser;
  }
};

export const addProject = (project: Project) => {
  PROJECTS.push(project);
  return project;
};

export const updateProject = (project: Project) => {
  const index = PROJECTS.findIndex(p => p.id === project.id);
  if (index !== -1) {
    PROJECTS[index] = project;
  }
};

export const addEvent = (event: ScheduleEvent) => {
  EVENTS.push(event);
  EVENTS.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
};

export const addTasksFromTemplate = (projectId: string, templateId: string, startDateStr: string, assigneeId: string) => {
  const template = TASK_TEMPLATES.find(t => t.id === templateId);
  if (!template) return;

  let lastTaskId: string | null = null;
  const baseDate = new Date(startDateStr);

  template.steps.forEach((step, index) => {
    // Calculate start date
    const start = new Date(baseDate);
    start.setDate(baseDate.getDate() + step.offsetStart);

    // Calculate end date
    const end = new Date(start);
    end.setDate(start.getDate() + step.durationDays);

    const newTask: Task = {
      id: `t-${Date.now()}-${index}`,
      projectId: projectId,
      name: step.name,
      assigneeId: assigneeId, // Default to manager initially or specific person
      startDate: start.toISOString().split('T')[0],
      endDate: end.toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      department: template.department,
      dependencies: lastTaskId ? [lastTaskId] : [],
      isAdHoc: false
    };

    TASKS.push(newTask);
    lastTaskId = newTask.id; // Chain them sequentially by default
  });
};

export const getUserById = (id: string) => USERS.find(u => u.id === id);
export const getProjectById = (id: string) => PROJECTS.find(p => p.id === id);

export const checkOverdue = (task: Task): boolean => {
    if (task.status === TaskStatus.COMPLETED) return false;
    const end = new Date(task.endDate);
    const now = new Date();
    return end < now;
};

