                  <button type="button" onClick={() => setEditTaskModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700">
                    儲存調整
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Edit Project Modal (Existing) */}
        {isEditModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">編輯專案</h3>
                <button onClick={() => setEditModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleEditSubmit} className="space-y-4">
                {renderFormFields()}

                {/* Status Field (Only for Edit) */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">專案狀態</label>
                  <select 
                    value={formData.status} 
                    onChange={e => setFormData({...formData, status: e.target.value as ProjectStatus})}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                  >
                    {Object.entries(PROJECT_STATUS_MAP).map(([key, label]) => (
                      <option key={key} value={key}>{label}</option>
                    ))}
                  </select>
                </div>

                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setEditModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Save size={16} /> 儲存變更
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- LIST VIEW ---

  // Extract all unique departments from projects for filter
  const filterDepartments = Array.from(new Set(projects.flatMap(p => p.departments))).sort();

  // Filter projects based on selection
  const filteredProjects = selectedDept === 'ALL'
    ? projects
    : projects.filter(p => p.departments.includes(selectedDept));

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-900">專案中心</h2>
        {currentUser.role === UserRole.ADMIN && (
          <button 
            onClick={openCreateModal}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增專案
          </button>
        )}
      </div>

      {/* Department Tabs (Filter) */}
      <div className="flex flex-wrap items-center gap-2 pb-2">
        <div className="flex items-center gap-2 mr-2 text-slate-500 text-sm">
          <Filter size={16} />
          <span>部門篩選:</span>
        </div>
        <button
          onClick={() => setSelectedDept('ALL')}
          className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
            selectedDept === 'ALL'
              ? 'bg-slate-800 text-white shadow-sm'
              : 'bg-white text-slate-600 hover:bg-slate-100 border border-slate-200'
          }`}
        >
          全部
        </button>
        {filterDepartments.map(dept => (
          <button
            key={dept}
            onClick={() => setSelectedDept(dept)}
            className={`px-4 py-1.5 rounded-full text-sm font-medium transition-all ${
              selectedDept === dept
                ? 'bg-brand-600 text-white shadow-sm'
                : 'bg-white text-slate-600 hover:bg-slate-100 border border-slate-200'
            }`}
          >
            {dept}
          </button>
        ))}
      </div>

      {filteredProjects.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
           <p className="text-slate-500">此部門目前沒有相關專案。</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredProjects.map(project => {
            const pTasks = tasks.filter(t => t.projectId === project.id);
            const activeCount = pTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;

            return (
              <div key={project.id} onClick={() => navigate(`/projects/${project.id}`)} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow cursor-pointer group">
                <div className="flex justify-between items-start mb-4">
                  <div className="w-10 h-10 rounded-lg bg-brand-50 flex items-center justify-center text-brand-600 font-bold group-hover:bg-brand-600 group-hover:text-white transition-colors">
                    {project.name.charAt(0)}
                  </div>
                  <span className={`px-2 py-1 text-[10px] font-bold uppercase rounded ${project.status === ProjectStatus.IN_PROGRESS ? 'bg-green-50 text-green-600' : 'bg-slate-100 text-slate-600'}`}>
                    {PROJECT_STATUS_MAP[project.status]}
                  </span>
                </div>
                <h3 className="text-lg font-bold text-slate-800 mb-1">{project.name}</h3>
                <p className="text-sm text-slate-500 mb-4">{project.client}</p>

                <div className="flex flex-wrap gap-1 mb-4">
                  {project.departments.map(d => (
                    <span key={d} className="text-[10px] px-1.5 py-0.5 bg-slate-50 text-slate-500 border border-slate-100 rounded">
                      {d}
                    </span>
                  ))}
                </div>

                <div className="flex items-center justify-between text-xs text-slate-400 border-t border-slate-100 pt-4">
                  <div className="flex items-center gap-1">
                    <CheckSquare size={14} />
                    <span>{activeCount} 個進行中任務</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Clock size={14} />
                    <span>到期日 {project.endDate}</span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Create Project Modal */}
      {isCreateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">建立新專案</h3>
                <button onClick={() => setCreateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleCreateSubmit} className="space-y-4">
                {renderFormFields()}
                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setCreateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Plus size={16} /> 建立專案
                  </button>
                </div>
              </form>
            </div>
          </div>
      )}
    </div>
  );
};

export default ProjectHub;

