};

// --- Helper Component: Quick Status Selector ---
interface QuickStatusSelectorProps {
  project: Project;
  canEdit: boolean;
  onUpdateStatus: (newStatus: ProjectStatus) => void;
}

const QuickStatusSelector: React.FC<QuickStatusSelectorProps> = ({ project, canEdit, onUpdateStatus }) => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const config = STATUS_CONFIG[project.status];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (status: ProjectStatus) => {
    onUpdateStatus(status);
    setIsOpen(false);
  };

  return (
    <div className="relative" ref={menuRef} onClick={(e) => e.stopPropagation()}>
      <button
        onClick={() => canEdit && setIsOpen(!isOpen)}
        disabled={!canEdit}
        className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold border transition-colors ${config.color} ${canEdit ? 'cursor-pointer' : 'cursor-default'}`}
      >
        <span className={`w-2 h-2 rounded-full ${config.dot}`} />
        {config.label}
        {canEdit && <ChevronDown size={12} className={`transition-transform ${isOpen ? 'rotate-180' : ''}`} />}
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-slate-100 z-50 animate-in fade-in zoom-in-95 duration-100 overflow-hidden">
          <div className="py-1">
             <div className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-wider bg-slate-50 border-b border-slate-100">
                設定專案狀態
             </div>
            {Object.entries(STATUS_CONFIG).map(([key, conf]) => (
              <button
                key={key}
                onClick={() => handleSelect(key as ProjectStatus)}
                className={`w-full text-left px-3 py-2 text-xs flex items-center gap-2 hover:bg-slate-50 transition-colors ${project.status === key ? 'bg-slate-50' : ''}`}
              >
                <span className={`w-2 h-2 rounded-full ${conf.dot}`} />
                <span className={`flex-1 font-medium ${project.status === key ? 'text-slate-900' : 'text-slate-600'}`}>{conf.label}</span>
                {project.status === key && <Check size={12} className="text-brand-600" />}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};


// Simple Flowchart Visualization Component using SVG/D3 logic
interface GraphProps {
  tasks: Task[];
  onTaskClick?: (task: Task) => void;
}

const SimpleDependencyGraph: React.FC<GraphProps> = ({ tasks, onTaskClick }) => {
  // Sort tasks roughly by time/id to layout
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  // Basic layout logic: Assign columns based on dependency depth
  const nodes: (Task & { x: number; y: number; col: number })[] = [];
  const links: { source: string; target: string }[] = [];

  const getCol = (taskId: string, currentDepth = 0): number => {
      const task = tasks.find(t => t.id === taskId);
      if(!task) return 0;
      if(!task.dependencies || task.dependencies.length === 0) return 0;
      // Prevent infinite loop if circular dependency exists (basic check)
      if (currentDepth > 20) return 0;
      return Math.max(...task.dependencies.map(d => getCol(d, currentDepth + 1))) + 1;
  };

  sortedTasks.forEach((t, i) => {
    const col = getCol(t.id);
    const siblings = nodes.filter(n => n.col === col);
    // Dynamic layout spacing
    nodes.push({ ...t, col, x: col * 200 + 50, y: siblings.length * 100 + 50 });
    t.dependencies?.forEach(depId => {
       links.push({ source: depId, target: t.id });
    });
  });

  const width = Math.max(800, (Math.max(...nodes.map(n => n.col), 0) + 1) * 220);
  const height = Math.max(300, Math.max(...nodes.map(n => n.y), 0) + 150);

  if (tasks.length === 0) {
    return <div className="p-8 text-center text-slate-400">目前尚無任務流程。請等待部門主管設定任務鏈。</div>;
  }

  return (
    <div className="overflow-x-auto border rounded-lg bg-slate-50 p-4 relative">
      <div className="absolute top-2 right-2 text-xs text-slate-400 flex items-center gap-1 z-10">
        {onTaskClick && <span className="bg-white px-2 py-1 rounded border shadow-sm">💡 點擊方塊可編輯任務</span>}
      </div>
      <svg width={width} height={height}>
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
          </marker>
        </defs>
        {/* Links */}
        {links.map((link, i) => {
           const s = nodes.find(n => n.id === link.source);
           const t = nodes.find(n => n.id === link.target);
           if (!s || !t) return null;
           // Draw curved path
           const path = `M${s.x + 80},${s.y + 25} C${s.x + 130},${s.y + 25} ${t.x - 50},${t.y + 25} ${t.x},${t.y + 25}`;
           return <path key={i} d={path} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />;
        })}
        {/* Nodes */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            transform={`translate(${node.x}, ${node.y})`}
            onClick={() => onTaskClick && onTaskClick(node)}
            style={{ cursor: onTaskClick ? 'pointer' : 'default' }}
            className={onTaskClick ? "hover:opacity-80 transition-opacity group" : ""}
          >
            <rect 
               width="160" 
               height="60" 
               rx="8" 
               fill="white" 
               stroke={node.status === TaskStatus.COMPLETED ? '#22c55e' : node.status === TaskStatus.IN_PROGRESS ? '#3b82f6' : '#e2e8f0'}
               strokeWidth="2"
               className="shadow-sm"
            />
             {/* Hover Effect Border */}
             {onTaskClick && (
              <rect width="160" height="60" rx="8" fill="transparent" stroke="#0ea5e9" strokeWidth="2" className="opacity-0 group-hover:opacity-50" />
            )}

            <text x="80" y="25" textAnchor="middle" className="text-[12px] font-bold fill-slate-700" style={{pointerEvents: 'none'}}>
                {node.name.length > 12 ? node.name.substring(0, 11) + '...' : node.name}
            </text>
            <text x="80" y="45" textAnchor="middle" className="text-[10px] fill-slate-500" style={{pointerEvents: 'none'}}>{node.department}</text>
             <text x="150" y="55" textAnchor="end" className="text-[9px] fill-slate-400" style={{pointerEvents: 'none'}}>{node.startDate}</text>
          </g>
        ))}
      </svg>
    </div>
  );
};

const ProjectHub: React.FC<ProjectHubProps> = ({ projects, tasks, users, currentUser, onAddProject, onUpdateProject, onImportTemplate, onUpdateTask }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [selectedDept, setSelectedDept] = useState<string>('ALL');

  // Modals State
  const [isCreateModalOpen, setCreateModalOpen] = useState(false);
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [isTemplateModalOpen, setTemplateModalOpen] = useState(false);
  const [isEditTaskModalOpen, setEditTaskModalOpen] = useState(false);

  // Form Data State
  const [formData, setFormData] = useState<Partial<Project>>({
    name: '', client: '', description: '', startDate: '', endDate: '', departments: []
  });

  // Template Form State
  const [templateId, setTemplateId] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateAssignee, setTemplateAssignee] = useState('');

  // Task Edit State
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Extract all known departments from existing projects for suggestions
  const allKnownDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  const taskTemplates = useMemo(() => {
    const templates = getTaskTemplates();
    if (selectedDept !== 'ALL') {
      return templates.filter(t => t.department === selectedDept);
    }
    return templates;
  }, [selectedDept]);

  const openCreateModal = () => {
    setFormData({
      name: '', client: '', description: '', 
      startDate: new Date().toISOString().split('T')[0], 
      endDate: '', 
      departments: []
    });
    setCreateModalOpen(true);
  };

  const openEditModal = (project: Project) => {
    setFormData({ ...project });
    setEditModalOpen(true);
  };

  const openEditTaskModal = (task: Task) => {
    setEditingTask({ ...task });
    setEditTaskModalOpen(true);
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.client) return;

    const newProject: Project = {
      id: `p-${Date.now()}`,
      name: formData.name!,
      client: formData.client!,
      description: formData.description || '',
      startDate: formData.startDate!,
      endDate: formData.endDate!,
      departments: formData.departments || [],
      status: ProjectStatus.PLANNING, // Default status
      managerId: currentUser.id // Admin is creator
    };

    onAddProject(newProject);
    setCreateModalOpen(false);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.id) {
       onUpdateProject(formData as Project);
       setEditModalOpen(false);
    }
  };

  const handleTemplateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (id && templateId && templateStartDate) {
      onImportTemplate(id, templateId, templateStartDate, templateAssignee || currentUser.id);
      setTemplateModalOpen(false);
      setTemplateId('');
      setTemplateStartDate('');
      setTemplateAssignee('');
    }
  };

  const handleEditTaskSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTask) {
      onUpdateTask(editingTask);
      setEditTaskModalOpen(false);
      setEditingTask(null);
    }
  };

  const toggleDependency = (targetTaskId: string) => {
      if (!editingTask) return;
      const currentDeps = editingTask.dependencies || [];
      if (currentDeps.includes(targetTaskId)) {
          setEditingTask({ ...editingTask, dependencies: currentDeps.filter(d => d !== targetTaskId) });
      } else {
          setEditingTask({ ...editingTask, dependencies: [...currentDeps, targetTaskId] });
      }
  };

  const autoSetStartDate = () => {
      if (!editingTask || !editingTask.dependencies || editingTask.dependencies.length === 0) return;

      const parentTasks = tasks.filter(t => editingTask.dependencies.includes(t.id));
      if (parentTasks.length === 0) return;

      // Find the max end date of parents
      const maxEndDate = parentTasks.reduce((max, task) => {
          const end = new Date(task.endDate);
          return end > max ? end : max;
      }, new Date(0));

      if (maxEndDate.getTime() > 0) {
          // Set to next day
          const nextDay = new Date(maxEndDate);
          nextDay.setDate(nextDay.getDate() + 1);
          setEditingTask({ ...editingTask, startDate: nextDay.toISOString().split('T')[0] });
      }
  };

  const toggleDepartment = (dept: string) => {
    const current = formData.departments || [];
    if (current.includes(dept)) {
      setFormData({ ...formData, departments: current.filter(d => d !== dept) });
    } else {
      setFormData({ ...formData, departments: [...current, dept] });
    }
  };

  // Render Modal Form Content (Shared fields)
  const renderFormFields = () => (
    <>
       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">專案名稱</label>
            <input 
              type="text" 
              required
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">客戶名稱</label>
            <input 
              type="text" 
              required
              value={formData.client} 
              onChange={e => setFormData({...formData, client: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">開始日期</label>
            <input 
              type="date" 
              value={formData.startDate} 
              onChange={e => setFormData({...formData, startDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">預計結束日期</label>
            <input 
              type="date" 
              value={formData.endDate} 
              onChange={e => setFormData({...formData, endDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">專案描述</label>
          <textarea 
            rows={3}
            value={formData.description} 
            onChange={e => setFormData({...formData, description: e.target.value})}
            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
          />
       </div>

       {/* Department Assignment */}
       <div>
         <label className="block text-sm font-medium text-slate-700 mb-2">指派參與部門</label>
         <div className="border border-slate-200 rounded-lg p-3 bg-slate-50 max-h-32 overflow-y-auto grid grid-cols-2 gap-2">
            {allKnownDepartments.map(dept => (
              <label key={dept} className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={formData.departments?.includes(dept)} 
                  onChange={() => toggleDepartment(dept)}
                  className="rounded text-brand-600 focus:ring-brand-500"
                />
                <span className="text-sm text-slate-600">{dept}</span>
              </label>
            ))}
         </div>
         <p className="text-xs text-slate-400 mt-1">選取後，各部門主管將會收到通知並安排詳細任務流程。</p>
       </div>
    </>
  );

  // --- DETAIL VIEW ---
  if (id) {
    const project = projects.find(p => p.id === id);
    if (!project) return <div>Project not found</div>;

    const projectTasks = tasks.filter(t => t.projectId === id);
    const isDeptManager = currentUser.role === UserRole.MANAGER && project.departments.includes(currentUser.department);
    const canEditTasks = isDeptManager || currentUser.role === UserRole.ADMIN;
    const canEditStatus = currentUser.role === UserRole.ADMIN;

    const availableTemplates = getTaskTemplates().filter(t => t.department === currentUser.department);

    return (
      <div className="space-y-6 animate-in fade-in duration-300">
        {/* Breadcrumb */}
        <button onClick={() => navigate('/projects')} className="flex items-center text-sm text-slate-500 hover:text-brand-600 mb-4">
          <ArrowLeft size={16} className="mr-1" /> 返回專案列表
        </button>

        {/* Project Header */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">{project.name}</h1>
              {/* Quick Status Selector in Detail View */}
              <QuickStatusSelector 
                project={project} 
                canEdit={canEditStatus} 
                onUpdateStatus={(s) => onUpdateProject({...project, status: s})} 
              />
            </div>
            <p className="text-slate-500 mt-2">{project.description}</p>
            <div className="flex items-center gap-6 mt-4 text-sm text-slate-500">
               <span className="flex items-center gap-1"><Calendar size={14} /> {project.startDate} - {project.endDate}</span>
               <span className="flex items-center gap-1"><UserCircle size={14} /> 客戶: {project.client}</span>
            </div>
            <div className="flex gap-2 mt-4">
              <span className="text-xs font-bold text-slate-400 py-1">參與部門:</span>
              {project.departments.map(d => (
                <span key={d} className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200">
                  {d}
                </span>
              ))}
            </div>
          </div>
          <div className="flex gap-2">
            {isDeptManager && (
              <button 
                onClick={() => {
                   setTemplateStartDate(new Date().toISOString().split('T')[0]);
                   setTemplateAssignee(currentUser.id);
                   setTemplateModalOpen(true);
                }}
                className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm hover:bg-brand-700 flex items-center gap-2"
              >
                <Workflow size={16} /> 匯入任務流程
              </button>
            )}
            {currentUser.role === UserRole.ADMIN && (
               <button 
                  onClick={() => openEditModal(project)}
                  className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm hover:bg-slate-800 flex items-center gap-2"
               >
                 <Edit size={16} /> 編輯專案
               </button>
            )}
          </div>
        </div>

        {/* Workflow Visualization */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <h3 className="text-lg font-semibold text-slate-800 mb-4">流程與依賴</h3>
           <SimpleDependencyGraph 
              tasks={projectTasks} 
              onTaskClick={canEditTasks ? openEditTaskModal : undefined}
           />
        </div>

        {/* Tasks List */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <div className="flex justify-between items-center mb-4">
             <h3 className="text-lg font-semibold text-slate-800">任務列表</h3>
           </div>
           <div className="overflow-x-auto">
             <table className="w-full text-sm text-left">
               <thead className="bg-slate-50 text-slate-500">
                 <tr>
                   <th className="px-4 py-2">任務</th>
                   <th className="px-4 py-2">負責人</th>
                   <th className="px-4 py-2">日期</th>
                   <th className="px-4 py-2">狀態</th>
                   <th className="px-4 py-2">操作</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {projectTasks.length === 0 ? (
                   <tr><td colSpan={5} className="text-center py-4 text-slate-400">暫無任務</td></tr>
                 ) : (
                   projectTasks.map(t => (
                     <tr key={t.id} className="hover:bg-slate-50 group">
                       <td className="px-4 py-3 font-medium">
                         {t.name}
                         {t.department === currentUser.department && (
                           <span className="ml-2 text-[10px] text-brand-600 bg-brand-50 px-1 rounded border border-brand-100">本部門</span>
                         )}
                       </td>
                       <td className="px-4 py-3 flex items-center gap-2">
                         <img src={users.find(u=>u.id===t.assigneeId)?.avatar} className="w-6 h-6 rounded-full"/>
                         {users.find(u=>u.id===t.assigneeId)?.name.split(' ')[0]}
                       </td>
                       <td className="px-4 py-3 text-slate-500">{t.startDate} - {t.endDate}</td>
                       <td className="px-4 py-3">
                         <span className={`px-2 py-0.5 rounded text-xs ${t.status === TaskStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                           {TASK_STATUS_MAP[t.status]}
                         </span>
                       </td>
                       <td className="px-4 py-3">
                         {(currentUser.role === UserRole.MANAGER && t.department === currentUser.department) || currentUser.role === UserRole.ADMIN ? (
                           <button onClick={() => openEditTaskModal(t)} className="text-slate-400 hover:text-brand-600 opacity-0 group-hover:opacity-100 transition-opacity">
                             <Edit size={14} />
                           </button>
                         ) : null}
                       </td>
                     </tr>
                   ))
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Import Template Modal */}
        {isTemplateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">匯入標準任務流程</h3>
                <button onClick={() => setTemplateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleTemplateSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">選擇流程模板</label>
                  <select 
                    value={templateId} 
                    onChange={e => setTemplateId(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    required
