import React, { useState, useMemo } from 'react';
import { ScheduleEvent, Task, User, UserRole, Project } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Plus, X, Calendar, ChevronLeft, ChevronRight } from 'lucide-react';

interface ScheduleStatsProps {
  events: ScheduleEvent[];
  tasks: Task[];
  users: User[];
  projects: Project[];
  currentUser: User;
  onAddEvent: (event: ScheduleEvent) => void;
}

const ScheduleStats: React.FC<ScheduleStatsProps> = ({ events, tasks, users, projects, currentUser, onAddEvent }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date());

  // Event Form State
  const [title, setTitle] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [relatedProject, setRelatedProject] = useState('');
  const [selectedAttendees, setSelectedAttendees] = useState<string[]>([]);

  const handleAddEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title || !date || !time) return;

    const newEvent: ScheduleEvent = {
      id: `e-${Date.now()}`,
      title,
      date,
      time,
      relatedProjectId: relatedProject || undefined,
      attendees: selectedAttendees
    };

    onAddEvent(newEvent);
    setIsModalOpen(false);
    // Reset form
    setTitle('');
    setDate('');
    setTime('');
    setRelatedProject('');
    setSelectedAttendees([]);
  };

  const toggleAttendee = (userId: string) => {
    if (selectedAttendees.includes(userId)) {
      setSelectedAttendees(selectedAttendees.filter(id => id !== userId));
    } else {
      setSelectedAttendees([...selectedAttendees, userId]);
    }
  };

  // --- Stats Data Prep ---
  const deptData = useMemo(() => {
    const counts: Record<string, number> = {};
    tasks.forEach(t => {
      counts[t.department] = (counts[t.department] || 0) + 1;
    });
    return Object.keys(counts).map(k => ({ name: k, count: counts[k] }));
  }, [tasks]);

  const statusMap: Record<string, string> = {
    'NOT_STARTED': '未開始',
    'IN_PROGRESS': '進行中',
    'COMPLETED': '已完成',
    'OVERDUE': '逾期'
  };

  const statusData = useMemo(() => {
      const counts: Record<string, number> = {};
      tasks.forEach(t => {
          counts[t.status] = (counts[t.status] || 0) + 1;
      });
      return Object.keys(counts).map(k => ({ name: statusMap[k] || k, value: counts[k] }));
  }, [tasks]);

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042'];

  const canAddEvent = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER;

  // --- Calendar Logic ---
  const getStartOfWeek = (d: Date) => {
    const date = new Date(d);
    const day = date.getDay(); // 0 (Sun) to 6 (Sat)
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Adjust to get Monday as start (or 0 for Sun)
    // Let's use Sunday as start of week for this calendar view, or Monday?
    // Let's standard Monday start for work context.
    return new Date(date.setDate(diff));
  };

  const addDays = (d: Date, days: number) => {
    const date = new Date(d);
    date.setDate(date.getDate() + days);
    return date;
  };

  const weekStart = getStartOfWeek(currentDate);
  const weekDays = Array.from({ length: 7 }).map((_, i) => addDays(weekStart, i));

  const formatDate = (d: Date) => d.toISOString().split('T')[0];

  return (
    <div className="space-y-8">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-900">行程與統計</h2>
        {canAddEvent && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增行程
          </button>
        )}
      </div>

      {/* Calendar View */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
        {/* Calendar Header / Nav */}
        <div className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-50">
           <div className="flex items-center gap-4">
              <h3 className="text-lg font-bold text-slate-800">
                {weekStart.getFullYear()}年 {weekStart.getMonth() + 1}月
              </h3>
              <div className="flex bg-white rounded-lg border border-slate-200 shadow-sm">
                <button onClick={() => setCurrentDate(addDays(currentDate, -7))} className="p-1.5 hover:bg-slate-50 text-slate-600 border-r border-slate-200">
                  <ChevronLeft size={18} />
                </button>
                <button onClick={() => setCurrentDate(new Date())} className="px-3 text-xs font-medium hover:bg-slate-50 text-slate-600">
                  今天
                </button>
                <button onClick={() => setCurrentDate(addDays(currentDate, 7))} className="p-1.5 hover:bg-slate-50 text-slate-600 border-l border-slate-200">
                  <ChevronRight size={18} />
                </button>
              </div>
           </div>
        </div>

        {/* Weekly Grid */}
        <div className="grid grid-cols-7 divide-x divide-slate-100 bg-white">
          {weekDays.map((day, i) => {
            const dateStr = formatDate(day);
            const isToday = dateStr === formatDate(new Date());
            const dayEvents = events.filter(e => e.date === dateStr);
            const dayName = day.toLocaleDateString('zh-TW', { weekday: 'short' });

            return (
              <div key={i} className="min-h-[300px] flex flex-col">
                {/* Day Header */}
                <div className={`p-3 text-center border-b border-slate-100 ${isToday ? 'bg-brand-50' : ''}`}>
                   <span className="text-xs text-slate-500 font-medium block uppercase">{dayName}</span>
                   <span className={`text-lg font-bold inline-flex w-8 h-8 items-center justify-center rounded-full mt-1 ${isToday ? 'bg-brand-600 text-white' : 'text-slate-700'}`}>
                     {day.getDate()}
                   </span>
                </div>

                {/* Day Body */}
                <div className="flex-1 p-2 space-y-2 bg-slate-50/30">
                   {dayEvents.map(e => (
                     <div key={e.id} className="bg-white p-2 rounded-lg border border-slate-200 shadow-sm hover:shadow-md transition-shadow cursor-default group">
                        <div className="text-xs font-bold text-brand-700 mb-1">{e.time}</div>
                        <div className="text-sm font-semibold text-slate-800 leading-tight mb-1">{e.title}</div>
                        {e.relatedProjectId && (
                          <div className="text-[10px] text-slate-500 truncate bg-slate-100 px-1 rounded inline-block">
                             {projects.find(p => p.id === e.relatedProjectId)?.name}
                          </div>
                        )}
                        <div className="mt-2 flex -space-x-1 opacity-60 group-hover:opacity-100 transition-opacity">
                            {e.attendees.map(uid => (
                              <img key={uid} src={users.find(u => u.id === uid)?.avatar} className="w-4 h-4 rounded-full border border-white" title={users.find(u => u.id === uid)?.name} />
                            ))}
                        </div>
                     </div>
                   ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Stats Charts */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* Department Workload */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">部門任務分佈</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={deptData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="name" tick={{fontSize: 12}} />
              <YAxis tick={{fontSize: 12}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="count" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Task Status */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">整體專案健康度</h3>
          <ResponsiveContainer width="100%" height="100%">
             <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {statusData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36} />
             </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Add Event Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">新增行程</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleAddEvent} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">行程標題</label>
                <input 
                  type="text" 
                  value={title} 
                  onChange={(e) => setTitle(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="例：專案啟動會議"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">日期</label>
                  <input 
                    type="date" 
                    value={date} 
                    onChange={(e) => setDate(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">時間</label>
                  <input 
                    type="time" 
                    value={time} 
                    onChange={(e) => setTime(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">關聯專案 (選填)</label>
                <select 
                  value={relatedProject} 
                  onChange={(e) => setRelatedProject(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                >
                  <option value="">無</option>
                  {projects.map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">參與人員</label>
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto p-2 border border-slate-200 rounded-lg">
                  {users.map(u => (
                    <label key={u.id} className="flex items-center gap-2 p-1.5 hover:bg-slate-50 rounded cursor-pointer">
                      <input 
                        type="checkbox" 
                        checked={selectedAttendees.includes(u.id)}
                        onChange={() => toggleAttendee(u.id)}
                        className="rounded text-brand-600 focus:ring-brand-500"
                      />
                      <span className="text-sm text-slate-700">{u.name}</span>
                    </label>
                  ))}
                </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button 
                  type="submit" 
                  className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
                >
                  <Calendar size={16} /> 建立行程
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

