// Simple Flowchart Visualization Component using SVG/D3 logic
interface GraphProps {
  tasks: Task[];
  onTaskClick?: (task: Task) => void;
}

const SimpleDependencyGraph: React.FC<GraphProps> = ({ tasks, onTaskClick }) => {
  // Sort tasks roughly by time/id to layout
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  // Basic layout logic: Assign columns based on dependency depth
  const nodes: (Task & { x: number; y: number; col: number })[] = [];
  const links: { source: string; target: string }[] = [];

  const getCol = (taskId: string, currentDepth = 0): number => {
      const task = tasks.find(t => t.id === taskId);
      if(!task) return 0;
      if(!task.dependencies || task.dependencies.length === 0) return 0;
      // Prevent infinite loop if circular dependency exists (basic check)
      if (currentDepth > 20) return 0;
      return Math.max(...task.dependencies.map(d => getCol(d, currentDepth + 1))) + 1;
  };

  sortedTasks.forEach((t, i) => {
    const col = getCol(t.id);
    const siblings = nodes.filter(n => n.col === col);
    // Dynamic layout spacing
    nodes.push({ ...t, col, x: col * 200 + 50, y: siblings.length * 100 + 50 });
    t.dependencies?.forEach(depId => {
       links.push({ source: depId, target: t.id });
    });
  });

  const width = Math.max(800, (Math.max(...nodes.map(n => n.col), 0) + 1) * 220);
  const height = Math.max(300, Math.max(...nodes.map(n => n.y), 0) + 150);

  if (tasks.length === 0) {
    return <div className="p-8 text-center text-slate-400">目前尚無任務流程。請等待部門主管設定任務鏈。</div>;
  }

  return (
    <div className="overflow-x-auto border rounded-lg bg-slate-50 p-4 relative">
      <div className="absolute top-2 right-2 text-xs text-slate-400 flex items-center gap-1 z-10">
        {onTaskClick && <span className="bg-white px-2 py-1 rounded border shadow-sm">💡 點擊方塊可編輯任務</span>}
      </div>
      <svg width={width} height={height}>
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
          </marker>
        </defs>
        {/* Links */}
        {links.map((link, i) => {
           const s = nodes.find(n => n.id === link.source);
           const t = nodes.find(n => n.id === link.target);
           if (!s || !t) return null;
           // Draw curved path
           const path = `M${s.x + 80},${s.y + 25} C${s.x + 130},${s.y + 25} ${t.x - 50},${t.y + 25} ${t.x},${t.y + 25}`;
           return <path key={i} d={path} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />;
        })}
        {/* Nodes */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            transform={`translate(${node.x}, ${node.y})`}
            onClick={() => onTaskClick && onTaskClick(node)}
            style={{ cursor: onTaskClick ? 'pointer' : 'default' }}
            className={onTaskClick ? "hover:opacity-80 transition-opacity group" : ""}
          >
            <rect 
               width="160" 
               height="60" 
               rx="8" 
               fill="white" 
               stroke={node.status === TaskStatus.COMPLETED ? '#22c55e' : node.status === TaskStatus.IN_PROGRESS ? '#3b82f6' : '#e2e8f0'}
               strokeWidth="2"
               className="shadow-sm"
            />
             {/* Hover Effect Border */}
             {onTaskClick && (
              <rect width="160" height="60" rx="8" fill="transparent" stroke="#0ea5e9" strokeWidth="2" className="opacity-0 group-hover:opacity-50" />
            )}

            <text x="80" y="25" textAnchor="middle" className="text-[12px] font-bold fill-slate-700" style={{pointerEvents: 'none'}}>
                {node.name.length > 12 ? node.name.substring(0, 11) + '...' : node.name}
            </text>
            <text x="80" y="45" textAnchor="middle" className="text-[10px] fill-slate-500" style={{pointerEvents: 'none'}}>{node.department}</text>
             <text x="150" y="55" textAnchor="end" className="text-[9px] fill-slate-400" style={{pointerEvents: 'none'}}>{node.startDate}</text>
          </g>
        ))}
      </svg>
    </div>
  );
};

