          </div>
          <div className="flex gap-2">
            {isDeptManager && (
              <button 
                onClick={() => {
                   setTemplateStartDate(new Date().toISOString().split('T')[0]);
                   setTemplateAssignee(currentUser.id);
                   setTemplateModalOpen(true);
                }}
                className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm hover:bg-brand-700 flex items-center gap-2"
              >
                <Workflow size={16} /> 匯入任務流程
              </button>
            )}
            {currentUser.role === UserRole.ADMIN && (
               <button 
                  onClick={() => openEditModal(project)}
                  className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm hover:bg-slate-800 flex items-center gap-2"
               >
                 <Edit size={16} /> 編輯專案
               </button>
            )}
          </div>
        </div>

        {/* Workflow Visualization */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <h3 className="text-lg font-semibold text-slate-800 mb-4">流程與依賴</h3>
           <SimpleDependencyGraph 
              tasks={projectTasks} 
              onTaskClick={canEditTasks ? openEditTaskModal : undefined}
           />
        </div>

        {/* Tasks List */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
           <div className="flex justify-between items-center mb-4">
             <h3 className="text-lg font-semibold text-slate-800">任務列表</h3>
           </div>
           <div className="overflow-x-auto">
             <table className="w-full text-sm text-left">
               <thead className="bg-slate-50 text-slate-500">
                 <tr>
                   <th className="px-4 py-2">任務</th>
                   <th className="px-4 py-2">負責人</th>
                   <th className="px-4 py-2">日期</th>
                   <th className="px-4 py-2">狀態</th>
                   <th className="px-4 py-2">操作</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-slate-100">
                 {projectTasks.length === 0 ? (
                   <tr><td colSpan={5} className="text-center py-4 text-slate-400">暫無任務</td></tr>
                 ) : (
                   projectTasks.map(t => (
                     <tr key={t.id} className="hover:bg-slate-50 group">
                       <td className="px-4 py-3 font-medium">
                         {t.name}
                         {t.department === currentUser.department && (
                           <span className="ml-2 text-[10px] text-brand-600 bg-brand-50 px-1 rounded border border-brand-100">本部門</span>
                         )}
                       </td>
                       <td className="px-4 py-3 flex items-center gap-2">
                         <img src={users.find(u=>u.id===t.assigneeId)?.avatar} className="w-6 h-6 rounded-full"/>
                         {users.find(u=>u.id===t.assigneeId)?.name.split(' ')[0]}
                       </td>
                       <td className="px-4 py-3 text-slate-500">{t.startDate} - {t.endDate}</td>
                       <td className="px-4 py-3">
                         <span className={`px-2 py-0.5 rounded text-xs ${t.status === TaskStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                           {TASK_STATUS_MAP[t.status]}
                         </span>
                       </td>
                       <td className="px-4 py-3">
                         {(currentUser.role === UserRole.MANAGER && t.department === currentUser.department) || currentUser.role === UserRole.ADMIN ? (
                           <button onClick={() => openEditTaskModal(t)} className="text-slate-400 hover:text-brand-600 opacity-0 group-hover:opacity-100 transition-opacity">
                             <Edit size={14} />
                           </button>
                         ) : null}
                       </td>
                     </tr>
                   ))
                 )}
               </tbody>
             </table>
           </div>
        </div>

        {/* Import Template Modal */}
        {isTemplateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">匯入標準任務流程</h3>
                <button onClick={() => setTemplateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleTemplateSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">選擇流程模板</label>
                  <select 
                    value={templateId} 
                    onChange={e => setTemplateId(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    required
                  >
                    <option value="">請選擇...</option>
                    {availableTemplates.map(t => (
                      <option key={t.id} value={t.id}>{t.name} ({t.department})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">流程開始日期</label>
                    <input 
                      type="date"
                      value={templateStartDate}
                      onChange={e => setTemplateStartDate(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                      required
                    />
                  </div>
                   <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">預設負責人</label>
                    <select 
                      value={templateAssignee}
                      onChange={e => setTemplateAssignee(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    >
                      {users.filter(u => u.department === currentUser.department && u.role === UserRole.ENGINEER).map(u => (
                        <option key={u.id} value={u.id}>{u.name}</option>
                      ))}
                      <option value={currentUser.id}>我自己 (主管)</option>
                    </select>
                  </div>
                </div>

                <div className="bg-slate-50 p-3 rounded text-xs text-slate-500 border border-slate-200 mt-2">
                  <p>匯入後，系統將自動建立所有相關任務並設定依賴關係。您可以在列表中點擊編輯按鈕來微調每個任務的日期與負責人。</p>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                  <button type="button" onClick={() => setTemplateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Workflow size={16} /> 確認匯入
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Edit Task Modal (Updated with Dependencies) */}
        {isEditTaskModalOpen && editingTask && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h3 className="text-lg font-bold text-slate-800">調整任務: {editingTask.name}</h3>
                  <p className="text-xs text-slate-400 mt-1">ID: {editingTask.id}</p>
                </div>
                <button onClick={() => setEditTaskModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleEditTaskSubmit} className="space-y-6 overflow-y-auto pr-2">
                 {/* Basic Info */}
                 <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">負責人</label>
                        <select 
                          value={editingTask.assigneeId}
                          onChange={e => setEditingTask({...editingTask, assigneeId: e.target.value})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                          {users.filter(u => u.department === editingTask.department || u.role === UserRole.ENGINEER).map(u => (
                            <option key={u.id} value={u.id}>{u.name} - {u.department}</option>
                          ))}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">狀態</label>
                        <select 
                          value={editingTask.status}
                          onChange={e => setEditingTask({...editingTask, status: e.target.value as TaskStatus})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                           {Object.entries(TASK_STATUS_MAP).map(([key, label]) => (
                             <option key={key} value={key}>{label}</option>
                           ))}
                        </select>
                    </div>
                 </div>

                 {/* Dependencies Section */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
                        <Link size={14} /> 前置任務 (本任務將在以下任務後進行)
                      </label>
                    </div>
                    <div className="space-y-2 max-h-32 overflow-y-auto border border-slate-300 bg-white rounded p-2">
                        {projectTasks
                          .filter(t => t.id !== editingTask.id) // Cannot depend on self
                          .map(t => (
                          <label key={t.id} className="flex items-center gap-2 text-sm p-1 hover:bg-slate-50 rounded cursor-pointer">
                             <input 
                                type="checkbox" 
                                checked={editingTask.dependencies?.includes(t.id)}
                                onChange={() => toggleDependency(t.id)}
                                className="rounded text-brand-600 focus:ring-brand-500"
                             />
                             <span className="flex-1">{t.name} <span className="text-slate-400 text-xs">({t.endDate})</span></span>
                             {editingTask.dependencies?.includes(t.id) && <ArrowRight size={12} className="text-brand-500"/>}
                          </label>
                        ))}
                        {projectTasks.length <= 1 && <div className="text-xs text-slate-400 italic text-center">無其他任務可選</div>}
                    </div>
                    {editingTask.dependencies && editingTask.dependencies.length > 0 && (
                       <p className="text-xs text-brand-600 mt-2 flex items-center gap-1">
                          已選擇 {editingTask.dependencies.length} 個前置任務
                       </p>
                    )}
                 </div>

                 {/* Dates with Auto-Calc */}
                 <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-1">
                       <label className="block text-sm font-medium text-slate-700">開始日期</label>
                       <button 
                         type="button" 
                         onClick={autoSetStartDate}
                         disabled={!editingTask.dependencies?.length}
                         className="text-[10px] bg-brand-50 text-brand-700 px-2 py-0.5 rounded border border-brand-200 flex items-center gap-1 hover:bg-brand-100 disabled:opacity-50 disabled:cursor-not-allowed"
                         title="根據前置任務的結束日期自動推算"
                       >
                         <Wand2 size={10} /> 自動推算
                       </button>
                    </div>
                    <input 
                      type="date"
                      value={editingTask.startDate}
                      onChange={e => setEditingTask({...editingTask, startDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">結束日期</label>
                    <input 
                      type="date"
                      value={editingTask.endDate}
                      onChange={e => setEditingTask({...editingTask, endDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 mt-6 border-t border-slate-100 pt-4">
                  <button type="button" onClick={() => setEditTaskModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700">
                    儲存調整
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Edit Project Modal (Existing) */}
        {isEditModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">編輯專案</h3>
                <button onClick={() => setEditModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleEditSubmit} className="space-y-4">
                {renderFormFields()}

                {/* Status Field (Only for Edit) */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">專案狀態</label>
                  <select 
                    value={formData.status} 
                    onChange={e => setFormData({...formData, status: e.target.value as ProjectStatus})}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                  >
                    {Object.entries(STATUS_CONFIG).map(([key, conf]) => (
                      <option key={key} value={key}>{conf.label}</option>
                    ))}
                  </select>
                </div>

                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setEditModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Save size={16} /> 儲存變更
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- LIST VIEW ---

  // Extract all unique departments from projects for filter
  const filterDepartments = Array.from(new Set(projects.flatMap(p => p.departments))).sort();

  // Filter projects based on selection and view mode
  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      // 1. Department Filter
      const deptMatch = selectedDept === 'ALL' || p.departments.includes(selectedDept);

      // 2. View Mode Filter (All vs Mine)
      let viewMatch = true;
      if (viewFilter === 'MINE') {
        if (currentUser.role === UserRole.MANAGER || currentUser.role === UserRole.ADMIN) {
           // Manager sees projects they manage OR projects where they have tasks
           // But mainly management role
           viewMatch = p.managerId === currentUser.id;
        } else {
           // Engineer sees projects where they have at least one task assigned
           const userTasks = tasks.filter(t => t.projectId === p.id && t.assigneeId === currentUser.id);
           viewMatch = userTasks.length > 0;
        }
      }

      return deptMatch && viewMatch;
    });
  }, [projects, tasks, selectedDept, viewFilter, currentUser]);

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <h2 className="text-2xl font-bold text-slate-900">專案中心</h2>
        {currentUser.role === UserRole.ADMIN && (
          <button 
            onClick={openCreateModal}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增專案
          </button>
        )}
      </div>

      {/* Control Bar: View Mode & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-4 pb-2 flex-shrink-0 bg-white p-3 rounded-xl border border-slate-100 shadow-sm">

        {/* Left: View Mode Toggle */}
        <div className="flex items-center gap-2">
           <div className="flex bg-slate-100 p-1 rounded-lg">
             <button
               onClick={() => setViewFilter('ALL')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'ALL' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <Layers size={16} />
               全部專案
             </button>
             <button
               onClick={() => setViewFilter('MINE')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'MINE' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <UserIcon size={16} />
               {currentUser.role === UserRole.ENGINEER ? '我參與的' : '我負責的'}
             </button>
           </div>

           <div className="h-6 w-px bg-slate-200 mx-2"></div>

           {/* Department Filters */}
           <div className="flex items-center gap-2">
              <span className="text-xs text-slate-400 font-bold uppercase tracking-wider">部門過濾:</span>
              <select 
                value={selectedDept}
                onChange={(e) => setSelectedDept(e.target.value)}
                className="text-sm border-none bg-transparent font-medium text-slate-600 focus:ring-0 cursor-pointer hover:text-slate-900"
              >
                <option value="ALL">全部部門</option>
                {filterDepartments.map(dept => (
                  <option key={dept} value={dept}>{dept}</option>
                ))}
              </select>
           </div>
        </div>

        {/* Right: Legend or Help text */}
        <div className="hidden md:flex items-center gap-3 text-xs text-slate-400">
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-slate-400"></span> 規劃</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-500"></span> 進行</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> 完成</span>
        </div>
      </div>

      {/* Kanban Board Layout */}
      <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
        {filteredProjects.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300 w-full h-40 flex items-center justify-center">
             <div className="flex flex-col items-center gap-2">
                <p className="text-slate-500 font-medium">沒有符合條件的專案。</p>
                <p className="text-xs text-slate-400">請嘗試切換「檢視模式」或「部門過濾器」。</p>
             </div>
          </div>
        ) : (
          <div className="flex gap-4 h-full min-w-max px-1 items-stretch">
            {STATUS_ORDER.map(statusKey => {
              const config = STATUS_CONFIG[statusKey];
              const statusProjects = filteredProjects.filter(p => p.status === statusKey);
              const isCollapsed = collapsedStatuses.includes(statusKey);

              // --- COLLAPSED COLUMN RENDER ---
              if (isCollapsed) {
                return (
                  <div 
                    key={statusKey} 
                    onClick={() => toggleColumn(statusKey)}
                    className={`w-12 flex-shrink-0 flex flex-col items-center bg-slate-50 hover:bg-slate-100 rounded-xl py-4 h-full border border-slate-200 cursor-pointer transition-colors group`}
                    title={`點擊展開 ${config.label}`}
                  >
                     <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-4 ${config.color} border shadow-sm`}>
                        <span className="font-bold text-xs">{statusProjects.length}</span>
                     </div>
                     <div className="flex-1 flex items-center justify-center">
                        <span className="writing-vertical-rl text-sm font-bold text-slate-500 tracking-widest whitespace-nowrap rotate-180 group-hover:text-slate-800 transition-colors">
                           {config.label}
                        </span>
                     </div>
                     <div className="mt-4 text-slate-400 group-hover:text-brand-600">
                        <ChevronRight size={16} />
                     </div>
                  </div>
                );
              }

              // --- EXPANDED COLUMN RENDER ---
              return (
                <div key={statusKey} className="w-80 flex-shrink-0 flex flex-col bg-slate-50/50 rounded-xl p-2 h-full border border-slate-200">
                  {/* Column Header */}
                  <div className={`flex items-center gap-2 mb-3 p-3 rounded-lg border shadow-sm ${config.headerBg} ${config.border} group relative`}>
                     <span className={`w-2.5 h-2.5 rounded-full ${config.dot}`}></span>
                     <h3 className="font-bold text-slate-700 text-sm flex-1">{config.label}</h3>
                     <span className="text-xs font-bold text-slate-500 bg-white/60 px-2 py-0.5 rounded-full">
                        {statusProjects.length}
                     </span>

                     {/* Collapse Button (Visible on hover) */}
                     <button 
                       onClick={(e) => { e.stopPropagation(); toggleColumn(statusKey); }}
                       className="absolute right-10 opacity-0 group-hover:opacity-100 p-1 hover:bg-black/5 rounded text-slate-500 transition-opacity"
                       title="收折欄位"
                     >
                        <ChevronLeft size={14} />
                     </button>
                  </div>

                  {/* Cards Container */}
                  <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                    {statusProjects.length === 0 && (
                      <div className="h-32 border-2 border-dashed border-slate-200 rounded-lg flex flex-col items-center justify-center text-slate-300 gap-2">
                        <div className={`w-2 h-2 rounded-full ${config.dot} opacity-20`}></div>
                        <span className="text-xs">尚無專案</span>
                      </div>
                    )}
                    {statusProjects.map(project => {
                      const pTasks = tasks.filter(t => t.projectId === project.id);
                      const activeCount = pTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
                      const canEditStatus = currentUser.role === UserRole.ADMIN;

                      return (
                        <div key={project.id} onClick={() => navigate(`/projects/${project.id}`)} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:shadow-md hover:border-brand-300 transition-all cursor-pointer group flex flex-col gap-2 relative">
                           {/* Card Top */}
                           <div className="flex justify-between items-start">
                              <span className="text-[10px] font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100 truncate max-w-[120px]">
                                {project.client}
                              </span>
                              <div onClick={(e) => e.stopPropagation()}>
                                <QuickStatusSelector 
                                   project={project}
                                   canEdit={canEditStatus}
                                   onUpdateStatus={(s) => onUpdateProject({...project, status: s})}
                                />
                              </div>
                           </div>

                           {/* Card Main */}
                           <div>
                              <h4 className="font-bold text-slate-800 text-sm leading-snug mb-1 group-hover:text-brand-700 transition-colors">
                                {project.name}
                              </h4>
                              <div className="flex flex-wrap gap-1 mt-1">
                                {project.departments.map(d => (
                                  <span key={d} className="text-[9px] px-1 py-0.5 bg-slate-50 text-slate-500 border border-slate-100 rounded">
                                    {d}
                                  </span>
                                ))}
                              </div>
                           </div>

                           {/* Card Footer */}
                           <div className="flex items-center justify-between text-[10px] text-slate-400 border-t border-slate-50 pt-2 mt-1">
                              <div className="flex items-center gap-1" title="進行中任務">
                                <CheckSquare size={12} className={activeCount > 0 ? "text-brand-500" : ""} />
                                <span>{activeCount}</span>
                              </div>
                              <div className="flex items-center gap-1">
                                <Clock size={12} />
                                <span>{project.endDate}</span>
                              </div>
                           </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Create Project Modal */}
      {isCreateModalOpen && (
