// --- Service Logic ---

export const getProjects = () => PROJECTS;
export const getTasks = () => TASKS;
export const getUsers = () => USERS;
export const getEvents = () => EVENTS;
export const getNotices = () => NOTICES;
export const getAssets = () => ASSETS;
export const getTaskTemplates = () => TASK_TEMPLATES;

export const getTasksByProject = (pid: string) => TASKS.filter(t => t.projectId === pid);
export const getTasksByUser = (uid: string) => TASKS.filter(t => t.assigneeId === uid);

export const getEngineerWorkload = (uid: string): number => {
  return TASKS.filter(t => t.assigneeId === uid && (t.status === TaskStatus.IN_PROGRESS)).length;
};

export const addTask = (task: Task) => {
  TASKS.push(task);
  return task;
};

export const updateTask = (task: Task) => {
  const index = TASKS.findIndex(t => t.id === task.id);
  if (index !== -1) {
    TASKS[index] = task;
  }
};

export const updateTaskStatus = (tid: string, status: TaskStatus) => {
  const t = TASKS.find(task => task.id === tid);
  if (t) t.status = status;
};

export const updateUser = (updatedUser: User) => {
  const index = USERS.findIndex(u => u.id === updatedUser.id);
  if (index !== -1) {
    USERS[index] = updatedUser;
  }
};

export const addProject = (project: Project) => {
  PROJECTS.push(project);
  return project;
};

export const updateProject = (project: Project) => {
  const index = PROJECTS.findIndex(p => p.id === project.id);
  if (index !== -1) {
    PROJECTS[index] = project;
  }
};

export const addEvent = (event: ScheduleEvent) => {
  EVENTS.push(event);
  EVENTS.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
};

export const addNotice = (notice: Notice) => {
  NOTICES.unshift(notice); // Add to top
};

export const updateNotice = (notice: Notice) => {
  const index = NOTICES.findIndex(n => n.id === notice.id);
  if (index !== -1) {
    NOTICES[index] = notice;
  }
};

export const deleteNotice = (id: string) => {
  const index = NOTICES.findIndex(n => n.id === id);
  if (index !== -1) {
    NOTICES.splice(index, 1);
  }
};

export const addTasksFromTemplate = (projectId: string, templateId: string, startDateStr: string, assigneeId: string) => {
  const template = TASK_TEMPLATES.find(t => t.id === templateId);
  if (!template) return;

  let lastTaskId: string | null = null;
  const baseDate = new Date(startDateStr);

  template.steps.forEach((step, index) => {
    // Calculate start date
    const start = new Date(baseDate);
    start.setDate(baseDate.getDate() + step.offsetStart);

    // Calculate end date
    const end = new Date(start);
    end.setDate(start.getDate() + step.durationDays);

    const newTask: Task = {
      id: `t-${Date.now()}-${index}`,
      projectId: projectId,
      name: step.name,
      assigneeId: assigneeId, // Default to manager initially or specific person
      startDate: start.toISOString().split('T')[0],
      endDate: end.toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      department: template.department,
      dependencies: lastTaskId ? [lastTaskId] : [],
      isAdHoc: false
    };

    TASKS.push(newTask);
    lastTaskId = newTask.id; // Chain them sequentially by default
  });
};

export const getUserById = (id: string) => USERS.find(u => u.id === id);
export const getProjectById = (id: string) => PROJECTS.find(p => p.id === id);

export const checkOverdue = (task: Task): boolean => {
    if (task.status === TaskStatus.COMPLETED) return false;
    const end = new Date(task.endDate);
    const now = new Date();
    return end < now;
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ProjectHub from './components/ProjectHub';
import TaskManager from './components/TaskManager';
import ScheduleStats from './components/ScheduleStats';
import AssetBooking from './components/AssetBooking';
import TeamManagement from './components/TeamManagement';
import { 
  getProjects, getTasks, getUsers, getEvents, getNotices, getAssets, 
  getUserById, addTask, updateTaskStatus, updateUser, addEvent, addProject, updateProject,
  addTasksFromTemplate, updateTask, addNotice, updateNotice, deleteNotice
} from './services/mockService';
import { User, Project, Task, ScheduleEvent, Notice, Asset, TaskStatus, UserRole } from './types';

const App: React.FC = () => {
  // Global App State
  const [currentUser, setCurrentUser] = useState<User | undefined>(undefined);
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);

  // Initialization
  useEffect(() => {
    // Load mock data
    const allUsers = getUsers();
    setUsers(allUsers);
    setCurrentUser(allUsers[0]); // Default to Admin
    setProjects(getProjects());
    setTasks(getTasks());
    setEvents(getEvents());
    setNotices(getNotices());
    setAssets(getAssets());
  }, []);

  const handleSwitchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const handleAddTask = (newTask: Task) => {
    addTask(newTask);
    setTasks([...getTasks()]); // Refresh from service
  };

  const handleUpdateTask = (id: string, status: TaskStatus) => {
    updateTaskStatus(id, status);
    setTasks([...getTasks()]); // Refresh
  };

  const handleFullUpdateTask = (task: Task) => {
    updateTask(task);
    setTasks([...getTasks()]);
  };

  const handleUpdateUser = (updatedUser: User) => {
    updateUser(updatedUser);
    setUsers([...getUsers()]); // Refresh
    // If updating current user self
    if (currentUser && currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
    }
  };

  const handleAddProject = (newProject: Project) => {
    addProject(newProject);
    setProjects([...getProjects()]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    updateProject(updatedProject);
    setProjects([...getProjects()]);
  };

  const handleAddEvent = (newEvent: ScheduleEvent) => {
    addEvent(newEvent);
    setEvents([...getEvents()]);
  }

  const handleImportTemplate = (projectId: string, templateId: string, startDate: string, assigneeId: string) => {
    addTasksFromTemplate(projectId, templateId, startDate, assigneeId);
    setTasks([...getTasks()]);
  };

  const handleAddNotice = (notice: Notice) => {
    addNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleUpdateNotice = (notice: Notice) => {
    updateNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleDeleteNotice = (id: string) => {
    deleteNotice(id);
    setNotices([...getNotices()]);
  };

  if (!currentUser) return <div className="flex items-center justify-center h-screen">載入中...</div>;

  return (
    <HashRouter>
      <Layout currentUser={currentUser} onSwitchUser={handleSwitchUser} users={users}>
        <Routes>
          <Route 
            path="/" 
            element={
              <Dashboard 
                user={currentUser} 
                projects={projects} 
                tasks={tasks} 
                events={events} 
                notices={notices} 
                onAddNotice={handleAddNotice}
                onUpdateNotice={handleUpdateNotice}
                onDeleteNotice={handleDeleteNotice}
              />
            } 
          />
          <Route 
            path="/projects" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
              />
            } 
          />
          <Route 
            path="/projects/:id" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
              />
            } 
          />
          <Route path="/tasks" element={<TaskManager tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} />} />
          <Route path="/schedule" element={<ScheduleStats events={events} tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddEvent={handleAddEvent} />} />
          <Route path="/assets" element={<AssetBooking assets={assets} />} />

          {/* Admin Only Route */}
          {currentUser.role === UserRole.ADMIN && (
             <Route path="/team" element={<TeamManagement users={users} onUpdateUser={handleUpdateUser} />} />
          )}

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

