// --- Helper Component: Quick Status Selector ---
interface QuickStatusSelectorProps {
  project: Project;
  canEdit: boolean;
  onUpdateStatus: (newStatus: ProjectStatus) => void;
}

const QuickStatusSelector: React.FC<QuickStatusSelectorProps> = ({ project, canEdit, onUpdateStatus }) => {
  const [isOpen, setIsOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);
  const config = STATUS_CONFIG[project.status];

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (status: ProjectStatus) => {
    onUpdateStatus(status);
    setIsOpen(false);
  };

  return (
    <div className="relative" ref={menuRef} onClick={(e) => e.stopPropagation()}>
      <button
        onClick={() => canEdit && setIsOpen(!isOpen)}
        disabled={!canEdit}
        className={`flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border transition-colors ${config.color} ${canEdit ? 'cursor-pointer' : 'cursor-default'}`}
      >
        <span className={`w-1.5 h-1.5 rounded-full ${config.dot}`} />
        {config.label}
        {canEdit && <ChevronDown size={10} className={`transition-transform ${isOpen ? 'rotate-180' : ''}`} />}
      </button>

      {isOpen && (
        <div className="absolute top-full left-0 mt-2 w-40 bg-white rounded-lg shadow-xl border border-slate-100 z-50 animate-in fade-in zoom-in-95 duration-100 overflow-hidden">
          <div className="py-1">
             <div className="px-3 py-2 text-[10px] font-bold text-slate-400 uppercase tracking-wider bg-slate-50 border-b border-slate-100">
                設定狀態
             </div>
            {Object.entries(STATUS_CONFIG).map(([key, conf]) => (
              <button
                key={key}
                onClick={() => handleSelect(key as ProjectStatus)}
                className={`w-full text-left px-3 py-2 text-xs flex items-center gap-2 hover:bg-slate-50 transition-colors ${project.status === key ? 'bg-slate-50' : ''}`}
              >
                <span className={`w-2 h-2 rounded-full ${conf.dot}`} />
                <span className={`flex-1 font-medium ${project.status === key ? 'text-slate-900' : 'text-slate-600'}`}>{conf.label}</span>
                {project.status === key && <Check size={12} className="text-brand-600" />}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

// --- Gantt Chart Component ---
interface GanttProps {
  tasks: Task[];
  users: User[];
  onTaskClick?: (task: Task) => void;
}

const ProjectGanttChart: React.FC<GanttProps> = ({ tasks, users, onTaskClick }) => {
  if (tasks.length === 0) {
    return <div className="p-12 text-center text-slate-400 border rounded-lg bg-slate-50">此專案目前尚無任務，請先建立任務。</div>;
  }

  // 1. Calculate Date Range
  const dates = tasks.flatMap(t => [new Date(t.startDate), new Date(t.endDate)]);
  if (dates.length === 0) return null;

  const minDate = new Date(Math.min(...dates.map(d => d.getTime())));
  const maxDate = new Date(Math.max(...dates.map(d => d.getTime())));

  // Add padding: 3 days before, 7 days after
  minDate.setDate(minDate.getDate() - 3);
  maxDate.setDate(maxDate.getDate() + 7);

  const totalDays = Math.ceil((maxDate.getTime() - minDate.getTime()) / (1000 * 3600 * 24));

  // Constants
  const DAY_WIDTH = 40;
  const HEADER_HEIGHT = 40;
  const ROW_HEIGHT = 48;
  const LABEL_WIDTH = 200; // Left column for task names

  const chartWidth = totalDays * DAY_WIDTH;
  const chartHeight = tasks.length * ROW_HEIGHT + HEADER_HEIGHT;

  // Helpers
  const getX = (dateStr: string) => {
    const d = new Date(dateStr);
    const diffTime = Math.abs(d.getTime() - minDate.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    return diffDays * DAY_WIDTH;
  };

  const getDurationWidth = (start: string, end: string) => {
    const s = new Date(start);
    const e = new Date(end);
    // Add 1 day to include end date
    const diffDays = Math.ceil((e.getTime() - s.getTime()) / (1000 * 3600 * 24)) + 1; 
    return Math.max(diffDays * DAY_WIDTH, 5); // Min width
  };

  const todayX = getX(new Date().toISOString().split('T')[0]);

  // Sort tasks by start date
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  const daysArray = Array.from({ length: totalDays }, (_, i) => {
      const d = new Date(minDate);
      d.setDate(d.getDate() + i);
      return d;
  });

  return (
    <div className="border rounded-xl bg-white shadow-sm overflow-hidden flex flex-col">
       {/* Legend */}
       <div className="flex items-center gap-4 p-3 border-b border-slate-100 bg-slate-50 text-xs text-slate-600">
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-blue-500"></span> 進行中</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-green-500"></span> 完成</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-slate-300"></span> 未開始</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-red-400"></span> 逾期</div>
       </div>

       <div className="flex overflow-x-auto relative custom-scrollbar">
         {/* Left Column (Sticky) */}
         <div className="sticky left-0 z-20 bg-white border-r border-slate-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]" style={{ width: LABEL_WIDTH, minWidth: LABEL_WIDTH }}>
            {/* Header placeholder */}
            <div className="border-b border-slate-100 bg-slate-50 font-bold text-slate-700 text-xs flex items-center px-4" style={{ height: HEADER_HEIGHT }}>
              任務名稱
            </div>
            {/* Rows */}
            {sortedTasks.map(t => (
               <div key={t.id} className="border-b border-slate-100 flex flex-col justify-center px-4 hover:bg-slate-50 truncate" style={{ height: ROW_HEIGHT }}>
                  <span className="text-sm font-medium text-slate-800 truncate" title={t.name}>{t.name}</span>
                  <span className="text-[10px] text-slate-500 truncate">{users.find(u => u.id === t.assigneeId)?.name}</span>
               </div>
            ))}
         </div>

         {/* Chart Area */}
         <div style={{ width: chartWidth, minWidth: chartWidth }} className="relative bg-white">
            {/* Grid Lines (Vertical) */}
            {daysArray.map((_, i) => (
               <div key={i} className="absolute top-0 bottom-0 border-r border-slate-100" style={{ left: (i + 1) * DAY_WIDTH, width: 0 }} />
            ))}

            {/* Today Line */}
            {todayX >= 0 && todayX <= chartWidth && (
               <div className="absolute top-0 bottom-0 border-l-2 border-red-400 border-dashed z-10 pointer-events-none" style={{ left: todayX }}>
                 <div className="bg-red-500 text-white text-[9px] px-1 py-0.5 absolute top-0 -translate-x-1/2 rounded-b">Today</div>
               </div>
            )}

            {/* Header Dates */}
            <div className="flex border-b border-slate-100 bg-slate-50" style={{ height: HEADER_HEIGHT }}>
               {daysArray.map((d, i) => (
                  <div key={i} className="flex-shrink-0 border-r border-slate-200 flex flex-col items-center justify-center text-[10px] text-slate-600" style={{ width: DAY_WIDTH }}>
                     <span className="font-bold">{d.getDate()}</span>
                     <span className="text-[9px] text-slate-400">{d.getMonth() + 1}月</span>
                  </div>
               ))}
            </div>

            {/* Bars */}
            {sortedTasks.map(t => {
               const startX = getX(t.startDate);
               const width = getDurationWidth(t.startDate, t.endDate);

               let colorClass = 'bg-slate-300';
               if (t.status === TaskStatus.COMPLETED) colorClass = 'bg-green-500';
               else if (t.status === TaskStatus.IN_PROGRESS) colorClass = 'bg-blue-500';
               else if (t.status === TaskStatus.OVERDUE) colorClass = 'bg-red-400';

               return (
                  <div key={t.id} className="border-b border-slate-100 relative group" style={{ height: ROW_HEIGHT }}>
                     <div 
                        onClick={() => onTaskClick && onTaskClick(t)}
                        className={`absolute top-1/2 -translate-y-1/2 h-6 rounded-full shadow-sm cursor-pointer ${colorClass} hover:opacity-90 transition-opacity flex items-center px-2 overflow-hidden`}
                        style={{ left: startX, width: width }}
                        title={`${t.name} (${t.startDate} ~ ${t.endDate})`}
                     >
                        {/* Label inside bar if wide enough */}
                        {width > 60 && <span className="text-[10px] text-white font-medium truncate drop-shadow-md">{t.name}</span>}
                     </div>
                  </div>
               );
            })}
         </div>
       </div>
    </div>
  );
};


// Simple Flowchart Visualization Component using SVG/D3 logic
interface GraphProps {
  tasks: Task[];
  onTaskClick?: (task: Task) => void;
}

const SimpleDependencyGraph: React.FC<GraphProps> = ({ tasks, onTaskClick }) => {
  // Sort tasks roughly by time/id to layout
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  // Basic layout logic: Assign columns based on dependency depth
  const nodes: (Task & { x: number; y: number; col: number })[] = [];
  const links: { source: string; target: string }[] = [];

  const getCol = (taskId: string, currentDepth = 0): number => {
      const task = tasks.find(t => t.id === taskId);
      if(!task) return 0;
      if(!task.dependencies || task.dependencies.length === 0) return 0;
      // Prevent infinite loop if circular dependency exists (basic check)
      if (currentDepth > 20) return 0;
      return Math.max(...task.dependencies.map(d => getCol(d, currentDepth + 1))) + 1;
  };

  sortedTasks.forEach((t, i) => {
    const col = getCol(t.id);
    const siblings = nodes.filter(n => n.col === col);
    // Dynamic layout spacing
    nodes.push({ ...t, col, x: col * 200 + 50, y: siblings.length * 100 + 50 });
    t.dependencies?.forEach(depId => {
       links.push({ source: depId, target: t.id });
    });
  });

  const width = Math.max(800, (Math.max(...nodes.map(n => n.col), 0) + 1) * 220);
  const height = Math.max(300, Math.max(...nodes.map(n => n.y), 0) + 150);

  if (tasks.length === 0) {
    return <div className="p-8 text-center text-slate-400">目前尚無任務流程。請等待部門主管設定任務鏈。</div>;
  }

  return (
    <div className="overflow-x-auto border rounded-lg bg-slate-50 p-4 relative">
      <div className="absolute top-2 right-2 text-xs text-slate-400 flex items-center gap-1 z-10">
        {onTaskClick && <span className="bg-white px-2 py-1 rounded border shadow-sm">💡 點擊方塊可編輯任務</span>}
      </div>
      <svg width={width} height={height}>
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
          </marker>
        </defs>
        {/* Links */}
        {links.map((link, i) => {
           const s = nodes.find(n => n.id === link.source);
           const t = nodes.find(n => n.id === link.target);
           if (!s || !t) return null;
           // Draw curved path
           const path = `M${s.x + 80},${s.y + 25} C${s.x + 130},${s.y + 25} ${t.x - 50},${t.y + 25} ${t.x},${t.y + 25}`;
           return <path key={i} d={path} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />;
        })}
        {/* Nodes */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            transform={`translate(${node.x}, ${node.y})`}
            onClick={() => onTaskClick && onTaskClick(node)}
            style={{ cursor: onTaskClick ? 'pointer' : 'default' }}
            className={onTaskClick ? "hover:opacity-80 transition-opacity group" : ""}
          >
            <rect 
               width="160" 
               height="60" 
               rx="8" 
               fill="white" 
               stroke={node.status === TaskStatus.COMPLETED ? '#22c55e' : node.status === TaskStatus.IN_PROGRESS ? '#3b82f6' : '#e2e8f0'}
               strokeWidth="2"
               className="shadow-sm"
            />
             {/* Hover Effect Border */}
             {onTaskClick && (
              <rect width="160" height="60" rx="8" fill="transparent" stroke="#0ea5e9" strokeWidth="2" className="opacity-0 group-hover:opacity-50" />
            )}

            <text x="80" y="25" textAnchor="middle" className="text-[12px] font-bold fill-slate-700" style={{pointerEvents: 'none'}}>
                {node.name.length > 12 ? node.name.substring(0, 11) + '...' : node.name}
            </text>
            <text x="80" y="45" textAnchor="middle" className="text-[10px] fill-slate-500" style={{pointerEvents: 'none'}}>{node.department}</text>
             <text x="150" y="55" textAnchor="end" className="text-[9px] fill-slate-400" style={{pointerEvents: 'none'}}>{node.startDate}</text>
          </g>
        ))}
      </svg>
    </div>
  );
};

