import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ProjectHub from './components/ProjectHub';
import TaskManager from './components/TaskManager';
import ScheduleStats from './components/ScheduleStats';
import AssetBooking from './components/AssetBooking';
import TeamManagement from './components/TeamManagement';
import { 
  getProjects, getTasks, getUsers, getEvents, getNotices, getAssets, 
  getUserById, addTask, updateTaskStatus, updateUser, addEvent, addProject, updateProject,
  addTasksFromTemplate, updateTask, addNotice, updateNotice, deleteNotice
} from './services/mockService';
import { User, Project, Task, ScheduleEvent, Notice, Asset, TaskStatus, UserRole } from './types';

const App: React.FC = () => {
  // Global App State
  const [currentUser, setCurrentUser] = useState<User | undefined>(undefined);
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);

  // Initialization
  useEffect(() => {
    // Load mock data
    const allUsers = getUsers();
    setUsers(allUsers);
    setCurrentUser(allUsers[0]); // Default to Admin
    setProjects(getProjects());
    setTasks(getTasks());
    setEvents(getEvents());
    setNotices(getNotices());
    setAssets(getAssets());
  }, []);

  const handleSwitchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const handleAddTask = (newTask: Task) => {
    addTask(newTask);
    setTasks([...getTasks()]); // Refresh from service
  };

  const handleUpdateTask = (id: string, status: TaskStatus) => {
    updateTaskStatus(id, status);
    setTasks([...getTasks()]); // Refresh
  };

  const handleFullUpdateTask = (task: Task) => {
    updateTask(task);
    setTasks([...getTasks()]);
  };

  const handleUpdateUser = (updatedUser: User) => {
    updateUser(updatedUser);
    setUsers([...getUsers()]); // Refresh
    // If updating current user self
    if (currentUser && currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
    }
  };

  const handleAddProject = (newProject: Project) => {
    addProject(newProject);
    setProjects([...getProjects()]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    updateProject(updatedProject);
    setProjects([...getProjects()]);
  };

  const handleAddEvent = (newEvent: ScheduleEvent) => {
    addEvent(newEvent);
    setEvents([...getEvents()]);
  }

  const handleImportTemplate = (projectId: string, templateId: string, startDate: string, assigneeId: string) => {
    addTasksFromTemplate(projectId, templateId, startDate, assigneeId);
    setTasks([...getTasks()]);
  };

  const handleAddNotice = (notice: Notice) => {
    addNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleUpdateNotice = (notice: Notice) => {
    updateNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleDeleteNotice = (id: string) => {
    deleteNotice(id);
    setNotices([...getNotices()]);
  };

  if (!currentUser) return <div className="flex items-center justify-center h-screen">載入中...</div>;

  return (
    <HashRouter>
      <Layout currentUser={currentUser} onSwitchUser={handleSwitchUser} users={users}>
        <Routes>
          <Route 
            path="/" 
            element={
              <Dashboard 
                user={currentUser} 
                users={users}
                projects={projects} 
                tasks={tasks} 
                events={events} 
                notices={notices} 
                onAddNotice={handleAddNotice}
                onUpdateNotice={handleUpdateNotice}
                onDeleteNotice={handleDeleteNotice}
              />
            } 
          />
          <Route 
            path="/projects" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
              />
            } 
          />
          <Route 
            path="/projects/:id" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
              />
            } 
          />
          <Route path="/tasks" element={<TaskManager tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} />} />
          <Route path="/schedule" element={<ScheduleStats events={events} tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddEvent={handleAddEvent} />} />
          <Route path="/assets" element={<AssetBooking assets={assets} />} />

          {/* Admin Only Route */}
          {currentUser.role === UserRole.ADMIN && (
             <Route path="/team" element={<TeamManagement users={users} onUpdateUser={handleUpdateUser} />} />
          )}

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

