                 <th className="px-6 py-3">操作</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {projects.map(p => {
                 const pTasks = tasks.filter(t => t.projectId === p.id);
                 const completed = pTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
                 const progress = pTasks.length > 0 ? Math.round((completed / pTasks.length) * 100) : 0;
                 return (
                   <tr key={p.id} className="hover:bg-slate-50">
                     <td className="px-6 py-4 font-medium text-slate-800">{p.name}</td>
                     <td className="px-6 py-4 text-slate-500">{p.client}</td>
                     <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold
                          ${p.status === ProjectStatus.IN_PROGRESS ? 'bg-blue-100 text-blue-700' : 
                            p.status === ProjectStatus.COMPLETED ? 'bg-green-100 text-green-700' : 
                            'bg-slate-100 text-slate-700'}`}>
                          {PROJECT_STATUS_MAP[p.status] || p.status}
                        </span>
                     </td>
                     <td className="px-6 py-4">
                       <div className="w-full bg-slate-200 rounded-full h-2">
                         <div className="bg-brand-500 h-2 rounded-full" style={{ width: `${progress}%` }}></div>
                       </div>
                       <span className="text-xs text-slate-400 mt-1 block">{progress}% 完成</span>
                     </td>
                     <td className="px-6 py-4">
                       <button onClick={() => navigate(`/projects/${p.id}`)} className="text-brand-600 hover:underline">查看</button>
                     </td>
                   </tr>
                 )
               })}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );

  const renderManagerView = () => {
    // Logic for Team Status
    const deptEngineers = users.filter(u => u.department === user.department && u.role !== UserRole.ADMIN);

    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Department Overview */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">{user.department} 概覽</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                <span className="text-slate-600">進行中任務</span>
                <span className="font-bold text-slate-900">{deptTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length}</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-red-50 rounded-lg">
                <span className="text-red-600">逾期任務</span>
                <span className="font-bold text-red-700">{deptTasks.filter(t => checkOverdue(t)).length}</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-blue-50 rounded-lg">
                <span className="text-blue-600">參與專案</span>
                <span className="font-bold text-blue-700">
                  {projects.filter(p => p.departments.includes(user.department) && p.status === ProjectStatus.IN_PROGRESS).length}
                </span>
              </div>
            </div>
          </div>

          {/* Engineer Workload Visualization */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-slate-800">工程師負載監控</h3>
              <span className="text-xs bg-slate-100 text-slate-500 px-2 py-1 rounded">
                共 {deptEngineers.length} 人
              </span>
            </div>

            <div className="space-y-4 flex-1 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
               {deptEngineers.map(engineer => {
                 const engTasks = tasks.filter(t => t.assigneeId === engineer.id && t.status !== TaskStatus.COMPLETED);
                 const activeCount = engTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
                 const notStartedCount = engTasks.filter(t => t.status === TaskStatus.NOT_STARTED).length;
                 const overdueCount = engTasks.filter(t => checkOverdue(t)).length;

                 // Determine Load Status
                 let statusColor = 'bg-green-500';
                 let statusText = '空閒';
                 const totalLoad = activeCount + (notStartedCount * 0.5); // Weight active tasks more

                 if (overdueCount > 0) {
                   statusColor = 'bg-red-500';
                   statusText = '警示';
                 } else if (totalLoad > 3) {
                   statusColor = 'bg-red-400';
                   statusText = '高負載';
                 } else if (totalLoad >= 2) {
                   statusColor = 'bg-amber-400';
                   statusText = '忙碌';
                 }

                 return (
                   <div key={engineer.id} className="p-3 bg-slate-50 rounded-lg border border-slate-100 group">
                      <div className="flex items-center justify-between mb-2">
                         <div className="flex items-center gap-2">
                            <div className="relative">
                              <img src={engineer.avatar} className="w-8 h-8 rounded-full bg-slate-200" alt={engineer.name} />
                              <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white ${statusColor}`}></div>
                            </div>
                            <div>
                               <p className="text-sm font-bold text-slate-700">{engineer.name}</p>
                               <p className="text-[10px] text-slate-400">{statusText}</p>
                            </div>
                         </div>
                         <div className="text-right">
                            <span className="text-xl font-bold text-slate-800">{activeCount + notStartedCount}</span>
                            <span className="text-[10px] text-slate-400 block">待辦</span>
                         </div>
                      </div>

                      {/* Progress Bar Visual */}
                      <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden flex mb-2">
                         <div className="bg-red-500 h-full" style={{ width: `${(overdueCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-blue-500 h-full" style={{ width: `${(activeCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-slate-400 h-full" style={{ width: `${(notStartedCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                      </div>

                      {/* Detail Badges */}
                      <div className="flex gap-2 text-[10px]">
                         {activeCount > 0 && <span className="bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">進行 {activeCount}</span>}
                         {overdueCount > 0 && <span className="bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1"><AlertTriangle size={8}/> 逾期 {overdueCount}</span>}
                         {notStartedCount > 0 && <span className="bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">未開始 {notStartedCount}</span>}
                         {activeCount + notStartedCount + overdueCount === 0 && <span className="text-slate-400 italic">目前無任務</span>}
                      </div>
                   </div>
                 );
               })}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderEngineerView = () => (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">我的優先任務</h3>
        {myTasks.length === 0 ? (
          <p className="text-slate-500 text-center py-8">目前沒有指派的進行中任務。</p>
        ) : (
          <div className="space-y-3">
            {myTasks
              .sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime())
              .map(task => {
              const isOverdue = checkOverdue(task);
              return (
                <div key={task.id} className={`p-4 rounded-lg border-l-4 flex justify-between items-center ${isOverdue ? 'bg-red-50 border-red-500' : 'bg-slate-50 border-brand-500'}`}>
                   <div>
                     <h4 className="font-medium text-slate-800">{task.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">期限: {task.endDate}</p>
                   </div>
                   <div className="flex items-center gap-2">
                     <span className={`text-xs px-2 py-1 rounded font-medium ${
                       task.status === TaskStatus.COMPLETED ? 'bg-green-200 text-green-800' :
                       task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-200 text-blue-800' :
                       'bg-slate-200 text-slate-800'
                     }`}>{TASK_STATUS_MAP[task.status] || task.status}</span>
                   </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Left Column (Main Content) */}
      <div className="lg:col-span-2 space-y-8">
        {user.role === UserRole.ADMIN && renderAdminView()}
        {user.role === UserRole.MANAGER && renderManagerView()}
        {user.role === UserRole.ENGINEER && renderEngineerView()}
      </div>

      {/* Right Column (Sidebar Widgets) */}
      <div className="space-y-8">

        {/* Schedule */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
          <div className="flex items-center gap-2 mb-4">
             <Calendar className="text-brand-600" size={20} />
             <h3 className="font-semibold text-slate-800">未來 7 天</h3>
          </div>
          <div className="space-y-4">
            {upcomingEvents.length > 0 ? upcomingEvents.map(e => (
              <div key={e.id} className="flex gap-3">
                 <div className="flex flex-col items-center min-w-[3rem] bg-slate-50 rounded p-1">
                   <span className="text-xs font-bold text-slate-500">{new Date(e.date).toLocaleDateString('zh-TW', { month: 'short' })}</span>
                   <span className="text-lg font-bold text-slate-800">{new Date(e.date).getDate()}</span>
                 </div>
                 <div>
                   <h4 className="text-sm font-medium text-slate-900">{e.title}</h4>
                   <p className="text-xs text-slate-500">{e.time} • {projects.find(p=>p.id===e.relatedProjectId)?.name ?? '一般事項'}</p>
                 </div>
              </div>
            )) : <p className="text-sm text-slate-400">無即將到來的行程。</p>}
          </div>
        </div>

        {/* Notices */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
           <div className="flex items-center justify-between mb-4">
             <div className="flex items-center gap-2">
               <Megaphone className="text-amber-500" size={20} />
               <h3 className="font-semibold text-slate-800">公告</h3>
             </div>
             {canManageNotices && (
               <button 
                 onClick={() => handleOpenNoticeModal()}
                 className="p-1 text-slate-400 hover:text-brand-600 hover:bg-slate-50 rounded transition-colors"
                 title="發布新公告"
               >
                 <Plus size={18} />
               </button>
             )}
          </div>
          <ul className="space-y-3">
            {notices.map(n => (
              <li key={n.id} className="text-sm group relative">
                <div className="flex items-start justify-between">
                  <div className="flex-1 pr-6">
                    <span className={`uppercase text-[10px] font-bold px-1.5 py-0.5 rounded mr-2 ${n.type === 'SYSTEM' ? 'bg-slate-200 text-slate-700' : 'bg-amber-100 text-amber-700'}`}>
                      {n.type === 'SYSTEM' ? '系統' : '公告'}
                    </span>
                    <span className="text-slate-700 font-medium">{n.title}</span>
                    <p className="text-xs text-slate-500 mt-1 ml-1 pl-2 border-l-2 border-slate-200">{n.content}</p>
                    <p className="text-[10px] text-slate-300 mt-1 text-right">{n.date}</p>
                  </div>

                  {canManageNotices && (
                    <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity absolute top-0 right-0 bg-white shadow-sm border rounded p-1">
                      <button onClick={() => handleOpenNoticeModal(n)} className="text-slate-400 hover:text-brand-600"><Edit size={14}/></button>
                      <button onClick={() => handleDeleteClick(n.id)} className="text-slate-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                  )}
                </div>
              </li>
            ))}
            {notices.length === 0 && <li className="text-center text-slate-400 text-xs py-2">目前沒有公告</li>}
          </ul>
        </div>
      </div>

      {/* Notice Modal */}
      {isNoticeModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">
                {editingNotice ? '編輯公告' : '發布新公告'}
              </h3>
              <button onClick={() => setIsNoticeModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleNoticeSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">標題</label>
                <input 
                  type="text" 
                  value={noticeForm.title} 
                  onChange={(e) => setNoticeForm({...noticeForm, title: e.target.value})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入公告標題..."
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">類型</label>
                <select 
                  value={noticeForm.type}
                  onChange={(e) => setNoticeForm({...noticeForm, type: e.target.value as 'SYSTEM' | 'ANNOUNCEMENT'})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                >
                  <option value="ANNOUNCEMENT">一般公告 (Announcement)</option>
                  <option value="SYSTEM">系統通知 (System)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">內容</label>
                <textarea 
                  rows={4}
                  value={noticeForm.content} 
                  onChange={(e) => setNoticeForm({...noticeForm, content: e.target.value})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入公告內容..."
                  required
                />
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => setIsNoticeModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button 
                  type="submit" 
                  className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
                >
                  <Save size={16} /> {editingNotice ? '儲存變更' : '發布'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useMemo, useState } from 'react';
import { User, UserRole, Project, Task, ScheduleEvent, Notice, TaskStatus, ProjectStatus } from '../types';
import { AlertCircle, Clock, Calendar, Megaphone, CheckCircle2, Plus, Edit, Trash2, X, Save, BarChart3, AlertTriangle } from 'lucide-react';
import { checkOverdue } from '../services/mockService';
import { useNavigate } from 'react-router-dom';

interface DashboardProps {
  user: User;
  users: User[];
  projects: Project[];
  tasks: Task[];
  events: ScheduleEvent[];
  notices: Notice[];
  onAddNotice: (notice: Notice) => void;
  onUpdateNotice: (notice: Notice) => void;
  onDeleteNotice: (id: string) => void;
}

const PROJECT_STATUS_MAP: Record<string, string> = {
  [ProjectStatus.PLANNING]: '規劃中',
  [ProjectStatus.QUOTE_NEEDED]: '須報價',
  [ProjectStatus.QUOTED]: '已報價',
  [ProjectStatus.IN_PROGRESS]: '進行中',
  [ProjectStatus.ACCEPTANCE]: '驗收中',
  [ProjectStatus.COMPLETED]: '完成',
  [ProjectStatus.CANCELLED]: '取消',
};

const TASK_STATUS_MAP: Record<string, string> = {
  [TaskStatus.NOT_STARTED]: '未開始',
  [TaskStatus.IN_PROGRESS]: '進行中',
  [TaskStatus.COMPLETED]: '完成',
  [TaskStatus.OVERDUE]: '逾期',
};

const Dashboard: React.FC<DashboardProps> = ({ user, users, projects, tasks, events, notices, onAddNotice, onUpdateNotice, onDeleteNotice }) => {
  const navigate = useNavigate();

  // Notice State
  const [isNoticeModalOpen, setIsNoticeModalOpen] = useState(false);
  const [editingNotice, setEditingNotice] = useState<Notice | null>(null);
  const [noticeForm, setNoticeForm] = useState<{title: string, content: string, type: 'SYSTEM' | 'ANNOUNCEMENT'}>({
    title: '', content: '', type: 'ANNOUNCEMENT'
  });

  // Permissions
  const canManageNotices = user.role === UserRole.ADMIN || user.role === UserRole.MANAGER;

  const handleOpenNoticeModal = (notice?: Notice) => {
    if (notice) {
      setEditingNotice(notice);
      setNoticeForm({
        title: notice.title,
        content: notice.content,
        type: notice.type
      });
    } else {
      setEditingNotice(null);
      setNoticeForm({ title: '', content: '', type: 'ANNOUNCEMENT' });
    }
    setIsNoticeModalOpen(true);
  };

  const handleNoticeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingNotice) {
      onUpdateNotice({
        ...editingNotice,
        ...noticeForm
      });
    } else {
      onAddNotice({
        id: `n-${Date.now()}`,
        date: new Date().toISOString().split('T')[0],
        ...noticeForm
      });
    }
    setIsNoticeModalOpen(false);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('確定要刪除此公告嗎？')) {
      onDeleteNotice(id);
    }
  };


  // Derived State
  const myTasks = useMemo(() => tasks.filter(t => t.assigneeId === user.id), [tasks, user.id]);
  const overdueTasks = useMemo(() => tasks.filter(t => checkOverdue(t) && t.status !== TaskStatus.COMPLETED), [tasks]);
  const deptTasks = useMemo(() => tasks.filter(t => t.department === user.department), [tasks, user.department]);

  const upcomingEvents = useMemo(() => {
    // Simple mock filter for "next week"
    return events.slice(0, 5);
  }, [events]);

  const renderAdminView = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-slate-500 text-sm font-medium mb-2">專案總數</h3>
          <p className="text-3xl font-bold text-slate-800">{projects.length}</p>
          <div className="mt-4 flex gap-2">
            <span className="px-2 py-1 bg-green-100 text-green-700 text-xs rounded-full">
              {projects.filter(p => p.status === ProjectStatus.IN_PROGRESS).length} 進行中
            </span>
            <span className="px-2 py-1 bg-amber-100 text-amber-700 text-xs rounded-full">
              {projects.filter(p => p.status === ProjectStatus.PLANNING).length} 規劃中
            </span>
          </div>
        </div>

        {/* Clickable Severe Issues Card */}
        <div 
          onClick={() => navigate('/tasks?filter=overdue')}
          className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 cursor-pointer hover:shadow-md hover:border-red-200 transition-all group relative overflow-hidden"
        >
          <div className="absolute right-0 top-0 w-20 h-20 bg-red-50 rounded-bl-full -mr-10 -mt-10 transition-transform group-hover:scale-110"></div>
          <div className="relative z-10">
            <h3 className="text-slate-500 text-sm font-medium mb-2 group-hover:text-red-600 transition-colors flex items-center gap-2">
               嚴重問題 <AlertTriangle size={14} className="opacity-0 group-hover:opacity-100 text-red-500 transition-opacity" />
            </h3>
            <p className="text-3xl font-bold text-red-600 group-hover:text-red-700">{overdueTasks.length}</p>
            <p className="text-xs text-slate-400 mt-1 group-hover:text-red-400">跨部門逾期任務 (點擊查看)</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-slate-500 text-sm font-medium mb-2">即將到期</h3>
          <p className="text-3xl font-bold text-brand-600">
            {tasks.filter(t => {
               const diff = new Date(t.endDate).getTime() - new Date().getTime();
               return diff > 0 && diff < 7 * 24 * 60 * 60 * 1000;
            }).length}
          </p>
          <p className="text-xs text-slate-400 mt-1">7天內到期任務</p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
         <div className="p-6 border-b border-slate-100">
           <h3 className="text-lg font-semibold text-slate-800">專案快照</h3>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-sm text-left">
             <thead className="bg-slate-50 text-slate-500 font-medium">
               <tr>
                 <th className="px-6 py-3">專案名稱</th>
                 <th className="px-6 py-3">客戶</th>
                 <th className="px-6 py-3">狀態</th>
                 <th className="px-6 py-3">進度</th>
                 <th className="px-6 py-3">操作</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {projects.map(p => {
                 const pTasks = tasks.filter(t => t.projectId === p.id);
                 const completed = pTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
                 const progress = pTasks.length > 0 ? Math.round((completed / pTasks.length) * 100) : 0;
                 return (
                   <tr key={p.id} className="hover:bg-slate-50">
                     <td className="px-6 py-4 font-medium text-slate-800">{p.name}</td>
                     <td className="px-6 py-4 text-slate-500">{p.client}</td>
                     <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold
                          ${p.status === ProjectStatus.IN_PROGRESS ? 'bg-blue-100 text-blue-700' : 
                            p.status === ProjectStatus.COMPLETED ? 'bg-green-100 text-green-700' : 
                            'bg-slate-100 text-slate-700'}`}>
                          {PROJECT_STATUS_MAP[p.status] || p.status}
                        </span>
                     </td>
                     <td className="px-6 py-4">
                       <div className="w-full bg-slate-200 rounded-full h-2">
                         <div className="bg-brand-500 h-2 rounded-full" style={{ width: `${progress}%` }}></div>
                       </div>
                       <span className="text-xs text-slate-400 mt-1 block">{progress}% 完成</span>
                     </td>
                     <td className="px-6 py-4">
                       <button onClick={() => navigate(`/projects/${p.id}`)} className="text-brand-600 hover:underline">查看</button>
                     </td>
                   </tr>
                 )
               })}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );

  const renderManagerView = () => {
    // Logic for Team Status
    const deptEngineers = users.filter(u => u.department === user.department && u.role !== UserRole.ADMIN);

    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Department Overview */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">{user.department} 概覽</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                <span className="text-slate-600">進行中任務</span>
                <span className="font-bold text-slate-900">{deptTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length}</span>
              </div>
              <div 
                 onClick={() => navigate('/tasks?filter=overdue')}
                 className="flex justify-between items-center p-3 bg-red-50 rounded-lg cursor-pointer hover:bg-red-100 transition-colors"
              >
                <span className="text-red-600 font-medium flex items-center gap-1"><AlertTriangle size={14}/> 逾期任務</span>
                <span className="font-bold text-red-700">{deptTasks.filter(t => checkOverdue(t)).length}</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-blue-50 rounded-lg">
                <span className="text-blue-600">參與專案</span>
                <span className="font-bold text-blue-700">
                  {projects.filter(p => p.departments.includes(user.department) && p.status === ProjectStatus.IN_PROGRESS).length}
                </span>
              </div>
            </div>
          </div>

          {/* Engineer Workload Visualization */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-slate-800">工程師負載監控</h3>
              <span className="text-xs bg-slate-100 text-slate-500 px-2 py-1 rounded">
                共 {deptEngineers.length} 人
              </span>
            </div>

            <div className="space-y-4 flex-1 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
               {deptEngineers.map(engineer => {
                 const engTasks = tasks.filter(t => t.assigneeId === engineer.id && t.status !== TaskStatus.COMPLETED);
                 const activeCount = engTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
                 const notStartedCount = engTasks.filter(t => t.status === TaskStatus.NOT_STARTED).length;
                 const overdueCount = engTasks.filter(t => checkOverdue(t)).length;

                 // Determine Load Status
                 let statusColor = 'bg-green-500';
                 let statusText = '空閒';
                 const totalLoad = activeCount + (notStartedCount * 0.5); // Weight active tasks more

                 if (overdueCount > 0) {
                   statusColor = 'bg-red-500';
                   statusText = '警示';
                 } else if (totalLoad > 3) {
                   statusColor = 'bg-red-400';
                   statusText = '高負載';
                 } else if (totalLoad >= 2) {
                   statusColor = 'bg-amber-400';
                   statusText = '忙碌';
                 }

                 return (
                   <div key={engineer.id} className="p-3 bg-slate-50 rounded-lg border border-slate-100 group">
                      <div className="flex items-center justify-between mb-2">
                         <div className="flex items-center gap-2">
                            <div className="relative">
                              <img src={engineer.avatar} className="w-8 h-8 rounded-full bg-slate-200" alt={engineer.name} />
                              <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white ${statusColor}`}></div>
                            </div>
                            <div>
                               <p className="text-sm font-bold text-slate-700">{engineer.name}</p>
                               <p className="text-[10px] text-slate-400">{statusText}</p>
                            </div>
                         </div>
                         <div className="text-right">
                            <span className="text-xl font-bold text-slate-800">{activeCount + notStartedCount}</span>
                            <span className="text-[10px] text-slate-400 block">待辦</span>
                         </div>
                      </div>

                      {/* Progress Bar Visual */}
                      <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden flex mb-2">
                         <div className="bg-red-500 h-full" style={{ width: `${(overdueCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-blue-500 h-full" style={{ width: `${(activeCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-slate-400 h-full" style={{ width: `${(notStartedCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                      </div>

                      {/* Detail Badges */}
                      <div className="flex gap-2 text-[10px]">
                         {activeCount > 0 && <span className="bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">進行 {activeCount}</span>}
                         {overdueCount > 0 && <span className="bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1"><AlertTriangle size={8}/> 逾期 {overdueCount}</span>}
                         {notStartedCount > 0 && <span className="bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">未開始 {notStartedCount}</span>}
                         {activeCount + notStartedCount + overdueCount === 0 && <span className="text-slate-400 italic">目前無任務</span>}
                      </div>
                   </div>
                 );
               })}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderEngineerView = () => (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">我的優先任務</h3>
        {myTasks.length === 0 ? (
          <p className="text-slate-500 text-center py-8">目前沒有指派的進行中任務。</p>
        ) : (
          <div className="space-y-3">
            {myTasks
              .sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime())
              .map(task => {
              const isOverdue = checkOverdue(task);
              return (
                <div key={task.id} className={`p-4 rounded-lg border-l-4 flex justify-between items-center ${isOverdue ? 'bg-red-50 border-red-500' : 'bg-slate-50 border-brand-500'}`}>
                   <div>
                     <h4 className="font-medium text-slate-800">{task.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">期限: {task.endDate}</p>
                   </div>
                   <div className="flex items-center gap-2">
                     <span className={`text-xs px-2 py-1 rounded font-medium ${
                       task.status === TaskStatus.COMPLETED ? 'bg-green-200 text-green-800' :
                       task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-200 text-blue-800' :
                       'bg-slate-200 text-slate-800'
                     }`}>{TASK_STATUS_MAP[task.status] || task.status}</span>
                   </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Left Column (Main Content) */}
      <div className="lg:col-span-2 space-y-8">
        {user.role === UserRole.ADMIN && renderAdminView()}
        {user.role === UserRole.MANAGER && renderManagerView()}
        {user.role === UserRole.ENGINEER && renderEngineerView()}
      </div>

      {/* Right Column (Sidebar Widgets) */}
      <div className="space-y-8">

        {/* Schedule */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
          <div className="flex items-center gap-2 mb-4">
             <Calendar className="text-brand-600" size={20} />
             <h3 className="font-semibold text-slate-800">未來 7 天</h3>
          </div>
          <div className="space-y-4">
            {upcomingEvents.length > 0 ? upcomingEvents.map(e => (
              <div key={e.id} className="flex gap-3">
                 <div className="flex flex-col items-center min-w-[3rem] bg-slate-50 rounded p-1">
                   <span className="text-xs font-bold text-slate-500">{new Date(e.date).toLocaleDateString('zh-TW', { month: 'short' })}</span>
                   <span className="text-lg font-bold text-slate-800">{new Date(e.date).getDate()}</span>
                 </div>
                 <div>
                   <h4 className="text-sm font-medium text-slate-900">{e.title}</h4>
                   <p className="text-xs text-slate-500">{e.time} • {projects.find(p=>p.id===e.relatedProjectId)?.name ?? '一般事項'}</p>
                 </div>
              </div>
            )) : <p className="text-sm text-slate-400">無即將到來的行程。</p>}
          </div>
        </div>

        {/* Notices */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
           <div className="flex items-center justify-between mb-4">
             <div className="flex items-center gap-2">
               <Megaphone className="text-amber-500" size={20} />
               <h3 className="font-semibold text-slate-800">公告</h3>
             </div>
             {canManageNotices && (
               <button 
                 onClick={() => handleOpenNoticeModal()}
                 className="p-1 text-slate-400 hover:text-brand-600 hover:bg-slate-50 rounded transition-colors"
                 title="發布新公告"
               >
                 <Plus size={18} />
               </button>
             )}
          </div>
          <ul className="space-y-3">
            {notices.map(n => (
              <li key={n.id} className="text-sm group relative">
                <div className="flex items-start justify-between">
                  <div className="flex-1 pr-6">
                    <span className={`uppercase text-[10px] font-bold px-1.5 py-0.5 rounded mr-2 ${n.type === 'SYSTEM' ? 'bg-slate-200 text-slate-700' : 'bg-amber-100 text-amber-700'}`}>
                      {n.type === 'SYSTEM' ? '系統' : '公告'}
                    </span>
                    <span className="text-slate-700 font-medium">{n.title}</span>
                    <p className="text-xs text-slate-500 mt-1 ml-1 pl-2 border-l-2 border-slate-200">{n.content}</p>
                    <p className="text-[10px] text-slate-300 mt-1 text-right">{n.date}</p>
                  </div>

                  {canManageNotices && (
                    <div className="flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity absolute top-0 right-0 bg-white shadow-sm border rounded p-1">
                      <button onClick={() => handleOpenNoticeModal(n)} className="text-slate-400 hover:text-brand-600"><Edit size={14}/></button>
                      <button onClick={() => handleDeleteClick(n.id)} className="text-slate-400 hover:text-red-600"><Trash2 size={14}/></button>
                    </div>
                  )}
                </div>
              </li>
            ))}
            {notices.length === 0 && <li className="text-center text-slate-400 text-xs py-2">目前沒有公告</li>}
          </ul>
        </div>
      </div>

      {/* Notice Modal */}
      {isNoticeModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
             <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">
                {editingNotice ? '編輯公告' : '發布新公告'}
              </h3>
              <button onClick={() => setIsNoticeModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleNoticeSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">標題</label>
                <input 
                  type="text" 
                  value={noticeForm.title} 
                  onChange={(e) => setNoticeForm({...noticeForm, title: e.target.value})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入公告標題..."
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">類型</label>
                <select 
                  value={noticeForm.type}
                  onChange={(e) => setNoticeForm({...noticeForm, type: e.target.value as 'SYSTEM' | 'ANNOUNCEMENT'})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                >
                  <option value="ANNOUNCEMENT">一般公告 (Announcement)</option>
                  <option value="SYSTEM">系統通知 (System)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">內容</label>
                <textarea 
                  rows={4}
                  value={noticeForm.content} 
                  onChange={(e) => setNoticeForm({...noticeForm, content: e.target.value})}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入公告內容..."
                  required
                />
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => setIsNoticeModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button 
                  type="submit" 
                  className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
                >
                  <Save size={16} /> {editingNotice ? '儲存變更' : '發布'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Task, User, UserRole, TaskStatus, Project } from '../types';
import { getEngineerWorkload, checkOverdue } from '../services/mockService';
import { AlertTriangle, Plus, X, AlertCircle, Filter, Clock } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router-dom';

interface TaskManagerProps {
  tasks: Task[];
  users: User[];
  projects: Project[];
  currentUser: User;
  onAddTask: (task: Task) => void;
  onUpdateTask: (id: string, status: TaskStatus) => void;
}

const TaskManager: React.FC<TaskManagerProps> = ({ tasks, users, projects, currentUser, onAddTask, onUpdateTask }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  // Filter State
  const [filterDept, setFilterDept] = useState<string>('');
  const [filterProject, setFilterProject] = useState<string>('');
  const [filterAssignee, setFilterAssignee] = useState<string>('');
  const [showOverdueOnly, setShowOverdueOnly] = useState(false);

  // Parse Query Params for automatic filtering
  useEffect(() => {
    const params = new URLSearchParams(location.search);
    if (params.get('filter') === 'overdue') {
      setShowOverdueOnly(true);
    } else {
      setShowOverdueOnly(false);
    }
  }, [location.search]);

  // Form State
  const [newTaskName, setNewTaskName] = useState('');
  const [selectedEng, setSelectedEng] = useState('');
  const [selectedProject, setSelectedProject] = useState('');
  const [isAdHoc, setIsAdHoc] = useState(false);
  const [warningMsg, setWarningMsg] = useState<string | null>(null);

  // Derived Options for Filtering
  const uniqueDepts = useMemo(() => Array.from(new Set(users.map(u => u.department))).sort(), [users]);

  const filteredProjects = useMemo(() => {
    if (!filterDept) return projects;
    // Show projects that have at least one department match
    return projects.filter(p => p.departments.includes(filterDept));
  }, [projects, filterDept]);

  const filteredUsers = useMemo(() => {
    let result = users;
    if (filterDept) {
      result = result.filter(u => u.department === filterDept);
    }
    return result;
  }, [users, filterDept]);

  // Derived Visible Tasks
  const visibleTasks = useMemo(() => {
    let result = tasks;

    // Engineer only sees own tasks usually, but let's allow them to see others if they want, 
    // or restrict if strict mode. For this requirement, we implement the requested filter.
    // If we want to strictly follow "Engineer sees own tasks", we should lock the assignee filter to currentUser.id
    if (currentUser.role === UserRole.ENGINEER) {
       result = result.filter(t => t.assigneeId === currentUser.id);
    } else {
       // Apply hierarchical filters for Admin/Manager
       if (filterDept) {
         // Filter tasks where the assignee is in the selected department
         // OR the task itself is marked with that department
         const deptUserIds = users.filter(u => u.department === filterDept).map(u => u.id);
         result = result.filter(t => t.department === filterDept || deptUserIds.includes(t.assigneeId));
       }
       if (filterProject) {
         result = result.filter(t => t.projectId === filterProject);
       }
       if (filterAssignee) {
         result = result.filter(t => t.assigneeId === filterAssignee);
       }
    }

    // Apply Overdue Filter
    if (showOverdueOnly) {
       result = result.filter(t => checkOverdue(t) && t.status !== TaskStatus.COMPLETED);
    }

    return result;
  }, [tasks, currentUser, filterDept, filterProject, filterAssignee, users, showOverdueOnly]);


  const handleEngineerChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const uid = e.target.value;
    setSelectedEng(uid);
    if (uid) {
      const load = getEngineerWorkload(uid);
      const user = users.find(u => u.id === uid);
      if (load >= 2) {
        setWarningMsg(`${user?.name || '此工程師'} 目前已有 ${load} 個任務進行中。`);
      } else {
        setWarningMsg(null);
      }
    } else {
      setWarningMsg(null);
    }
  };

  const toggleOverdueFilter = () => {
    if (showOverdueOnly) {
      navigate('/tasks'); // Clear params
    } else {
      navigate('/tasks?filter=overdue');
    }
  };

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskName || !selectedEng || !selectedProject) return;

    // Simulate warning confirmation
    if (warningMsg && !window.confirm(`警告: ${warningMsg}\n\n您確定要繼續指派此任務嗎？`)) {
      return;
    }

    const newTask: Task = {
      id: `t-${Date.now()}`,
      name: newTaskName,
      projectId: selectedProject,
      assigneeId: selectedEng,
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      dependencies: [],
      department: users.find(u => u.id === selectedEng)?.department || '一般',
      isAdHoc: isAdHoc // Set the Ad-hoc flag
    };

    onAddTask(newTask);
    setIsModalOpen(false);
    // Reset form
    setNewTaskName('');
    setSelectedEng('');
    setSelectedProject('');
    setIsAdHoc(false);
    setWarningMsg(null);
  };

  const columns = [
    { id: TaskStatus.NOT_STARTED, label: '未開始', color: 'border-slate-300' },
    { id: TaskStatus.IN_PROGRESS, label: '進行中', color: 'border-blue-500' },
    { id: TaskStatus.COMPLETED, label: '已完成', color: 'border-green-500' },
  ];

  return (
    <div className="h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:justify-between md:items-center gap-4 mb-6">
        <h2 className="text-2xl font-bold text-slate-900">任務管理</h2>

        {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2 shadow-sm whitespace-nowrap"
          >
            <Plus size={16} /> 指派任務
          </button>
        )}
      </div>

      {/* Hierarchical Filters */}
      {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 mb-6 flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-2 text-slate-500 text-sm font-medium">
            <Filter size={16} />
            <span>篩選:</span>
          </div>

          {/* Overdue Toggle */}
          <button 
             onClick={toggleOverdueFilter}
             className={`px-3 py-1.5 rounded text-sm font-medium flex items-center gap-1 transition-colors border ${
               showOverdueOnly 
               ? 'bg-red-50 text-red-600 border-red-200 shadow-sm' 
               : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
             }`}
          >
             <AlertTriangle size={14} className={showOverdueOnly ? "fill-red-600" : ""} />
             只顯示逾期
          </button>

          <div className="h-6 w-px bg-slate-200 mx-2"></div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">1. 部門</label>
            <select 
              value={filterDept}
              onChange={(e) => {
                setFilterDept(e.target.value);
                setFilterProject('');
                setFilterAssignee('');
              }}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50"
            >
              <option value="">全部部門</option>
              {uniqueDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>

          <div className="text-slate-300">→</div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">2. 專案</label>
            <select 
              value={filterProject}
              onChange={(e) => {
                 setFilterProject(e.target.value);
                 // Optional: Reset assignee if they are not in this project?
                 // For now keep assignee filter as it might be useful to see "User X in Project Y"
              }}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50 max-w-[200px]"
            >
              <option value="">全部專案</option>
              {filteredProjects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>

           <div className="text-slate-300">→</div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-slate-500">3. 負責人</label>
             <select 
              value={filterAssignee}
              onChange={(e) => setFilterAssignee(e.target.value)}
              className="px-3 py-1.5 border border-slate-300 rounded text-sm focus:ring-2 focus:ring-brand-500 focus:outline-none bg-slate-50"
            >
              <option value="">全部人員</option>
              {filteredUsers.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
            </select>
          </div>

          <button 
            onClick={() => { setFilterDept(''); setFilterProject(''); setFilterAssignee(''); navigate('/tasks'); }}
            className="ml-auto text-xs text-slate-400 hover:text-slate-600 underline"
          >
            清除篩選
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full overflow-hidden">
        {columns.map(col => (
          <div key={col.id} className="bg-slate-100 rounded-xl p-4 flex flex-col h-full">
            <h3 className={`font-semibold text-slate-700 mb-4 pb-2 border-b-2 ${col.color}`}>
              {col.label} <span className="text-xs text-slate-400 ml-2 font-normal">({visibleTasks.filter(t => t.status === col.id).length})</span>
            </h3>
            <div className="flex-1 overflow-y-auto space-y-3">
              {visibleTasks.filter(t => t.status === col.id).length === 0 && (
                <div className="text-center py-8 text-slate-400 text-sm italic">無相關任務</div>
              )}
              {visibleTasks.filter(t => t.status === col.id).map(task => {
                const isOverdue = checkOverdue(task);
                // Calculate if due within 2 days (and not overdue)
                const now = new Date();
                const end = new Date(task.endDate);
                const diffTime = end.getTime() - now.getTime();
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                const isDueSoon = !isOverdue && task.status !== TaskStatus.COMPLETED && diffDays >= 0 && diffDays <= 2;

                return (
                <div key={task.id} className={`bg-white p-4 rounded-lg shadow-sm border group relative ${task.isAdHoc ? 'border-l-4 border-l-amber-500 border-slate-200' : 'border-slate-200'}`}>

                   {/* Badge Container */}
                   <div className="absolute top-3 right-3 flex flex-col gap-1 items-end z-10">
                     {task.isAdHoc && (
                       <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded font-bold">臨時</span>
                     )}
                     {isOverdue && (
                       <span className="text-[10px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1">
                         <AlertCircle size={10} /> 逾期
                       </span>
                     )}
                     {isDueSoon && (
                       <span className="text-[10px] bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1">
                         <Clock size={10} /> 即將到期
                       </span>
                     )}
                   </div>

                   <div className="flex justify-between items-start mb-2 pr-12">
                     <span className="text-xs font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded">{task.department}</span>
                   </div>

                   <h4 className="font-medium text-slate-800 mb-1">{task.name}</h4>
                   <p className="text-xs text-slate-500 mb-2 truncate pr-2">{projects.find(p => p.id === task.projectId)?.name}</p>

                   {/* Date Display */}
                   <div className={`flex items-center gap-1 text-xs mb-3 ${isOverdue ? 'text-red-600 font-bold' : isDueSoon ? 'text-orange-600 font-bold' : 'text-slate-400'}`}>
                      <Clock size={12} />
                      <span>{task.endDate}</span>
                   </div>

                   <div className="flex items-center justify-between mt-auto border-t border-slate-50 pt-3">
                      <div className="flex items-center gap-2">
                        <img src={users.find(u => u.id === task.assigneeId)?.avatar} className="w-6 h-6 rounded-full" alt="assignee" />
                        <span className="text-xs text-slate-500">{users.find(u => u.id === task.assigneeId)?.name.split(' ')[0]}</span>
                      </div>

                      {/* Simple status controls for demo */}
                      <div className="opacity-20 group-hover:opacity-100 transition-opacity flex gap-1">
                        {col.id !== TaskStatus.COMPLETED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.COMPLETED)} className="text-[10px] bg-green-100 text-green-700 px-2 py-1 rounded hover:bg-green-200">完成</button>
                        )}
                        {col.id === TaskStatus.NOT_STARTED && (
                           <button onClick={() => onUpdateTask(task.id, TaskStatus.IN_PROGRESS)} className="text-[10px] bg-blue-100 text-blue-700 px-2 py-1 rounded hover:bg-blue-200">開始</button>
                        )}
                      </div>
                   </div>
                </div>
              )})}
            </div>
          </div>
        ))}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold text-slate-800">指派新任務</h3>
              <button onClick={() => setIsModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
            </div>
            <form onSubmit={handleCreateTask} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">任務名稱</label>
                <input 
                  type="text" 
                  value={newTaskName} 
                  onChange={(e) => setNewTaskName(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                  placeholder="輸入任務內容..."
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">專案歸屬</label>
                <select 
                  value={selectedProject} 
                  onChange={(e) => setSelectedProject(e.target.value)}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇專案...</option>
                  {projects.filter(p => p.status === 'IN_PROGRESS' || p.status === 'PLANNING').map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">指派給</label>
                <select 
                  value={selectedEng} 
                  onChange={handleEngineerChange}
                  className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500"
                  required
                >
                  <option value="">請選擇工程師...</option>
                  {users.filter(u => u.role === UserRole.ENGINEER).map(u => (
                    <option key={u.id} value={u.id}>{u.name} ({u.department})</option>
                  ))}
                </select>
              </div>

              {/* Task Type Toggle */}
              <div className="flex items-center gap-2 pt-1">
                <input 
                  type="checkbox" 
                  id="isAdHoc"
                  checked={isAdHoc}
                  onChange={(e) => setIsAdHoc(e.target.checked)}
                  className="w-4 h-4 text-brand-600 rounded focus:ring-brand-500 border-gray-300"
                />
                <label htmlFor="isAdHoc" className="text-sm font-medium text-slate-700">這是一項臨時任務 (Ad-hoc)</label>
              </div>

              {/* Workload Warning */}
              {warningMsg && (
                <div className="bg-amber-50 border border-amber-200 text-amber-800 text-sm p-4 rounded-lg flex items-start gap-3 mt-2">
                  <AlertTriangle size={20} className="mt-0.5 flex-shrink-0 text-amber-600" />
                  <div className="flex-1">
                    <p className="font-bold mb-1">工作量警示</p>
                    <p>{warningMsg}</p>
                    <p className="text-xs text-amber-600/80 mt-1">您仍可強制指派，但請留意工程師負荷。</p>
                  </div>
                </div>
              )}

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                <button 
                  type="submit" 
                  className={`px-4 py-2 text-white rounded-lg text-sm font-medium flex items-center gap-2 ${warningMsg ? 'bg-amber-600 hover:bg-amber-700' : 'bg-brand-600 hover:bg-brand-700'}`}
                >
                  {warningMsg ? <><AlertCircle size={16}/> 強制指派</> : <><Plus size={16}/> 確認指派</>}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskManager;

import React, { useMemo, useState } from 'react';
import { User, UserRole, Project, Task, ScheduleEvent, Notice, TaskStatus, ProjectStatus } from '../types';
import { AlertCircle, Clock, Calendar, Megaphone, CheckCircle2, Plus, Edit, Trash2, X, Save, BarChart3, AlertTriangle } from 'lucide-react';
import { checkOverdue } from '../services/mockService';
import { useNavigate } from 'react-router-dom';

interface DashboardProps {
  user: User;
  users: User[];
  projects: Project[];
  tasks: Task[];
  events: ScheduleEvent[];
  notices: Notice[];
  onAddNotice: (notice: Notice) => void;
  onUpdateNotice: (notice: Notice) => void;
  onDeleteNotice: (id: string) => void;
}

const PROJECT_STATUS_MAP: Record<string, string> = {
  [ProjectStatus.PLANNING]: '規劃中',
  [ProjectStatus.QUOTE_NEEDED]: '須報價',
  [ProjectStatus.QUOTED]: '已報價',
  [ProjectStatus.IN_PROGRESS]: '進行中',
  [ProjectStatus.ACCEPTANCE]: '驗收中',
  [ProjectStatus.COMPLETED]: '完成',
  [ProjectStatus.CANCELLED]: '取消',
};

const TASK_STATUS_MAP: Record<string, string> = {
  [TaskStatus.NOT_STARTED]: '未開始',
  [TaskStatus.IN_PROGRESS]: '進行中',
  [TaskStatus.COMPLETED]: '完成',
  [TaskStatus.OVERDUE]: '逾期',
};

const Dashboard: React.FC<DashboardProps> = ({ user, users, projects, tasks, events, notices, onAddNotice, onUpdateNotice, onDeleteNotice }) => {
  const navigate = useNavigate();

  // Notice State
  const [isNoticeModalOpen, setIsNoticeModalOpen] = useState(false);
  const [editingNotice, setEditingNotice] = useState<Notice | null>(null);
  const [noticeForm, setNoticeForm] = useState<{title: string, content: string, type: 'SYSTEM' | 'ANNOUNCEMENT'}>({
    title: '', content: '', type: 'ANNOUNCEMENT'
  });

  // Permissions
  const canManageNotices = user.role === UserRole.ADMIN || user.role === UserRole.MANAGER;

  const handleOpenNoticeModal = (notice?: Notice) => {
    if (notice) {
      setEditingNotice(notice);
      setNoticeForm({
        title: notice.title,
        content: notice.content,
        type: notice.type
      });
    } else {
      setEditingNotice(null);
      setNoticeForm({ title: '', content: '', type: 'ANNOUNCEMENT' });
    }
    setIsNoticeModalOpen(true);
  };

  const handleNoticeSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingNotice) {
      onUpdateNotice({
        ...editingNotice,
        ...noticeForm
      });
    } else {
      onAddNotice({
        id: `n-${Date.now()}`,
        date: new Date().toISOString().split('T')[0],
        ...noticeForm
      });
    }
    setIsNoticeModalOpen(false);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('確定要刪除此公告嗎？')) {
      onDeleteNotice(id);
    }
  };


  // Derived State
  const myTasks = useMemo(() => tasks.filter(t => t.assigneeId === user.id), [tasks, user.id]);
  const overdueTasks = useMemo(() => tasks.filter(t => checkOverdue(t) && t.status !== TaskStatus.COMPLETED), [tasks]);
  const deptTasks = useMemo(() => tasks.filter(t => t.department === user.department), [tasks, user.department]);

  const upcomingEvents = useMemo(() => {
    // Simple mock filter for "next week"
    return events.slice(0, 5);
  }, [events]);

  const renderAdminView = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-slate-500 text-sm font-medium mb-2">專案總數</h3>
          <p className="text-3xl font-bold text-slate-800">{projects.length}</p>
          <div className="mt-4 flex gap-2">
            <span className="px-2 py-1 bg-green-100 text-green-700 text-xs rounded-full">
              {projects.filter(p => p.status === ProjectStatus.IN_PROGRESS).length} 進行中
            </span>
            <span className="px-2 py-1 bg-amber-100 text-amber-700 text-xs rounded-full">
              {projects.filter(p => p.status === ProjectStatus.PLANNING).length} 規劃中
            </span>
          </div>
        </div>

        {/* Clickable Severe Issues Card */}
        <div 
          onClick={() => navigate('/tasks?filter=overdue')}
          className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 cursor-pointer hover:shadow-md hover:border-red-200 transition-all group relative overflow-hidden"
        >
          <div className="absolute right-0 top-0 w-20 h-20 bg-red-50 rounded-bl-full -mr-10 -mt-10 transition-transform group-hover:scale-110"></div>
          <div className="relative z-10">
            <h3 className="text-slate-500 text-sm font-medium mb-2 group-hover:text-red-600 transition-colors flex items-center gap-2">
               嚴重問題 <AlertTriangle size={14} className="opacity-0 group-hover:opacity-100 text-red-500 transition-opacity" />
            </h3>
            <p className="text-3xl font-bold text-red-600 group-hover:text-red-700">{overdueTasks.length}</p>
            <p className="text-xs text-slate-400 mt-1 group-hover:text-red-400">跨部門逾期任務 (點擊查看)</p>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-slate-500 text-sm font-medium mb-2">即將到期</h3>
          <p className="text-3xl font-bold text-brand-600">
            {tasks.filter(t => {
               const diff = new Date(t.endDate).getTime() - new Date().getTime();
               return diff > 0 && diff < 7 * 24 * 60 * 60 * 1000;
            }).length}
          </p>
          <p className="text-xs text-slate-400 mt-1">7天內到期任務</p>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
         <div className="p-6 border-b border-slate-100">
           <h3 className="text-lg font-semibold text-slate-800">專案快照</h3>
         </div>
         <div className="overflow-x-auto">
           <table className="w-full text-sm text-left">
             <thead className="bg-slate-50 text-slate-500 font-medium">
               <tr>
                 <th className="px-6 py-3">專案名稱</th>
                 <th className="px-6 py-3">客戶</th>
                 <th className="px-6 py-3">狀態</th>
                 <th className="px-6 py-3">當前重點任務</th>
                 <th className="px-6 py-3">操作</th>
               </tr>
             </thead>
             <tbody className="divide-y divide-slate-100">
               {projects.map(p => {
                 // Logic to find the most urgent active task
                 const activeTasks = tasks.filter(t => t.projectId === p.id && t.status === TaskStatus.IN_PROGRESS);
                 // Sort by end date ascending (earliest first)
                 activeTasks.sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime());
                 const urgentTask = activeTasks.length > 0 ? activeTasks[0] : null;
                 const isOverdueTask = urgentTask ? checkOverdue(urgentTask) : false;

                 return (
                   <tr key={p.id} className="hover:bg-slate-50">
                     <td className="px-6 py-4 font-medium text-slate-800">{p.name}</td>
                     <td className="px-6 py-4 text-slate-500">{p.client}</td>
                     <td className="px-6 py-4">
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold
                          ${p.status === ProjectStatus.IN_PROGRESS ? 'bg-blue-100 text-blue-700' : 
                            p.status === ProjectStatus.COMPLETED ? 'bg-green-100 text-green-700' : 
                            'bg-slate-100 text-slate-700'}`}>
                          {PROJECT_STATUS_MAP[p.status] || p.status}
                        </span>
                     </td>
                     <td className="px-6 py-4">
                       {urgentTask ? (
                         <div className="flex flex-col gap-1">
                           <div className="flex items-center gap-2">
                             <div className={`w-2 h-2 rounded-full ${isOverdueTask ? 'bg-red-500' : 'bg-blue-500'}`}></div>
                             <span className="font-medium text-slate-700 truncate max-w-[150px]" title={urgentTask.name}>{urgentTask.name}</span>
                           </div>
                           <div className="flex items-center gap-2 text-xs text-slate-400 pl-4">
                              <span className={`flex items-center gap-1 ${isOverdueTask ? 'text-red-500 font-bold' : ''}`}>
                                <Clock size={10} /> {urgentTask.endDate}
                              </span>
                              <span>•</span>
                              <span>{users.find(u => u.id === urgentTask.assigneeId)?.name.split(' ')[0]}</span>
                           </div>
                         </div>
                       ) : (
                         <span className="text-xs text-slate-400 italic pl-2">目前無進行中任務</span>
                       )}
                     </td>
                     <td className="px-6 py-4">
                       <button onClick={() => navigate(`/projects/${p.id}`)} className="text-brand-600 hover:underline">查看</button>
                     </td>
                   </tr>
                 )
               })}
             </tbody>
           </table>
         </div>
      </div>
    </div>
  );

  const renderManagerView = () => {
    // Logic for Team Status
    const deptEngineers = users.filter(u => u.department === user.department && u.role !== UserRole.ADMIN);

    return (
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Department Overview */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-semibold text-slate-800 mb-4">{user.department} 概覽</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 bg-slate-50 rounded-lg">
                <span className="text-slate-600">進行中任務</span>
                <span className="font-bold text-slate-900">{deptTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length}</span>
              </div>
              <div 
                 onClick={() => navigate('/tasks?filter=overdue')}
                 className="flex justify-between items-center p-3 bg-red-50 rounded-lg cursor-pointer hover:bg-red-100 transition-colors"
              >
                <span className="text-red-600 font-medium flex items-center gap-1"><AlertTriangle size={14}/> 逾期任務</span>
                <span className="font-bold text-red-700">{deptTasks.filter(t => checkOverdue(t)).length}</span>
              </div>
              <div className="flex justify-between items-center p-3 bg-blue-50 rounded-lg">
                <span className="text-blue-600">參與專案</span>
                <span className="font-bold text-blue-700">
                  {projects.filter(p => p.departments.includes(user.department) && p.status === ProjectStatus.IN_PROGRESS).length}
                </span>
              </div>
            </div>
          </div>

          {/* Engineer Workload Visualization */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex flex-col">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-slate-800">工程師負載監控</h3>
              <span className="text-xs bg-slate-100 text-slate-500 px-2 py-1 rounded">
                共 {deptEngineers.length} 人
              </span>
            </div>

            <div className="space-y-4 flex-1 overflow-y-auto max-h-[300px] pr-2 custom-scrollbar">
               {deptEngineers.map(engineer => {
                 const engTasks = tasks.filter(t => t.assigneeId === engineer.id && t.status !== TaskStatus.COMPLETED);
                 const activeCount = engTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
                 const notStartedCount = engTasks.filter(t => t.status === TaskStatus.NOT_STARTED).length;
                 const overdueCount = engTasks.filter(t => checkOverdue(t)).length;

                 // Determine Load Status
                 let statusColor = 'bg-green-500';
                 let statusText = '空閒';
                 const totalLoad = activeCount + (notStartedCount * 0.5); // Weight active tasks more

                 if (overdueCount > 0) {
                   statusColor = 'bg-red-500';
                   statusText = '警示';
                 } else if (totalLoad > 3) {
                   statusColor = 'bg-red-400';
                   statusText = '高負載';
                 } else if (totalLoad >= 2) {
                   statusColor = 'bg-amber-400';
                   statusText = '忙碌';
                 }

                 return (
                   <div key={engineer.id} className="p-3 bg-slate-50 rounded-lg border border-slate-100 group">
                      <div className="flex items-center justify-between mb-2">
                         <div className="flex items-center gap-2">
                            <div className="relative">
                              <img src={engineer.avatar} className="w-8 h-8 rounded-full bg-slate-200" alt={engineer.name} />
                              <div className={`absolute -bottom-0.5 -right-0.5 w-3 h-3 rounded-full border-2 border-white ${statusColor}`}></div>
                            </div>
                            <div>
                               <p className="text-sm font-bold text-slate-700">{engineer.name}</p>
                               <p className="text-[10px] text-slate-400">{statusText}</p>
                            </div>
                         </div>
                         <div className="text-right">
                            <span className="text-xl font-bold text-slate-800">{activeCount + notStartedCount}</span>
                            <span className="text-[10px] text-slate-400 block">待辦</span>
                         </div>
                      </div>

                      {/* Progress Bar Visual */}
                      <div className="w-full h-1.5 bg-slate-200 rounded-full overflow-hidden flex mb-2">
                         <div className="bg-red-500 h-full" style={{ width: `${(overdueCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-blue-500 h-full" style={{ width: `${(activeCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                         <div className="bg-slate-400 h-full" style={{ width: `${(notStartedCount / Math.max(engTasks.length, 1)) * 100}%` }}></div>
                      </div>

                      {/* Detail Badges */}
                      <div className="flex gap-2 text-[10px]">
                         {activeCount > 0 && <span className="bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">進行 {activeCount}</span>}
                         {overdueCount > 0 && <span className="bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold flex items-center gap-1"><AlertTriangle size={8}/> 逾期 {overdueCount}</span>}
                         {notStartedCount > 0 && <span className="bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">未開始 {notStartedCount}</span>}
                         {activeCount + notStartedCount + overdueCount === 0 && <span className="text-slate-400 italic">目前無任務</span>}
                      </div>
                   </div>
                 );
               })}
            </div>
          </div>
        </div>
      </div>
    );
  };

  const renderEngineerView = () => (
    <div className="space-y-6">
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 p-6">
        <h3 className="text-lg font-semibold text-slate-800 mb-4">我的優先任務</h3>
        {myTasks.length === 0 ? (
          <p className="text-slate-500 text-center py-8">目前沒有指派的進行中任務。</p>
        ) : (
          <div className="space-y-3">
            {myTasks
              .sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime())
              .map(task => {
              const isOverdue = checkOverdue(task);
              return (
                <div key={task.id} className={`p-4 rounded-lg border-l-4 flex justify-between items-center ${isOverdue ? 'bg-red-50 border-red-500' : 'bg-slate-50 border-brand-500'}`}>
                   <div>
                     <h4 className="font-medium text-slate-800">{task.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">期限: {task.endDate}</p>
                   </div>
                   <div className="flex items-center gap-2">
                     <span className={`text-xs px-2 py-1 rounded font-medium ${
                       task.status === TaskStatus.COMPLETED ? 'bg-green-200 text-green-800' :
                       task.status === TaskStatus.IN_PROGRESS ? 'bg-blue-200 text-blue-800' :
                       'bg-slate-200 text-slate-800'
                     }`}>{TASK_STATUS_MAP[task.status] || task.status}</span>
                   </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      {/* Left Column (Main Content) */}
      <div className="lg:col-span-2 space-y-8">
        {user.role === UserRole.ADMIN && renderAdminView()}
        {user.role === UserRole.MANAGER && renderManagerView()}
        {user.role === UserRole.ENGINEER && renderEngineerView()}
      </div>

      {/* Right Column (Sidebar Widgets) */}
