  const [collapsedStatuses, setCollapsedStatuses] = useState<ProjectStatus[]>([]);

  // Modals State
  const [isCreateModalOpen, setCreateModalOpen] = useState(false);
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [isTemplateModalOpen, setTemplateModalOpen] = useState(false);
  const [isEditTaskModalOpen, setEditTaskModalOpen] = useState(false);

  // Form Data State
  const [formData, setFormData] = useState<Partial<Project>>({
    name: '', client: '', description: '', startDate: '', endDate: '', departments: []
  });

  // Template Form State
  const [templateId, setTemplateId] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateAssignee, setTemplateAssignee] = useState('');

  // Task Edit State
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Extract all known departments from existing projects for suggestions
  const allKnownDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Extract all unique departments from projects for filter
  // MOVED UP before conditional return to avoid React Error #300
  const filterDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Filter projects based on selection and view mode
  // MOVED UP before conditional return to avoid React Error #300
  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      // 1. Department Filter
      const deptMatch = selectedDept === 'ALL' || p.departments.includes(selectedDept);

      // 2. View Mode Filter (All vs Mine)
      let viewMatch = true;
      if (viewFilter === 'MINE') {
        if (currentUser.role === UserRole.MANAGER || currentUser.role === UserRole.ADMIN) {
           // Manager sees projects they manage OR projects where they have tasks
           viewMatch = p.managerId === currentUser.id;
        } else {
           // Engineer sees projects where they have at least one task assigned
           const userTasks = tasks.filter(t => t.projectId === p.id && t.assigneeId === currentUser.id);
           viewMatch = userTasks.length > 0;
        }
      }

      return deptMatch && viewMatch;
    });
  }, [projects, tasks, selectedDept, viewFilter, currentUser]);

  const toggleColumn = (status: ProjectStatus) => {
    setCollapsedStatuses(prev => 
      prev.includes(status) ? prev.filter(s => s !== status) : [...prev, status]
    );
  };

  const openCreateModal = () => {
    setFormData({
      name: '', client: '', description: '', 
      startDate: new Date().toISOString().split('T')[0], 
      endDate: '', 
      departments: []
    });
    setCreateModalOpen(true);
  };

  const openEditModal = (project: Project) => {
    setFormData({ ...project });
    setEditModalOpen(true);
  };

  const openEditTaskModal = (task: Task) => {
    setEditingTask({ ...task });
    setEditTaskModalOpen(true);
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.client) return;

    const newProject: Project = {
      id: `p-${Date.now()}`,
      name: formData.name!,
      client: formData.client!,
      description: formData.description || '',
      startDate: formData.startDate!,
      endDate: formData.endDate!,
      departments: formData.departments || [],
      status: ProjectStatus.PLANNING, // Default status
      managerId: currentUser.id // Admin is creator
    };

    onAddProject(newProject);
    setCreateModalOpen(false);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.id) {
       onUpdateProject(formData as Project);
       setEditModalOpen(false);
    }
  };

  const handleTemplateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (id && templateId && templateStartDate) {
      onImportTemplate(id, templateId, templateStartDate, templateAssignee || currentUser.id);
      setTemplateModalOpen(false);
      setTemplateId('');
      setTemplateStartDate('');
      setTemplateAssignee('');
    }
  };

  const handleEditTaskSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTask) {
      onUpdateTask(editingTask);
      setEditTaskModalOpen(false);
      setEditingTask(null);
    }
  };

  const toggleDependency = (targetTaskId: string) => {
      if (!editingTask) return;
      const currentDeps = editingTask.dependencies || [];
      if (currentDeps.includes(targetTaskId)) {
          setEditingTask({ ...editingTask, dependencies: currentDeps.filter(d => d !== targetTaskId) });
      } else {
          setEditingTask({ ...editingTask, dependencies: [...currentDeps, targetTaskId] });
      }
  };

  const autoSetStartDate = () => {
      if (!editingTask || !editingTask.dependencies || editingTask.dependencies.length === 0) return;

      const parentTasks = tasks.filter(t => editingTask.dependencies.includes(t.id));
      if (parentTasks.length === 0) return;

      // Find the max end date of parents
      const maxEndDate = parentTasks.reduce((max, task) => {
          const end = new Date(task.endDate);
          return end > max ? end : max;
      }, new Date(0));

      if (maxEndDate.getTime() > 0) {
          // Set to next day
          const nextDay = new Date(maxEndDate);
          nextDay.setDate(nextDay.getDate() + 1);
          setEditingTask({ ...editingTask, startDate: nextDay.toISOString().split('T')[0] });
      }
  };

  const toggleDepartment = (dept: string) => {
    const current = formData.departments || [];
    if (current.includes(dept)) {
      setFormData({ ...formData, departments: current.filter(d => d !== dept) });
    } else {
      setFormData({ ...formData, departments: [...current, dept] });
    }
  };

  // Render Modal Form Content (Shared fields)
  const renderFormFields = () => (
    <>
       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">專案名稱</label>
            <input 
              type="text" 
              required
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">客戶名稱</label>
            <input 
              type="text" 
              required
              value={formData.client} 
              onChange={e => setFormData({...formData, client: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">開始日期</label>
            <input 
              type="date" 
              value={formData.startDate} 
              onChange={e => setFormData({...formData, startDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">預計結束日期</label>
            <input 
              type="date" 
              value={formData.endDate} 
              onChange={e => setFormData({...formData, endDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">專案描述</label>
          <textarea 
            rows={3}
            value={formData.description} 
            onChange={e => setFormData({...formData, description: e.target.value})}
            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
          />
       </div>

       {/* Department Assignment */}
       <div>
         <label className="block text-sm font-medium text-slate-700 mb-2">指派參與部門</label>
         <div className="border border-slate-200 rounded-lg p-3 bg-slate-50 max-h-32 overflow-y-auto grid grid-cols-2 gap-2">
            {allKnownDepartments.map(dept => (
              <label key={dept} className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={formData.departments?.includes(dept)} 
                  onChange={() => toggleDepartment(dept)}
                  className="rounded text-brand-600 focus:ring-brand-500"
                />
                <span className="text-sm text-slate-600">{dept}</span>
              </label>
            ))}
         </div>
         <p className="text-xs text-slate-400 mt-1">選取後，各部門主管將會收到通知並安排詳細任務流程。</p>
       </div>
    </>
  );

  // --- DETAIL VIEW ---
  if (id) {
    const project = projects.find(p => p.id === id);
    if (!project) return <div>Project not found</div>;

    const projectTasks = tasks.filter(t => t.projectId === id);
    const isDeptManager = currentUser.role === UserRole.MANAGER && project.departments.includes(currentUser.department);
    const canEditTasks = isDeptManager || currentUser.role === UserRole.ADMIN;
    const canEditStatus = currentUser.role === UserRole.ADMIN;

    const availableTemplates = getTaskTemplates().filter(t => t.department === currentUser.department);

    return (
      <div className="space-y-6 animate-in fade-in duration-300">
        {/* Breadcrumb */}
        <button onClick={() => navigate('/projects')} className="flex items-center text-sm text-slate-500 hover:text-brand-600 mb-4">
          <ArrowLeft size={16} className="mr-1" /> 返回專案列表
        </button>

        {/* Project Header */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">{project.name}</h1>
              {/* Quick Status Selector in Detail View */}
              <QuickStatusSelector 
                project={project} 
                canEdit={canEditStatus} 
                onUpdateStatus={(s) => onUpdateProject({...project, status: s})} 
              />
            </div>
            <p className="text-slate-500 mt-2">{project.description}</p>
            <div className="flex items-center gap-6 mt-4 text-sm text-slate-500">
               <span className="flex items-center gap-1"><Calendar size={14} /> {project.startDate} - {project.endDate}</span>
               <span className="flex items-center gap-1"><UserCircle size={14} /> 客戶: {project.client}</span>
            </div>
            <div className="flex gap-2 mt-4">
              <span className="text-xs font-bold text-slate-400 py-1">參與部門:</span>
              {project.departments.map(d => (
                <span key={d} className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200">
                  {d}
                </span>
              ))}
            </div>
          </div>
          <div className="flex gap-2">
            {isDeptManager && (
              <button 
                onClick={() => {
                   setTemplateStartDate(new Date().toISOString().split('T')[0]);
                   setTemplateAssignee(currentUser.id);
                   setTemplateModalOpen(true);
                }}
                className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm hover:bg-brand-700 flex items-center gap-2"
              >
                <Workflow size={16} /> 匯入任務流程
              </button>
            )}
            {currentUser.role === UserRole.ADMIN && (
               <button 
                  onClick={() => openEditModal(project)}
                  className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm hover:bg-slate-800 flex items-center gap-2"
               >
                 <Edit size={16} /> 編輯專案
               </button>
            )}
          </div>
        </div>

        {/* View Switcher & Content */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 min-h-[500px]">
           <div className="flex justify-between items-center mb-6">
             <div className="flex items-center gap-4">
                <h3 className="text-lg font-semibold text-slate-800">專案任務</h3>

                {/* View Tabs */}
                <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button 
                    onClick={() => setDetailViewMode('LIST')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'LIST' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <List size={16} /> 列表
                  </button>
                  <button 
                    onClick={() => setDetailViewMode('GRAPH')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'GRAPH' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <Network size={16} /> 流程圖
                  </button>
                   <button 
                    onClick={() => setDetailViewMode('GANTT')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'GANTT' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <CalendarRange size={16} /> 甘特圖
                  </button>
                </div>
             </div>
           </div>

           {/* Render Content based on View Mode */}
           {detailViewMode === 'GRAPH' && (
              <SimpleDependencyGraph 
                  tasks={projectTasks} 
                  onTaskClick={canEditTasks ? openEditTaskModal : undefined}
              />
           )}

           {detailViewMode === 'GANTT' && (
              <ProjectGanttChart 
                 tasks={projectTasks} 
                 users={users}
                 onTaskClick={canEditTasks ? openEditTaskModal : undefined}
              />
           )}

           {detailViewMode === 'LIST' && (
             <div className="overflow-x-auto">
               <table className="w-full text-sm text-left">
                 <thead className="bg-slate-50 text-slate-500">
                   <tr>
                     <th className="px-4 py-2">任務</th>
                     <th className="px-4 py-2">負責人</th>
                     <th className="px-4 py-2">日期</th>
                     <th className="px-4 py-2">狀態</th>
                     <th className="px-4 py-2">操作</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                   {projectTasks.length === 0 ? (
                     <tr><td colSpan={5} className="text-center py-4 text-slate-400">暫無任務</td></tr>
                   ) : (
                     projectTasks.map(t => (
                       <tr key={t.id} className="hover:bg-slate-50 group">
                         <td className="px-4 py-3 font-medium">
                           {t.name}
                           {t.department === currentUser.department && (
                             <span className="ml-2 text-[10px] text-brand-600 bg-brand-50 px-1 rounded border border-brand-100">本部門</span>
                           )}
                         </td>
                         <td className="px-4 py-3 flex items-center gap-2">
                           <img src={users.find(u=>u.id===t.assigneeId)?.avatar} className="w-6 h-6 rounded-full"/>
                           {users.find(u=>u.id===t.assigneeId)?.name.split(' ')[0]}
                         </td>
                         <td className="px-4 py-3 text-slate-500">{t.startDate} - {t.endDate}</td>
                         <td className="px-4 py-3">
                           <span className={`px-2 py-0.5 rounded text-xs ${t.status === TaskStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                             {TASK_STATUS_MAP[t.status]}
                           </span>
                         </td>
                         <td className="px-4 py-3">
                           {(currentUser.role === UserRole.MANAGER && t.department === currentUser.department) || currentUser.role === UserRole.ADMIN ? (
                             <button onClick={() => openEditTaskModal(t)} className="text-slate-400 hover:text-brand-600 opacity-0 group-hover:opacity-100 transition-opacity">
                               <Edit size={14} />
                             </button>
                           ) : null}
                         </td>
                       </tr>
                     ))
                   )}
                 </tbody>
               </table>
             </div>
           )}
        </div>

        {/* Import Template Modal */}
        {isTemplateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">匯入標準任務流程</h3>
                <button onClick={() => setTemplateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleTemplateSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">選擇流程模板</label>
                  <select 
                    value={templateId} 
                    onChange={e => setTemplateId(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    required
                  >
                    <option value="">請選擇...</option>
                    {availableTemplates.map(t => (
                      <option key={t.id} value={t.id}>{t.name} ({t.department})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">流程開始日期</label>
                    <input 
                      type="date"
                      value={templateStartDate}
                      onChange={e => setTemplateStartDate(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                      required
                    />
                  </div>
                   <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">預設負責人</label>
                    <select 
                      value={templateAssignee}
                      onChange={e => setTemplateAssignee(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    >
                      {users.filter(u => u.department === currentUser.department && u.role === UserRole.ENGINEER).map(u => (
                        <option key={u.id} value={u.id}>{u.name}</option>
                      ))}
                      <option value={currentUser.id}>我自己 (主管)</option>
                    </select>
                  </div>
                </div>

                <div className="bg-slate-50 p-3 rounded text-xs text-slate-500 border border-slate-200 mt-2">
                  <p>匯入後，系統將自動建立所有相關任務並設定依賴關係。您可以在列表中點擊編輯按鈕來微調每個任務的日期與負責人。</p>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                  <button type="button" onClick={() => setTemplateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Workflow size={16} /> 確認匯入
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Edit Task Modal (Updated with Dependencies) */}
        {isEditTaskModalOpen && editingTask && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h3 className="text-lg font-bold text-slate-800">調整任務: {editingTask.name}</h3>
                  <p className="text-xs text-slate-400 mt-1">ID: {editingTask.id}</p>
                </div>
                <button onClick={() => setEditTaskModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleEditTaskSubmit} className="space-y-6 overflow-y-auto pr-2">
                 {/* Basic Info */}
                 <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">負責人</label>
                        <select 
                          value={editingTask.assigneeId}
                          onChange={e => setEditingTask({...editingTask, assigneeId: e.target.value})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                          {users.filter(u => u.department === editingTask.department || u.role === UserRole.ENGINEER).map(u => (
                            <option key={u.id} value={u.id}>{u.name} - {u.department}</option>
                          ))}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">狀態</label>
                        <select 
                          value={editingTask.status}
                          onChange={e => setEditingTask({...editingTask, status: e.target.value as TaskStatus})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                           {Object.entries(TASK_STATUS_MAP).map(([key, label]) => (
                             <option key={key} value={key}>{label}</option>
                           ))}
                        </select>
                    </div>
                 </div>

                 {/* Dependencies Section */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
                        <Link size={14} /> 前置任務 (本任務將在以下任務後進行)
                      </label>
                    </div>
                    <div className="space-y-2 max-h-32 overflow-y-auto border border-slate-300 bg-white rounded p-2">
                        {projectTasks
                          .filter(t => t.id !== editingTask.id) // Cannot depend on self
                          .map(t => (
                          <label key={t.id} className="flex items-center gap-2 text-sm p-1 hover:bg-slate-50 rounded cursor-pointer">
                             <input 
                                type="checkbox" 
                                checked={editingTask.dependencies?.includes(t.id)}
                                onChange={() => toggleDependency(t.id)}
                                className="rounded text-brand-600 focus:ring-brand-500"
                             />
                             <span className="flex-1">{t.name} <span className="text-slate-400 text-xs">({t.endDate})</span></span>
                             {editingTask.dependencies?.includes(t.id) && <ArrowRight size={12} className="text-brand-500"/>}
                          </label>
                        ))}
                        {projectTasks.length <= 1 && <div className="text-xs text-slate-400 italic text-center">無其他任務可選</div>}
                    </div>
                    {editingTask.dependencies && editingTask.dependencies.length > 0 && (
                       <p className="text-xs text-brand-600 mt-2 flex items-center gap-1">
                          已選擇 {editingTask.dependencies.length} 個前置任務
                       </p>
                    )}
                 </div>

                 {/* Dates with Auto-Calc */}
                 <div className="grid grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-1">
                       <label className="block text-sm font-medium text-slate-700">開始日期</label>
                       <button 
                         type="button" 
                         onClick={autoSetStartDate}
                         disabled={!editingTask.dependencies?.length}
                         className="text-[10px] bg-brand-50 text-brand-700 px-2 py-0.5 rounded border border-brand-200 flex items-center gap-1 hover:bg-brand-100 disabled:opacity-50 disabled:cursor-not-allowed"
                         title="根據前置任務的結束日期自動推算"
                       >
                         <Wand2 size={10} /> 自動推算
                       </button>
                    </div>
                    <input 
                      type="date"
                      value={editingTask.startDate}
                      onChange={e => setEditingTask({...editingTask, startDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">結束日期</label>
                    <input 
                      type="date"
                      value={editingTask.endDate}
                      onChange={e => setEditingTask({...editingTask, endDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 mt-6 border-t border-slate-100 pt-4">
                  <button type="button" onClick={() => setEditTaskModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
