const ProjectGanttChart: React.FC<GanttProps> = ({ tasks, users, onTaskClick }) => {
  if (tasks.length === 0) {
    return <div className="p-12 text-center text-slate-400 border rounded-lg bg-slate-50">此專案目前尚無任務，請先建立任務。</div>;
  }

  // 1. Calculate Date Range
  const dates = tasks.flatMap(t => [new Date(t.startDate), new Date(t.endDate)]);
  if (dates.length === 0) return null;

  const minDate = new Date(Math.min(...dates.map(d => d.getTime())));
  const maxDate = new Date(Math.max(...dates.map(d => d.getTime())));

  // Add padding: 3 days before, 7 days after
  minDate.setDate(minDate.getDate() - 3);
  maxDate.setDate(maxDate.getDate() + 7);

  const totalDays = Math.ceil((maxDate.getTime() - minDate.getTime()) / (1000 * 3600 * 24));

  // Constants
  const DAY_WIDTH = 40;
  const HEADER_HEIGHT = 40;
  const ROW_HEIGHT = 48;
  const LABEL_WIDTH = 200; // Left column for task names

  const chartWidth = totalDays * DAY_WIDTH;
  const chartHeight = tasks.length * ROW_HEIGHT + HEADER_HEIGHT;

  // Helpers
  const getX = (dateStr: string) => {
    const d = new Date(dateStr);
    const diffTime = Math.abs(d.getTime() - minDate.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
    return diffDays * DAY_WIDTH;
  };

  const getDurationWidth = (start: string, end: string) => {
    const s = new Date(start);
    const e = new Date(end);
    // Add 1 day to include end date
    const diffDays = Math.ceil((e.getTime() - s.getTime()) / (1000 * 3600 * 24)) + 1; 
    return Math.max(diffDays * DAY_WIDTH, 5); // Min width
  };

  const todayX = getX(new Date().toISOString().split('T')[0]);

  // Sort tasks by start date
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  const daysArray = Array.from({ length: totalDays }, (_, i) => {
      const d = new Date(minDate);
      d.setDate(d.getDate() + i);
      return d;
  });

  return (
    <div className="border rounded-xl bg-white shadow-sm overflow-hidden flex flex-col">
       {/* Legend */}
       <div className="flex items-center gap-4 p-3 border-b border-slate-100 bg-slate-50 text-xs text-slate-600">
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-blue-500"></span> 進行中</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-green-500"></span> 完成</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-slate-300"></span> 未開始</div>
          <div className="flex items-center gap-1"><span className="w-3 h-3 rounded bg-red-400"></span> 逾期</div>
       </div>

       <div className="flex overflow-x-auto relative custom-scrollbar">
         {/* Left Column (Sticky) */}
         <div className="sticky left-0 z-20 bg-white border-r border-slate-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]" style={{ width: LABEL_WIDTH, minWidth: LABEL_WIDTH }}>
            {/* Header placeholder */}
            <div className="border-b border-slate-100 bg-slate-50 font-bold text-slate-700 text-xs flex items-center px-4" style={{ height: HEADER_HEIGHT }}>
              任務名稱
            </div>
            {/* Rows */}
            {sortedTasks.map(t => (
               <div key={t.id} className="border-b border-slate-100 flex flex-col justify-center px-4 hover:bg-slate-50 truncate" style={{ height: ROW_HEIGHT }}>
                  <span className="text-sm font-medium text-slate-800 truncate" title={t.name}>{t.name}</span>
                  <span className="text-[10px] text-slate-500 truncate">{users.find(u => u.id === t.assigneeId)?.name}</span>
               </div>
            ))}
         </div>

         {/* Chart Area */}
         <div style={{ width: chartWidth, minWidth: chartWidth }} className="relative bg-white">
            {/* Grid Lines (Vertical) */}
            {daysArray.map((_, i) => (
               <div key={i} className="absolute top-0 bottom-0 border-r border-slate-100" style={{ left: (i + 1) * DAY_WIDTH, width: 0 }} />
            ))}

            {/* Today Line */}
            {todayX >= 0 && todayX <= chartWidth && (
               <div className="absolute top-0 bottom-0 border-l-2 border-red-400 border-dashed z-10 pointer-events-none" style={{ left: todayX }}>
                 <div className="bg-red-500 text-white text-[9px] px-1 py-0.5 absolute top-0 -translate-x-1/2 rounded-b">Today</div>
               </div>
            )}

            {/* Header Dates */}
            <div className="flex border-b border-slate-100 bg-slate-50" style={{ height: HEADER_HEIGHT }}>
               {daysArray.map((d, i) => (
                  <div key={i} className="flex-shrink-0 border-r border-slate-200 flex flex-col items-center justify-center text-[10px] text-slate-600" style={{ width: DAY_WIDTH }}>
                     <span className="font-bold">{d.getDate()}</span>
                     <span className="text-[9px] text-slate-400">{d.getMonth() + 1}月</span>
                  </div>
               ))}
            </div>

            {/* Bars */}
            {sortedTasks.map(t => {
               const startX = getX(t.startDate);
               const width = getDurationWidth(t.startDate, t.endDate);

               let colorClass = 'bg-slate-300';
               if (t.status === TaskStatus.COMPLETED) colorClass = 'bg-green-500';
               else if (t.status === TaskStatus.IN_PROGRESS) colorClass = 'bg-blue-500';
               else if (t.status === TaskStatus.OVERDUE) colorClass = 'bg-red-400';

               return (
                  <div key={t.id} className="border-b border-slate-100 relative group" style={{ height: ROW_HEIGHT }}>
                     <div 
                        onClick={() => onTaskClick && onTaskClick(t)}
                        className={`absolute top-1/2 -translate-y-1/2 h-6 rounded-full shadow-sm cursor-pointer ${colorClass} hover:opacity-90 transition-opacity flex items-center px-2 overflow-hidden`}
                        style={{ left: startX, width: width }}
                        title={`${t.name} (${t.startDate} ~ ${t.endDate})`}
                     >
                        {/* Label inside bar if wide enough */}
                        {width > 60 && <span className="text-[10px] text-white font-medium truncate drop-shadow-md">{t.name}</span>}
                     </div>
                  </div>
               );
            })}
         </div>
       </div>
    </div>
  );
};


// Simple Flowchart Visualization Component using SVG/D3 logic
interface GraphProps {
  tasks: Task[];
  onTaskClick?: (task: Task) => void;
  onAddClick?: () => void;
}

const SimpleDependencyGraph: React.FC<GraphProps> = ({ tasks, onTaskClick, onAddClick }) => {
  // Sort tasks roughly by time/id to layout
  const sortedTasks = [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());

  // Basic layout logic: Assign columns based on dependency depth
  const nodes: (Task & { x: number; y: number; col: number })[] = [];
  const links: { source: string; target: string }[] = [];

  const getCol = (taskId: string, currentDepth = 0): number => {
      const task = tasks.find(t => t.id === taskId);
      if(!task) return 0;
      if(!task.dependencies || task.dependencies.length === 0) return 0;
      // Prevent infinite loop if circular dependency exists (basic check)
      if (currentDepth > 20) return 0;
      return Math.max(...task.dependencies.map(d => getCol(d, currentDepth + 1))) + 1;
  };

  sortedTasks.forEach((t, i) => {
    const col = getCol(t.id);
    const siblings = nodes.filter(n => n.col === col);
    // Dynamic layout spacing
    nodes.push({ ...t, col, x: col * 200 + 50, y: siblings.length * 100 + 50 });
    t.dependencies?.forEach(depId => {
       links.push({ source: depId, target: t.id });
    });
  });

  const width = Math.max(800, (Math.max(...nodes.map(n => n.col), 0) + 1) * 220);
  const height = Math.max(300, Math.max(...nodes.map(n => n.y), 0) + 150);

  if (tasks.length === 0) {
    return (
      <div className="p-12 text-center text-slate-400 border rounded-lg bg-slate-50 flex flex-col items-center gap-4">
        <p>目前尚無任務流程。</p>
        {onAddClick && (
          <button onClick={onAddClick} className="flex items-center gap-2 text-brand-600 font-bold hover:underline">
             <Plus size={20} /> 新增第一個任務節點
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="overflow-x-auto border rounded-lg bg-slate-50 p-4 relative">
      <div className="absolute top-2 right-2 text-xs text-slate-400 flex items-center gap-3 z-10">
        {onAddClick && (
          <button 
             onClick={onAddClick}
             className="bg-brand-600 text-white px-3 py-1.5 rounded-lg shadow-sm hover:bg-brand-700 flex items-center gap-1 text-xs font-bold transition-all"
          >
             <Plus size={14} /> 新增任務節點
          </button>
        )}
        {onTaskClick && <span className="bg-white px-2 py-1 rounded border shadow-sm">💡 點擊方塊可編輯任務</span>}
      </div>
      <svg width={width} height={height}>
        <defs>
          <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="28" refY="3.5" orient="auto">
            <polygon points="0 0, 10 3.5, 0 7" fill="#94a3b8" />
          </marker>
        </defs>
        {/* Links */}
        {links.map((link, i) => {
           const s = nodes.find(n => n.id === link.source);
           const t = nodes.find(n => n.id === link.target);
           if (!s || !t) return null;
           // Draw curved path
           const path = `M${s.x + 80},${s.y + 25} C${s.x + 130},${s.y + 25} ${t.x - 50},${t.y + 25} ${t.x},${t.y + 25}`;
           return <path key={i} d={path} stroke="#cbd5e1" strokeWidth="2" fill="none" markerEnd="url(#arrowhead)" />;
        })}
        {/* Nodes */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            transform={`translate(${node.x}, ${node.y})`}
            onClick={() => onTaskClick && onTaskClick(node)}
            style={{ cursor: onTaskClick ? 'pointer' : 'default' }}
            className={onTaskClick ? "hover:opacity-80 transition-opacity group" : ""}
          >
            <rect 
               width="160" 
               height="60" 
               rx="8" 
               fill="white" 
               stroke={node.status === TaskStatus.COMPLETED ? '#22c55e' : node.status === TaskStatus.IN_PROGRESS ? '#3b82f6' : '#e2e8f0'}
               strokeWidth="2"
               className="shadow-sm"
            />
             {/* Hover Effect Border */}
             {onTaskClick && (
              <rect width="160" height="60" rx="8" fill="transparent" stroke="#0ea5e9" strokeWidth="2" className="opacity-0 group-hover:opacity-50" />
            )}

            <text x="80" y="25" textAnchor="middle" className="text-[12px] font-bold fill-slate-700" style={{pointerEvents: 'none'}}>
                {node.name.length > 12 ? node.name.substring(0, 11) + '...' : node.name}
            </text>
            <text x="80" y="45" textAnchor="middle" className="text-[10px] fill-slate-500" style={{pointerEvents: 'none'}}>{node.department}</text>
             <text x="150" y="55" textAnchor="end" className="text-[9px] fill-slate-400" style={{pointerEvents: 'none'}}>{node.startDate}</text>
          </g>
        ))}
      </svg>
    </div>
  );
};

const ProjectHub: React.FC<ProjectHubProps> = ({ projects, tasks, users, currentUser, onAddProject, onUpdateProject, onImportTemplate, onUpdateTask, onAddTask }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [viewFilter, setViewFilter] = useState<'ALL' | 'MINE'>('ALL'); // NEW: 'ALL' or 'MINE'

  // Detail View Mode
  const [detailViewMode, setDetailViewMode] = useState<'LIST' | 'GRAPH' | 'GANTT'>('LIST');

  // NEW: State for collapsed columns
  const [collapsedStatuses, setCollapsedStatuses] = useState<ProjectStatus[]>([]);

  // Modals State
  const [isCreateModalOpen, setCreateModalOpen] = useState(false);
  const [isEditModalOpen, setEditModalOpen] = useState(false);
  const [isTemplateModalOpen, setTemplateModalOpen] = useState(false);
  const [isEditTaskModalOpen, setEditTaskModalOpen] = useState(false);

  // NEW: Create Task Modal State
  const [isCreateTaskModalOpen, setCreateTaskModalOpen] = useState(false);
  const [newTaskData, setNewTaskData] = useState<Partial<Task>>({});

  // Form Data State
  const [formData, setFormData] = useState<Partial<Project>>({
    name: '', client: '', description: '', startDate: '', endDate: '', departments: []
  });

  // Template Form State
  const [templateId, setTemplateId] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateAssignee, setTemplateAssignee] = useState('');

  // Task Edit State
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Extract all known departments from existing projects for suggestions
  const allKnownDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Extract all unique departments from projects for filter
  // MOVED UP before conditional return to avoid React Error #300
  const filterDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Filter projects based on selection and view mode
  // MOVED UP before conditional return to avoid React Error #300
  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      // 1. Department Filter
      const deptMatch = selectedDept === 'ALL' || p.departments.includes(selectedDept);

      // 2. View Mode Filter (All vs Mine)
      let viewMatch = true;
      if (viewFilter === 'MINE') {
        if (currentUser.role === UserRole.MANAGER || currentUser.role === UserRole.ADMIN) {
           // Manager sees projects they manage OR projects where they have tasks
           viewMatch = p.managerId === currentUser.id;
        } else {
           // Engineer sees projects where they have at least one task assigned
           const userTasks = tasks.filter(t => t.projectId === p.id && t.assigneeId === currentUser.id);
           viewMatch = userTasks.length > 0;
        }
      }

      return deptMatch && viewMatch;
    });
  }, [projects, tasks, selectedDept, viewFilter, currentUser]);

  const toggleColumn = (status: ProjectStatus) => {
    setCollapsedStatuses(prev => 
      prev.includes(status) ? prev.filter(s => s !== status) : [...prev, status]
    );
  };

  const openCreateModal = () => {
    setFormData({
      name: '', client: '', description: '', 
      startDate: new Date().toISOString().split('T')[0], 
      endDate: '', 
      departments: []
    });
    setCreateModalOpen(true);
  };

  const openEditModal = (project: Project) => {
    setFormData({ ...project });
    setEditModalOpen(true);
  };

  const openEditTaskModal = (task: Task) => {
    setEditingTask({ ...task });
    setEditTaskModalOpen(true);
  };

  const openCreateTaskModal = () => {
    if (!id) return;
    const project = projects.find(p => p.id === id);
    setNewTaskData({
      projectId: id,
      department: currentUser.department || project?.departments[0] || '',
      startDate: new Date().toISOString().split('T')[0],
      endDate: new Date(Date.now() + 7 * 86400000).toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      dependencies: []
    });
    setCreateTaskModalOpen(true);
  }

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.client) return;

    const newProject: Project = {
      id: `p-${Date.now()}`,
      name: formData.name!,
      client: formData.client!,
      description: formData.description || '',
      startDate: formData.startDate!,
      endDate: formData.endDate!,
      departments: formData.departments || [],
      status: ProjectStatus.PLANNING, // Default status
      managerId: currentUser.id // Admin is creator
    };

    onAddProject(newProject);
    setCreateModalOpen(false);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.id) {
       onUpdateProject(formData as Project);
       setEditModalOpen(false);
    }
  };

  const handleTemplateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (id && templateId && templateStartDate) {
      onImportTemplate(id, templateId, templateStartDate, templateAssignee || currentUser.id);
      setTemplateModalOpen(false);
      setTemplateId('');
      setTemplateStartDate('');
      setTemplateAssignee('');
    }
  };

  const handleEditTaskSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingTask) {
      onUpdateTask(editingTask);
      setEditTaskModalOpen(false);
      setEditingTask(null);
    }
  };

  const handleCreateTaskSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newTaskData.name && newTaskData.projectId && newTaskData.assigneeId) {
       const newTask: Task = {
          id: `t-${Date.now()}`,
          projectId: newTaskData.projectId,
          name: newTaskData.name,
          assigneeId: newTaskData.assigneeId,
          startDate: newTaskData.startDate!,
          endDate: newTaskData.endDate!,
          status: TaskStatus.NOT_STARTED,
          department: newTaskData.department!,
          dependencies: newTaskData.dependencies || [],
          isAdHoc: false
       };
       onAddTask(newTask);
       setCreateTaskModalOpen(false);
       setNewTaskData({});
    }
  };

  const toggleDependency = (targetTaskId: string) => {
      if (!editingTask) return;
      const currentDeps = editingTask.dependencies || [];
      if (currentDeps.includes(targetTaskId)) {
          setEditingTask({ ...editingTask, dependencies: currentDeps.filter(d => d !== targetTaskId) });
      } else {
          setEditingTask({ ...editingTask, dependencies: [...currentDeps, targetTaskId] });
      }
  };

  const toggleDependencyForNewTask = (targetTaskId: string) => {
      const currentDeps = newTaskData.dependencies || [];
      if (currentDeps.includes(targetTaskId)) {
          setNewTaskData({ ...newTaskData, dependencies: currentDeps.filter(d => d !== targetTaskId) });
      } else {
          setNewTaskData({ ...newTaskData, dependencies: [...currentDeps, targetTaskId] });
      }
  };

  const autoSetStartDate = () => {
      if (!editingTask || !editingTask.dependencies || editingTask.dependencies.length === 0) return;

      const parentTasks = tasks.filter(t => editingTask.dependencies.includes(t.id));
      if (parentTasks.length === 0) return;

      // Find the max end date of parents
      const maxEndDate = parentTasks.reduce((max, task) => {
          const end = new Date(task.endDate);
          return end > max ? end : max;
      }, new Date(0));

      if (maxEndDate.getTime() > 0) {
          // Set to next day
          const nextDay = new Date(maxEndDate);
          nextDay.setDate(nextDay.getDate() + 1);
          setEditingTask({ ...editingTask, startDate: nextDay.toISOString().split('T')[0] });
      }
  };

  const toggleDepartment = (dept: string) => {
    const current = formData.departments || [];
    if (current.includes(dept)) {
      setFormData({ ...formData, departments: current.filter(d => d !== dept) });
    } else {
      setFormData({ ...formData, departments: [...current, dept] });
    }
  };

  // Render Modal Form Content (Shared fields)
  const renderFormFields = () => (
    <>
       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">專案名稱</label>
            <input 
              type="text" 
              required
              value={formData.name} 
              onChange={e => setFormData({...formData, name: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">客戶名稱</label>
            <input 
              type="text" 
              required
              value={formData.client} 
              onChange={e => setFormData({...formData, client: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">開始日期</label>
            <input 
              type="date" 
              value={formData.startDate} 
              onChange={e => setFormData({...formData, startDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">預計結束日期</label>
            <input 
              type="date" 
              value={formData.endDate} 
              onChange={e => setFormData({...formData, endDate: e.target.value})}
              className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
            />
          </div>
       </div>

       <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">專案描述</label>
          <textarea 
            rows={3}
            value={formData.description} 
            onChange={e => setFormData({...formData, description: e.target.value})}
            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
          />
       </div>

       {/* Department Assignment */}
       <div>
         <label className="block text-sm font-medium text-slate-700 mb-2">指派參與部門</label>
         <div className="border border-slate-200 rounded-lg p-3 bg-slate-50 max-h-32 overflow-y-auto grid grid-cols-2 gap-2">
            {allKnownDepartments.map(dept => (
              <label key={dept} className="flex items-center gap-2 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={formData.departments?.includes(dept)} 
                  onChange={() => toggleDepartment(dept)}
                  className="rounded text-brand-600 focus:ring-brand-500"
                />
                <span className="text-sm text-slate-600">{dept}</span>
              </label>
            ))}
         </div>
         <p className="text-xs text-slate-400 mt-1">選取後，各部門主管將會收到通知並安排詳細任務流程。</p>
       </div>
    </>
  );

  // --- DETAIL VIEW ---
  if (id) {
    const project = projects.find(p => p.id === id);
    if (!project) return <div>Project not found</div>;

    const projectTasks = tasks.filter(t => t.projectId === id);
    const isDeptManager = currentUser.role === UserRole.MANAGER && project.departments.includes(currentUser.department);
    const canEditTasks = isDeptManager || currentUser.role === UserRole.ADMIN;
    const canEditStatus = currentUser.role === UserRole.ADMIN;

    const availableTemplates = getTaskTemplates().filter(t => t.department === currentUser.department);

    return (
      <div className="space-y-6 animate-in fade-in duration-300">
        {/* Breadcrumb */}
        <button onClick={() => navigate('/projects')} className="flex items-center text-sm text-slate-500 hover:text-brand-600 mb-4">
          <ArrowLeft size={16} className="mr-1" /> 返回專案列表
        </button>

        {/* Project Header */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">{project.name}</h1>
              {/* Quick Status Selector in Detail View */}
              <QuickStatusSelector 
                project={project} 
                canEdit={canEditStatus} 
                onUpdateStatus={(s) => onUpdateProject({...project, status: s})} 
              />
            </div>
            <p className="text-slate-500 mt-2">{project.description}</p>
            <div className="flex items-center gap-6 mt-4 text-sm text-slate-500">
               <span className="flex items-center gap-1"><Calendar size={14} /> {project.startDate} - {project.endDate}</span>
               <span className="flex items-center gap-1"><UserCircle size={14} /> 客戶: {project.client}</span>
            </div>
            <div className="flex gap-2 mt-4">
              <span className="text-xs font-bold text-slate-400 py-1">參與部門:</span>
              {project.departments.map(d => (
