                    <Network size={16} /> 流程圖
                  </button>
                   <button 
                    onClick={() => setDetailViewMode('GANTT')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'GANTT' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
