                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">負責人</label>
                        <select 
                          value={editingTask.assigneeId}
                          onChange={e => setEditingTask({...editingTask, assigneeId: e.target.value})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                          {users.filter(u => u.department === editingTask.department || u.role === UserRole.ENGINEER).map(u => (
                            <option key={u.id} value={u.id}>{u.name} - {u.department}</option>
                          ))}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">狀態</label>
                        <select 
                          value={editingTask.status}
                          onChange={e => setEditingTask({...editingTask, status: e.target.value as TaskStatus})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                        >
                           {Object.entries(TASK_STATUS_MAP).map(([key, label]) => (
                             <option key={key} value={key}>{label}</option>
                           ))}
                        </select>
                    </div>
                 </div>

                 {/* Dependencies Section */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
                        <Link size={14} /> 前置任務 (本任務將在以下任務後進行)
