                             {editingTask.dependencies?.includes(t.id) && <ArrowRight size={12} className="text-brand-500"/>}
                          </label>
                        ))}
                        {projectTasks.length <= 1 && <div className="text-xs text-slate-400 italic text-center">無其他任務可選</div>}
                    </div>
                    {editingTask.dependencies && editingTask.dependencies.length > 0 && (
                       <p className="text-xs text-brand-600 mt-2 flex items-center gap-1">
