           </div>

           <div className="h-6 w-px bg-slate-200 mx-2"></div>

           {/* Department Filters */}
           <div className="flex items-center gap-2">
              <span className="text-xs text-slate-400 font-bold uppercase tracking-wider">部門過濾:</span>
              <select 
                value={selectedDept}
                onChange={(e) => setSelectedDept(e.target.value)}
