import React, { useState, useEffect } from 'react';
import { TaskTemplate, TemplateStep, User } from '../types';
import { Plus, Trash2, Save, GripVertical, ChevronRight, ArrowRight, LayoutList, Workflow } from 'lucide-react';

interface TemplateEditorProps {
  templates: TaskTemplate[];
  users: User[];
  onAddTemplate: (template: TaskTemplate) => void;
  onUpdateTemplate: (template: TaskTemplate) => void;
  onDeleteTemplate: (id: string) => void;
}

const TemplateEditor: React.FC<TemplateEditorProps> = ({ templates, users, onAddTemplate, onUpdateTemplate, onDeleteTemplate }) => {
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);

  // Editing State
  const [editName, setEditName] = useState('');
  const [editDept, setEditDept] = useState('');
  const [editSteps, setEditSteps] = useState<TemplateStep[]>([]);
  const [isDirty, setIsDirty] = useState(false);

  // Derive Departments from Users
  const departments = Array.from(new Set(users.map(u => u.department))).sort();

  useEffect(() => {
    if (selectedTemplateId) {
      const t = templates.find(t => t.id === selectedTemplateId);
      if (t) {
        setEditName(t.name);
        setEditDept(t.department);
        setEditSteps([...t.steps]); // Clone to avoid direct mutation
        setIsDirty(false);
      }
    } else {
       // Reset or keep blank
       setEditName('');
       setEditDept(departments[0] || '');
       setEditSteps([]);
       setIsDirty(false);
    }
  }, [selectedTemplateId, templates]);

  const handleSelectTemplate = (id: string) => {
    if (isDirty && !window.confirm("您有未儲存的變更，確定要切換模板嗎？")) {
      return;
    }
    setSelectedTemplateId(id);
  };

  const handleCreateNew = () => {
     if (isDirty && !window.confirm("您有未儲存的變更，確定要建立新模板嗎？")) {
      return;
    }
    const newId = `tmpl-${Date.now()}`;
    const newTemplate: TaskTemplate = {
      id: newId,
      name: '新流程模板',
      department: departments[0] || '一般',
      steps: [
        { name: '第一階段', durationDays: 7, offsetStart: 0 }
      ]
    };
    onAddTemplate(newTemplate);
    setSelectedTemplateId(newId);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("確定要刪除此模板嗎？此動作無法復原。")) {
      onDeleteTemplate(id);
      if (selectedTemplateId === id) setSelectedTemplateId(null);
    }
  };

  const handleSave = () => {
    if (!selectedTemplateId) return;
    const updated: TaskTemplate = {
      id: selectedTemplateId,
      name: editName,
      department: editDept,
      steps: editSteps
    };
    onUpdateTemplate(updated);
    setIsDirty(false);
    alert('模板已儲存！');
  };

  // Step Operations
  const updateStep = (index: number, field: keyof TemplateStep, value: any) => {
    const newSteps = [...editSteps];
    newSteps[index] = { ...newSteps[index], [field]: value };
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  const addStep = () => {
    const lastStep = editSteps[editSteps.length - 1];
    const newOffset = lastStep ? lastStep.offsetStart + lastStep.durationDays : 0;
    setEditSteps([...editSteps, { name: '新任務步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  const removeStep = (index: number) => {
    const newSteps = [...editSteps];
    newSteps.splice(index, 1);
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  // Sort templates for list
  const sortedTemplates = [...templates].sort((a, b) => a.department.localeCompare(b.department));

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
          <Workflow className="text-brand-600" /> 任務流程模板編輯器
        </h2>
        <button 
          onClick={handleCreateNew}
          className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
        >
          <Plus size={16} /> 建立新模板
        </button>
      </div>

      <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">

        {/* Sidebar List */}
        <div className="col-span-4 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden">
           <div className="p-4 border-b border-slate-100 bg-slate-50">
             <h3 className="font-semibold text-slate-700">現有模板 ({templates.length})</h3>
           </div>
           <div className="flex-1 overflow-y-auto p-2 space-y-2">
             {sortedTemplates.map(t => (
               <div 
                 key={t.id}
                 onClick={() => handleSelectTemplate(t.id)}
                 className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedTemplateId === t.id ? 'bg-brand-50 border-brand-200 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
               >
                 <div className="flex justify-between items-start">
                   <div>
                     <h4 className={`font-bold text-sm ${selectedTemplateId === t.id ? 'text-brand-700' : 'text-slate-700'}`}>{t.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">{t.department} • {t.steps.length} 步驟</p>
                   </div>
                   {selectedTemplateId === t.id && <ChevronRight size={16} className="text-brand-400 mt-1" />}
                 </div>
               </div>
             ))}
           </div>
        </div>

        {/* Main Editor Area */}
        <div className="col-span-8 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden relative">
           {!selectedTemplateId ? (
             <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
               <Workflow size={48} className="mb-4 opacity-20" />
               <p>請選擇左側模板或建立新模板</p>
             </div>
           ) : (
             <>
               {/* Header Controls */}
               <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-start">
                  <div className="flex-1 grid grid-cols-2 gap-4 mr-8">
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">模板名稱</label>
                       <input 
                         type="text" 
                         value={editName}
                         onChange={(e) => { setEditName(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-brand-500"
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">所屬部門</label>
                       <select 
                         value={editDept}
                         onChange={(e) => { setEditDept(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-brand-500"
                       >
                         {departments.map(d => <option key={d} value={d}>{d}</option>)}
                       </select>
                     </div>
                  </div>
                  <div className="flex gap-2">
                     <button 
                       onClick={() => handleDelete(selectedTemplateId)}
                       className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded"
                       title="刪除模板"
                     >
                       <Trash2 size={18} />
                     </button>
                     <button 
                       onClick={handleSave}
                       disabled={!isDirty}
                       className={`flex items-center gap-2 px-4 py-2 rounded text-sm font-bold shadow-sm transition-all ${isDirty ? 'bg-brand-600 text-white hover:bg-brand-700' : 'bg-slate-200 text-slate-400 cursor-default'}`}
                     >
                       <Save size={16} /> 儲存
                     </button>
                  </div>
               </div>

               {/* Steps List */}
               <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                  <div className="flex justify-between items-center mb-4">
                     <h3 className="font-bold text-slate-700 flex items-center gap-2"><LayoutList size={18}/> 流程步驟定義</h3>
                     <button onClick={addStep} className="text-xs bg-white border border-slate-300 px-3 py-1.5 rounded-lg font-medium text-slate-600 hover:text-brand-600 hover:border-brand-300 shadow-sm flex items-center gap-1">
                        <Plus size={14} /> 新增步驟
                     </button>
                  </div>

                  <div className="space-y-3">
                    {editSteps.map((step, index) => (
                      <div key={index} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4 group">
                         <div className="text-slate-300 cursor-move"><GripVertical size={20} /></div>
                         <div className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-500 text-xs font-bold border border-slate-200">
                           {index + 1}
                         </div>

                         <div className="flex-1 grid grid-cols-12 gap-4 items-center">
                            <div className="col-span-6">
                              <label className="block text-[10px] text-slate-400 mb-0.5">任務名稱</label>
                              <input 
                                type="text" 
                                value={step.name}
                                onChange={(e) => updateStep(index, 'name', e.target.value)}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm font-medium text-slate-800 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">工期 (天)</label>
                               <input 
                                type="number" 
                                min="1"
                                value={step.durationDays}
                                onChange={(e) => updateStep(index, 'durationDays', parseInt(e.target.value))}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">開始偏移 (第幾天)</label>
                               <div className="flex items-center gap-2">
                                 <ArrowRight size={12} className="text-slate-300" />
                                 <input 
                                  type="number" 
                                  min="0"
                                  value={step.offsetStart}
                                  onChange={(e) => updateStep(index, 'offsetStart', parseInt(e.target.value))}
                                  className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                                />
                               </div>
                            </div>
                         </div>

                         <button 
                           onClick={() => removeStep(index)}
                           className="text-slate-300 hover:text-red-500 p-2 opacity-0 group-hover:opacity-100 transition-opacity"
                         >
                           <Trash2 size={16} />
                         </button>
                      </div>
                    ))}
                    {editSteps.length === 0 && (
                      <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-lg text-slate-400">
                         此模板尚未定義任何步驟
                      </div>
                    )}
                  </div>
               </div>

               {/* Timeline Preview (Simple) */}
               <div className="h-24 border-t border-slate-200 bg-white p-4 overflow-x-auto whitespace-nowrap flex items-center gap-1">
                  {editSteps.length > 0 && editSteps.map((step, i) => (
                    <React.Fragment key={i}>
                       <div className="inline-flex flex-col justify-center h-12 bg-blue-50 border border-blue-100 rounded px-2 min-w-[100px]" style={{ width: Math.max(100, step.durationDays * 10) }}>
                          <span className="text-[10px] font-bold text-blue-800 truncate">{step.name}</span>
                          <span className="text-[9px] text-blue-500">Day {step.offsetStart} - {step.offsetStart + step.durationDays}</span>
                       </div>
                       {i < editSteps.length - 1 && <ArrowRight size={12} className="text-slate-300 mx-1" />}
                    </React.Fragment>
                  ))}
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

export default TemplateEditor;

