  ProjectStatus.PLANNING,
  ProjectStatus.QUOTE_NEEDED,
  ProjectStatus.QUOTED,
  ProjectStatus.IN_PROGRESS,
  ProjectStatus.ACCEPTANCE,
  ProjectStatus.COMPLETED,
