                  <h3 className="text-lg font-bold text-slate-800">新增任務節點</h3>
                  <p className="text-xs text-slate-400 mt-1">專案: {project.name}</p>
                </div>
                <button onClick={() => setCreateTaskModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
