                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setEditModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Save size={16} /> 儲存變更
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- LIST VIEW ---

  // Use filterDepartments (already calculated at top)

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center flex-shrink-0">
        <h2 className="text-2xl font-bold text-slate-900">專案中心</h2>
        {currentUser.role === UserRole.ADMIN && (
          <button 
            onClick={openCreateModal}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增專案
          </button>
        )}
      </div>

      {/* Control Bar: View Mode & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-4 pb-2 flex-shrink-0 bg-white p-3 rounded-xl border border-slate-100 shadow-sm">

        {/* Left: View Mode Toggle */}
        <div className="flex items-center gap-2">
           <div className="flex bg-slate-100 p-1 rounded-lg">
             <button
               onClick={() => setViewFilter('ALL')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'ALL' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <Layers size={16} />
               全部專案
             </button>
             <button
               onClick={() => setViewFilter('MINE')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'MINE' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <UserIcon size={16} />
               {currentUser.role === UserRole.ENGINEER ? '我參與的' : '我負責的'}
             </button>
           </div>

           <div className="h-6 w-px bg-slate-200 mx-2"></div>

           {/* Department Filters */}
           <div className="flex items-center gap-2">
              <span className="text-xs text-slate-400 font-bold uppercase tracking-wider">部門過濾:</span>
              <select 
                value={selectedDept}
                onChange={(e) => setSelectedDept(e.target.value)}
                className="text-sm border-none bg-transparent font-medium text-slate-600 focus:ring-0 cursor-pointer hover:text-slate-900"
              >
                <option value="ALL">全部部門</option>
                {filterDepartments.map(dept => (
                  <option key={dept} value={dept}>{dept}</option>
                ))}
              </select>
           </div>
        </div>

        {/* Right: Legend or Help text */}
        <div className="hidden md:flex items-center gap-3 text-xs text-slate-400">
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-slate-400"></span> 規劃</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-500"></span> 進行</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> 完成</span>
        </div>
      </div>

      {/* Kanban Board Layout */}
      <div className="flex-1 overflow-x-auto overflow-y-hidden pb-4">
        {filteredProjects.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300 w-full h-40 flex items-center justify-center">
             <div className="flex flex-col items-center gap-2">
                <p className="text-slate-500 font-medium">沒有符合條件的專案。</p>
                <p className="text-xs text-slate-400">請嘗試切換「檢視模式」或「部門過濾器」。</p>
             </div>
          </div>
        ) : (
          <div className="flex gap-4 h-full min-w-max px-1 items-stretch">
            {STATUS_ORDER.map(statusKey => {
              const config = STATUS_CONFIG[statusKey];
              const statusProjects = filteredProjects.filter(p => p.status === statusKey);
              const isCollapsed = collapsedStatuses.includes(statusKey);

              // --- COLLAPSED COLUMN RENDER ---
              if (isCollapsed) {
                return (
                  <div 
                    key={statusKey} 
                    onClick={() => toggleColumn(statusKey)}
                    className={`w-12 flex-shrink-0 flex flex-col items-center bg-slate-50 hover:bg-slate-100 rounded-xl py-4 h-full border border-slate-200 cursor-pointer transition-colors group`}
                    title={`點擊展開 ${config.label}`}
                  >
                     <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-4 ${config.color} border shadow-sm`}>
                        <span className="font-bold text-xs">{statusProjects.length}</span>
                     </div>
                     <div className="flex-1 flex items-center justify-center">
                        <span className="writing-vertical-rl text-sm font-bold text-slate-500 tracking-widest whitespace-nowrap rotate-180 group-hover:text-slate-800 transition-colors">
                           {config.label}
                        </span>
                     </div>
                     <div className="mt-4 text-slate-400 group-hover:text-brand-600">
                        <ChevronRight size={16} />
                     </div>
                  </div>
                );
              }

              // --- EXPANDED COLUMN RENDER ---
              return (
                <div key={statusKey} className="w-80 flex-shrink-0 flex flex-col bg-slate-50/50 rounded-xl p-2 h-full border border-slate-200">
                  {/* Column Header */}
                  <div className={`flex items-center gap-2 mb-3 p-3 rounded-lg border shadow-sm ${config.headerBg} ${config.border} group relative`}>
                     <span className={`w-2.5 h-2.5 rounded-full ${config.dot}`}></span>
                     <h3 className="font-bold text-slate-700 text-sm flex-1">{config.label}</h3>
                     <span className="text-xs font-bold text-slate-500 bg-white/60 px-2 py-0.5 rounded-full">
                        {statusProjects.length}
                     </span>

                     {/* Collapse Button (Visible on hover) */}
                     <button 
                       onClick={(e) => { e.stopPropagation(); toggleColumn(statusKey); }}
                       className="absolute right-10 opacity-0 group-hover:opacity-100 p-1 hover:bg-black/5 rounded text-slate-500 transition-opacity"
                       title="收折欄位"
                     >
                        <ChevronLeft size={14} />
                     </button>
                  </div>

                  {/* Cards Container */}
                  <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                    {statusProjects.length === 0 && (
                      <div className="h-32 border-2 border-dashed border-slate-200 rounded-lg flex flex-col items-center justify-center text-slate-300 gap-2">
                        <div className={`w-2 h-2 rounded-full ${config.dot} opacity-20`}></div>
                        <span className="text-xs">尚無專案</span>
                      </div>
                    )}
                    {statusProjects.map(project => {
                      const pTasks = tasks.filter(t => t.projectId === project.id);
                      const activeCount = pTasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length;
                      const canEditStatus = currentUser.role === UserRole.ADMIN;

                      return (
                        <div key={project.id} onClick={() => navigate(`/projects/${project.id}`)} className="bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:shadow-md hover:border-brand-300 transition-all cursor-pointer group flex flex-col gap-2 relative">
                           {/* Card Top */}
                           <div className="flex justify-between items-start">
                              <span className="text-[10px] font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100 truncate max-w-[120px]">
                                {project.client}
                              </span>
                              <div onClick={(e) => e.stopPropagation()}>
                                <QuickStatusSelector 
                                   project={project}
                                   canEdit={canEditStatus}
                                   onUpdateStatus={(s) => onUpdateProject({...project, status: s})}
                                />
                              </div>
                           </div>

                           {/* Card Main */}
                           <div>
                              <h4 className="font-bold text-slate-800 text-sm leading-snug mb-1 group-hover:text-brand-700 transition-colors">
                                {project.name}
                              </h4>
                              <div className="flex flex-wrap gap-1 mt-1">
                                {project.departments.map(d => (
                                  <span key={d} className="text-[9px] px-1 py-0.5 bg-slate-50 text-slate-500 border border-slate-100 rounded">
                                    {d}
                                  </span>
                                ))}
                              </div>
                           </div>

                           {/* Card Footer */}
                           <div className="flex items-center justify-between text-[10px] text-slate-400 border-t border-slate-50 pt-2 mt-1">
                              <div className="flex items-center gap-1" title="進行中任務">
                                <CheckSquare size={12} className={activeCount > 0 ? "text-brand-500" : ""} />
                                <span>{activeCount}</span>
                              </div>
                              <div className="flex items-center gap-1">
                                <Clock size={12} />
                                <span>{project.endDate}</span>
                              </div>
                           </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Create Project Modal */}
      {isCreateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">建立新專案</h3>
                <button onClick={() => setCreateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleCreateSubmit} className="space-y-4">
                {renderFormFields()}
                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setCreateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Plus size={16} /> 建立專案
                  </button>
                </div>
              </form>
            </div>
          </div>
      )}
    </div>
  );
};

export default ProjectHub;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ProjectHub from './components/ProjectHub';
import TaskManager from './components/TaskManager';
import ScheduleStats from './components/ScheduleStats';
import AssetBooking from './components/AssetBooking';
import TeamManagement from './components/TeamManagement';
import TemplateEditor from './components/TemplateEditor';
import { 
  getProjects, getTasks, getUsers, getEvents, getNotices, getAssets, getTaskTemplates,
  getUserById, addTask, updateTaskStatus, updateUser, addEvent, addProject, updateProject,
  addTasksFromTemplate, updateTask, addNotice, updateNotice, deleteNotice,
  addTemplate, updateTemplate, deleteTemplate
} from './services/mockService';
import { User, Project, Task, ScheduleEvent, Notice, Asset, TaskStatus, UserRole, TaskTemplate } from './types';

const App: React.FC = () => {
  // Global App State
  const [currentUser, setCurrentUser] = useState<User | undefined>(undefined);
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [templates, setTemplates] = useState<TaskTemplate[]>([]);

  // Initialization
  useEffect(() => {
    // Load mock data
    const allUsers = getUsers();
    setUsers(allUsers);
    setCurrentUser(allUsers[0]); // Default to Admin
    setProjects(getProjects());
    setTasks(getTasks());
    setEvents(getEvents());
    setNotices(getNotices());
    setAssets(getAssets());
    setTemplates(getTaskTemplates());
  }, []);

  const handleSwitchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const handleAddTask = (newTask: Task) => {
    addTask(newTask);
    setTasks([...getTasks()]); // Refresh from service
  };

  const handleUpdateTask = (id: string, status: TaskStatus) => {
    updateTaskStatus(id, status);
    setTasks([...getTasks()]); // Refresh
  };

  const handleFullUpdateTask = (task: Task) => {
    updateTask(task);
    setTasks([...getTasks()]);
  };

  const handleUpdateUser = (updatedUser: User) => {
    updateUser(updatedUser);
    setUsers([...getUsers()]); // Refresh
    // If updating current user self
    if (currentUser && currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
    }
  };

  const handleAddProject = (newProject: Project) => {
    addProject(newProject);
    setProjects([...getProjects()]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    updateProject(updatedProject);
    setProjects([...getProjects()]);
  };

  const handleAddEvent = (newEvent: ScheduleEvent) => {
    addEvent(newEvent);
    setEvents([...getEvents()]);
  }

  const handleImportTemplate = (projectId: string, templateId: string, startDate: string, assigneeId: string) => {
    addTasksFromTemplate(projectId, templateId, startDate, assigneeId);
    setTasks([...getTasks()]);
  };

  const handleAddNotice = (notice: Notice) => {
    addNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleUpdateNotice = (notice: Notice) => {
    updateNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleDeleteNotice = (id: string) => {
    deleteNotice(id);
    setNotices([...getNotices()]);
  };

  // Template Handlers
  const handleAddTemplate = (template: TaskTemplate) => {
    addTemplate(template);
    setTemplates([...getTaskTemplates()]);
  };

  const handleUpdateTemplate = (template: TaskTemplate) => {
    updateTemplate(template);
    setTemplates([...getTaskTemplates()]);
  };

  const handleDeleteTemplate = (id: string) => {
    deleteTemplate(id);
    setTemplates([...getTaskTemplates()]);
  };

  if (!currentUser) return <div className="flex items-center justify-center h-screen">載入中...</div>;

  return (
    <HashRouter>
      <Layout currentUser={currentUser} onSwitchUser={handleSwitchUser} users={users}>
        <Routes>
          <Route 
            path="/" 
            element={
              <Dashboard 
                user={currentUser} 
                users={users}
                projects={projects} 
                tasks={tasks} 
                events={events} 
                notices={notices} 
                onAddNotice={handleAddNotice}
                onUpdateNotice={handleUpdateNotice}
                onDeleteNotice={handleDeleteNotice}
              />
            } 
          />
          <Route 
            path="/projects" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                templates={templates}
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
                onAddTask={handleAddTask}
              />
            } 
          />
          <Route 
            path="/projects/:id" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser}
                templates={templates} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
                onAddTask={handleAddTask}
              />
            } 
          />
          <Route path="/tasks" element={<TaskManager tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} />} />
          <Route path="/schedule" element={<ScheduleStats events={events} tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddEvent={handleAddEvent} />} />
          <Route path="/assets" element={<AssetBooking assets={assets} />} />

          {/* Admin & Manager Routes */}
          {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
             <Route 
               path="/templates" 
               element={
                 <TemplateEditor 
                   templates={templates} 
                   users={users} 
                   onAddTemplate={handleAddTemplate}
                   onUpdateTemplate={handleUpdateTemplate}
                   onDeleteTemplate={handleDeleteTemplate}
                 />
               } 
             />
          )}

          {/* Admin Only Route */}
          {currentUser.role === UserRole.ADMIN && (
             <Route path="/team" element={<TeamManagement users={users} onUpdateUser={handleUpdateUser} />} />
          )}

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { TaskTemplate, TemplateStep, User } from '../types';
import { Plus, Trash2, Save, GripVertical, ChevronRight, ArrowRight, LayoutList, Workflow } from 'lucide-react';

interface TemplateEditorProps {
  templates: TaskTemplate[];
  users: User[];
  onAddTemplate: (template: TaskTemplate) => void;
  onUpdateTemplate: (template: TaskTemplate) => void;
  onDeleteTemplate: (id: string) => void;
}

const TemplateEditor: React.FC<TemplateEditorProps> = ({ templates, users, onAddTemplate, onUpdateTemplate, onDeleteTemplate }) => {
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);

  // Editing State
  const [editName, setEditName] = useState('');
  const [editDept, setEditDept] = useState('');
  const [editSteps, setEditSteps] = useState<TemplateStep[]>([]);
  const [isDirty, setIsDirty] = useState(false);

  // Derive Departments from Users
  const departments = Array.from(new Set(users.map(u => u.department))).sort();

  useEffect(() => {
    if (selectedTemplateId) {
      const t = templates.find(t => t.id === selectedTemplateId);
      if (t) {
        setEditName(t.name);
        setEditDept(t.department);
        setEditSteps([...t.steps]); // Clone to avoid direct mutation
        setIsDirty(false);
      }
    } else {
       // Reset or keep blank
       setEditName('');
       setEditDept((departments[0] as string) || '');
       setEditSteps([]);
       setIsDirty(false);
    }
  }, [selectedTemplateId, templates]);

  const handleSelectTemplate = (id: string) => {
    if (isDirty && !window.confirm("您有未儲存的變更，確定要切換模板嗎？")) {
      return;
    }
    setSelectedTemplateId(id);
  };

  const handleCreateNew = () => {
     if (isDirty && !window.confirm("您有未儲存的變更，確定要建立新模板嗎？")) {
      return;
    }
    const newId = `tmpl-${Date.now()}`;
    const newTemplate: TaskTemplate = {
      id: newId,
      name: '新流程模板',
      department: departments[0] || '一般',
      steps: [
        { name: '第一階段', durationDays: 7, offsetStart: 0 }
      ]
    };
    onAddTemplate(newTemplate);
    setSelectedTemplateId(newId);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("確定要刪除此模板嗎？此動作無法復原。")) {
      onDeleteTemplate(id);
      if (selectedTemplateId === id) setSelectedTemplateId(null);
    }
  };

  const handleSave = () => {
    if (!selectedTemplateId) return;
    const updated: TaskTemplate = {
      id: selectedTemplateId,
      name: editName,
      department: editDept,
      steps: editSteps
    };
    onUpdateTemplate(updated);
    setIsDirty(false);
    alert('模板已儲存！');
  };

  // Step Operations
  const updateStep = (index: number, field: keyof TemplateStep, value: any) => {
    const newSteps = [...editSteps];
    newSteps[index] = { ...newSteps[index], [field]: value };
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  const addStep = () => {
    const lastStep = editSteps[editSteps.length - 1];
    const newOffset = lastStep ? lastStep.offsetStart + lastStep.durationDays : 0;
    setEditSteps([...editSteps, { name: '新任務步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  const removeStep = (index: number) => {
    const newSteps = [...editSteps];
    newSteps.splice(index, 1);
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  // Sort templates for list
  const sortedTemplates = [...templates].sort((a, b) => a.department.localeCompare(b.department));

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
          <Workflow className="text-brand-600" /> 任務流程模板編輯器
        </h2>
        <button 
          onClick={handleCreateNew}
          className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
        >
          <Plus size={16} /> 建立新模板
        </button>
      </div>

      <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">

        {/* Sidebar List */}
        <div className="col-span-4 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden">
           <div className="p-4 border-b border-slate-100 bg-slate-50">
             <h3 className="font-semibold text-slate-700">現有模板 ({templates.length})</h3>
           </div>
           <div className="flex-1 overflow-y-auto p-2 space-y-2">
             {sortedTemplates.map(t => (
               <div 
                 key={t.id}
                 onClick={() => handleSelectTemplate(t.id)}
                 className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedTemplateId === t.id ? 'bg-brand-50 border-brand-200 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
               >
                 <div className="flex justify-between items-start">
                   <div>
                     <h4 className={`font-bold text-sm ${selectedTemplateId === t.id ? 'text-brand-700' : 'text-slate-700'}`}>{t.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">{t.department} • {t.steps.length} 步驟</p>
                   </div>
                   {selectedTemplateId === t.id && <ChevronRight size={16} className="text-brand-400 mt-1" />}
                 </div>
               </div>
             ))}
           </div>
        </div>

        {/* Main Editor Area */}
        <div className="col-span-8 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden relative">
           {!selectedTemplateId ? (
             <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
               <Workflow size={48} className="mb-4 opacity-20" />
               <p>請選擇左側模板或建立新模板</p>
             </div>
           ) : (
             <>
               {/* Header Controls */}
               <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-start">
                  <div className="flex-1 grid grid-cols-2 gap-4 mr-8">
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">模板名稱</label>
                       <input 
                         type="text" 
                         value={editName}
                         onChange={(e) => { setEditName(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-brand-500"
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">所屬部門</label>
                       <select 
                         value={editDept}
                         onChange={(e) => { setEditDept(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-brand-500"
                       >
                         {departments.map(d => <option key={d} value={d}>{d}</option>)}
                       </select>
                     </div>
                  </div>
                  <div className="flex gap-2">
                     <button 
                       onClick={() => handleDelete(selectedTemplateId)}
                       className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded"
                       title="刪除模板"
                     >
                       <Trash2 size={18} />
                     </button>
                     <button 
                       onClick={handleSave}
                       disabled={!isDirty}
                       className={`flex items-center gap-2 px-4 py-2 rounded text-sm font-bold shadow-sm transition-all ${isDirty ? 'bg-brand-600 text-white hover:bg-brand-700' : 'bg-slate-200 text-slate-400 cursor-default'}`}
                     >
                       <Save size={16} /> 儲存
                     </button>
                  </div>
               </div>

               {/* Steps List */}
               <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                  <div className="flex justify-between items-center mb-4">
                     <h3 className="font-bold text-slate-700 flex items-center gap-2"><LayoutList size={18}/> 流程步驟定義</h3>
                     <button onClick={addStep} className="text-xs bg-white border border-slate-300 px-3 py-1.5 rounded-lg font-medium text-slate-600 hover:text-brand-600 hover:border-brand-300 shadow-sm flex items-center gap-1">
                        <Plus size={14} /> 新增步驟
                     </button>
                  </div>

                  <div className="space-y-3">
                    {editSteps.map((step, index) => (
                      <div key={index} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4 group">
                         <div className="text-slate-300 cursor-move"><GripVertical size={20} /></div>
                         <div className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-100 text-slate-500 text-xs font-bold border border-slate-200">
                           {index + 1}
                         </div>

                         <div className="flex-1 grid grid-cols-12 gap-4 items-center">
                            <div className="col-span-6">
                              <label className="block text-[10px] text-slate-400 mb-0.5">任務名稱</label>
                              <input 
                                type="text" 
                                value={step.name}
                                onChange={(e) => updateStep(index, 'name', e.target.value)}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm font-medium text-slate-800 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">工期 (天)</label>
                               <input 
                                type="number" 
                                min="1"
                                value={step.durationDays}
                                onChange={(e) => updateStep(index, 'durationDays', parseInt(e.target.value))}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">開始偏移 (第幾天)</label>
                               <div className="flex items-center gap-2">
                                 <ArrowRight size={12} className="text-slate-300" />
                                 <input 
                                  type="number" 
                                  min="0"
                                  value={step.offsetStart}
                                  onChange={(e) => updateStep(index, 'offsetStart', parseInt(e.target.value))}
                                  className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                                />
                               </div>
                            </div>
                         </div>

                         <button 
                           onClick={() => removeStep(index)}
                           className="text-slate-300 hover:text-red-500 p-2 opacity-0 group-hover:opacity-100 transition-opacity"
                         >
                           <Trash2 size={16} />
                         </button>
                      </div>
                    ))}
                    {editSteps.length === 0 && (
                      <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-lg text-slate-400">
                         此模板尚未定義任何步驟
                      </div>
                    )}
                  </div>
               </div>

               {/* Timeline Preview (Simple) */}
               <div className="h-24 border-t border-slate-200 bg-white p-4 overflow-x-auto whitespace-nowrap flex items-center gap-1">
                  {editSteps.length > 0 && editSteps.map((step, i) => (
                    <React.Fragment key={i}>
                       <div className="inline-flex flex-col justify-center h-12 bg-blue-50 border border-blue-100 rounded px-2 min-w-[100px]" style={{ width: Math.max(100, step.durationDays * 10) }}>
                          <span className="text-[10px] font-bold text-blue-800 truncate">{step.name}</span>
                          <span className="text-[9px] text-blue-500">Day {step.offsetStart} - {step.offsetStart + step.durationDays}</span>
                       </div>
                       {i < editSteps.length - 1 && <ArrowRight size={12} className="text-slate-300 mx-1" />}
                    </React.Fragment>
                  ))}
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

