export const getProjects = () => PROJECTS;
export const getTasks = () => TASKS;
export const getUsers = () => USERS;
export const getEvents = () => EVENTS;
export const getNotices = () => NOTICES;
export const getAssets = () => ASSETS;
export const getTaskTemplates = () => TASK_TEMPLATES;

export const getTasksByProject = (pid: string) => TASKS.filter(t => t.projectId === pid);
export const getTasksByUser = (uid: string) => TASKS.filter(t => t.assigneeId === uid);

export const getEngineerWorkload = (uid: string): number => {
  return TASKS.filter(t => t.assigneeId === uid && (t.status === TaskStatus.IN_PROGRESS)).length;
};

export const addTask = (task: Task) => {
  TASKS.push(task);
  return task;
};

export const updateTask = (task: Task) => {
  const index = TASKS.findIndex(t => t.id === task.id);
  if (index !== -1) {
    TASKS[index] = task;
  }
};

export const updateTaskStatus = (tid: string, status: TaskStatus) => {
  const t = TASKS.find(task => task.id === tid);
  if (t) t.status = status;
};

export const updateUser = (updatedUser: User) => {
  const index = USERS.findIndex(u => u.id === updatedUser.id);
  if (index !== -1) {
    USERS[index] = updatedUser;
  }
};

export const addProject = (project: Project) => {
  PROJECTS.push(project);
  return project;
};

export const updateProject = (project: Project) => {
  const index = PROJECTS.findIndex(p => p.id === project.id);
  if (index !== -1) {
    PROJECTS[index] = project;
  }
};

export const addEvent = (event: ScheduleEvent) => {
  EVENTS.push(event);
  EVENTS.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
};

export const addNotice = (notice: Notice) => {
  NOTICES.unshift(notice); // Add to top
};

export const updateNotice = (notice: Notice) => {
  const index = NOTICES.findIndex(n => n.id === notice.id);
  if (index !== -1) {
    NOTICES[index] = notice;
  }
};

export const deleteNotice = (id: string) => {
  const index = NOTICES.findIndex(n => n.id === id);
  if (index !== -1) {
    NOTICES.splice(index, 1);
  }
};

// Template CRUD
export const addTemplate = (template: TaskTemplate) => {
  TASK_TEMPLATES.push(template);
};

export const updateTemplate = (template: TaskTemplate) => {
  const index = TASK_TEMPLATES.findIndex(t => t.id === template.id);
  if (index !== -1) {
    TASK_TEMPLATES[index] = template;
  }
};

export const deleteTemplate = (id: string) => {
  const index = TASK_TEMPLATES.findIndex(t => t.id === id);
  if (index !== -1) {
    TASK_TEMPLATES.splice(index, 1);
  }
};

export const addTasksFromTemplate = (projectId: string, templateId: string, startDateStr: string, assigneeId: string) => {
  const template = TASK_TEMPLATES.find(t => t.id === templateId);
  if (!template) return;

  // We need to keep track of tasks to build dependencies crudely
  // Since our template structure only has offsetStart, we can infer dependency
  // if offsetStart matches the end of another task.
  // BUT, to keep it simple and robust, we will just create the tasks with correct dates.
  // The user can manually link dependencies in the Gantt chart if needed for specific logic.

  const baseDate = new Date(startDateStr);

  template.steps.forEach((step, index) => {
    // Calculate start date
    const start = new Date(baseDate);
    start.setDate(baseDate.getDate() + step.offsetStart);

    // Calculate end date
    const end = new Date(start);
    end.setDate(start.getDate() + step.durationDays);

    const newTask: Task = {
      id: `t-${Date.now()}-${index}`,
      projectId: projectId,
      name: step.name,
      assigneeId: assigneeId, // Default to manager initially or specific person
      startDate: start.toISOString().split('T')[0],
      endDate: end.toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      department: template.department,
      dependencies: [], // Reset dependencies for template import, let dates drive it or user link it
      isAdHoc: false
    };

    TASKS.push(newTask);
  });
};

export const getUserById = (id: string) => USERS.find(u => u.id === id);
export const getProjectById = (id: string) => PROJECTS.find(p => p.id === id);

export const checkOverdue = (task: Task): boolean => {
    if (task.status === TaskStatus.COMPLETED) return false;
    const end = new Date(task.endDate);
    const now = new Date();
    return end < now;
};

import React, { useState, useEffect } from 'react';
import { TaskTemplate, TemplateStep, User } from '../types';
import { Plus, Trash2, Save, GripVertical, ChevronRight, ArrowRight, LayoutList, Workflow, ArrowDownToLine, GitMerge, Square } from 'lucide-react';

interface TemplateEditorProps {
  templates: TaskTemplate[];
  users: User[];
  onAddTemplate: (template: TaskTemplate) => void;
  onUpdateTemplate: (template: TaskTemplate) => void;
  onDeleteTemplate: (id: string) => void;
}

const TemplateEditor: React.FC<TemplateEditorProps> = ({ templates, users, onAddTemplate, onUpdateTemplate, onDeleteTemplate }) => {
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);

  // Editing State
  const [editName, setEditName] = useState('');
  const [editDept, setEditDept] = useState('');
  const [editSteps, setEditSteps] = useState<TemplateStep[]>([]);
  const [isDirty, setIsDirty] = useState(false);

  // Derive Departments from Users
  const departments = Array.from(new Set(users.map(u => u.department))).sort();

  useEffect(() => {
    if (selectedTemplateId) {
      const t = templates.find(t => t.id === selectedTemplateId);
      if (t) {
        setEditName(t.name);
        setEditDept(t.department);
        setEditSteps([...t.steps]); // Clone to avoid direct mutation
        setIsDirty(false);
      }
    } else {
       // Reset or keep blank
       setEditName('');
       setEditDept((departments[0] as string) || '');
       setEditSteps([]);
       setIsDirty(false);
    }
  }, [selectedTemplateId, templates]);

  const handleSelectTemplate = (id: string) => {
    if (isDirty && !window.confirm("您有未儲存的變更，確定要切換模板嗎？")) {
      return;
    }
    setSelectedTemplateId(id);
  };

  const handleCreateNew = () => {
     if (isDirty && !window.confirm("您有未儲存的變更，確定要建立新模板嗎？")) {
      return;
    }
    const newId = `tmpl-${Date.now()}`;
    const newTemplate: TaskTemplate = {
      id: newId,
      name: '新流程模板',
      department: departments[0] || '一般',
      steps: [
        { name: '第一階段', durationDays: 7, offsetStart: 0 }
      ]
    };
    onAddTemplate(newTemplate);
    setSelectedTemplateId(newId);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("確定要刪除此模板嗎？此動作無法復原。")) {
      onDeleteTemplate(id);
      if (selectedTemplateId === id) setSelectedTemplateId(null);
    }
  };

  const handleSave = () => {
    if (!selectedTemplateId) return;
    const updated: TaskTemplate = {
      id: selectedTemplateId,
      name: editName,
      department: editDept,
      steps: editSteps
    };
    onUpdateTemplate(updated);
    setIsDirty(false);
    alert('模板已儲存！');
  };

  // --- Flexible Step Addition ---

  const getLastStep = () => editSteps[editSteps.length - 1];

  // 1. Sequential: Start after the last step ends
  const addStepSequential = () => {
    const last = getLastStep();
    const newOffset = last ? last.offsetStart + last.durationDays : 0;
    setEditSteps([...editSteps, { name: '新序列步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  // 2. Parallel: Start at the same time as the last step
  const addStepParallel = () => {
    const last = getLastStep();
    const newOffset = last ? last.offsetStart : 0;
    setEditSteps([...editSteps, { name: '新同步步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  // 3. Independent: Start at Day 0 (or allow manual)
  const addStepIndependent = () => {
    setEditSteps([...editSteps, { name: '新獨立步驟', durationDays: 5, offsetStart: 0 }]);
    setIsDirty(true);
  };

  const updateStep = (index: number, field: keyof TemplateStep, value: any) => {
    const newSteps = [...editSteps];
    newSteps[index] = { ...newSteps[index], [field]: value };
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  const removeStep = (index: number) => {
    const newSteps = [...editSteps];
    newSteps.splice(index, 1);
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  // Sort templates for list
  const sortedTemplates = [...templates].sort((a, b) => a.department.localeCompare(b.department));

  // --- Gantt Preview Logic ---
  const maxDays = editSteps.length > 0 
    ? Math.max(...editSteps.map(s => s.offsetStart + s.durationDays)) + 5 
    : 30;

  // Calculate relative positions for preview
  const getStyle = (step: TemplateStep) => {
    const left = (step.offsetStart / maxDays) * 100;
    const width = (step.durationDays / maxDays) * 100;
    return { left: `${left}%`, width: `${width}%` };
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
          <Workflow className="text-brand-600" /> 任務流程模板編輯器
        </h2>
        <button 
          onClick={handleCreateNew}
          className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
        >
          <Plus size={16} /> 建立新模板
        </button>
      </div>

      <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">

        {/* Sidebar List */}
        <div className="col-span-4 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden">
           <div className="p-4 border-b border-slate-100 bg-slate-50">
             <h3 className="font-semibold text-slate-700">現有模板 ({templates.length})</h3>
           </div>
           <div className="flex-1 overflow-y-auto p-2 space-y-2">
             {sortedTemplates.map(t => (
               <div 
                 key={t.id}
                 onClick={() => handleSelectTemplate(t.id)}
                 className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedTemplateId === t.id ? 'bg-brand-50 border-brand-200 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
               >
                 <div className="flex justify-between items-start">
                   <div>
                     <h4 className={`font-bold text-sm ${selectedTemplateId === t.id ? 'text-brand-700' : 'text-slate-700'}`}>{t.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">{t.department} • {t.steps.length} 步驟</p>
                   </div>
                   {selectedTemplateId === t.id && <ChevronRight size={16} className="text-brand-400 mt-1" />}
                 </div>
               </div>
             ))}
           </div>
        </div>

        {/* Main Editor Area */}
        <div className="col-span-8 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden relative">
           {!selectedTemplateId ? (
             <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
               <Workflow size={48} className="mb-4 opacity-20" />
               <p>請選擇左側模板或建立新模板</p>
             </div>
           ) : (
             <>
               {/* Header Controls */}
               <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-start">
                  <div className="flex-1 grid grid-cols-2 gap-4 mr-8">
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">模板名稱</label>
                       <input 
                         type="text" 
                         value={editName}
                         onChange={(e) => { setEditName(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-brand-500"
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">所屬部門</label>
                       <select 
                         value={editDept}
                         onChange={(e) => { setEditDept(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-brand-500"
                       >
                         {departments.map(d => <option key={d} value={d}>{d}</option>)}
                       </select>
                     </div>
                  </div>
                  <div className="flex gap-2">
                     <button 
                       onClick={() => handleDelete(selectedTemplateId)}
                       className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded"
                       title="刪除模板"
                     >
                       <Trash2 size={18} />
                     </button>
                     <button 
                       onClick={handleSave}
                       disabled={!isDirty}
                       className={`flex items-center gap-2 px-4 py-2 rounded text-sm font-bold shadow-sm transition-all ${isDirty ? 'bg-brand-600 text-white hover:bg-brand-700' : 'bg-slate-200 text-slate-400 cursor-default'}`}
                     >
                       <Save size={16} /> 儲存
                     </button>
                  </div>
               </div>

               {/* Steps List */}
               <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                  <div className="flex flex-wrap justify-between items-center mb-4 gap-2">
                     <h3 className="font-bold text-slate-700 flex items-center gap-2"><LayoutList size={18}/> 流程步驟定義</h3>

                     <div className="flex bg-slate-100 p-1 rounded-lg">
                        <button onClick={addStepSequential} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="接續上一個步驟">
                           <ArrowDownToLine size={14} className="text-blue-500"/> 新增序列
                        </button>
                        <div className="w-px bg-slate-300 my-1 mx-1"></div>
                        <button onClick={addStepParallel} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="與上一個步驟同時開始">
                           <GitMerge size={14} className="text-purple-500 rotate-90"/> 新增同步
                        </button>
                        <div className="w-px bg-slate-300 my-1 mx-1"></div>
                        <button onClick={addStepIndependent} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="從第0天開始">
                           <Square size={14} className="text-amber-500"/> 新增獨立
                        </button>
                     </div>
                  </div>

                  <div className="space-y-3">
                    {editSteps.map((step, index) => (
                      <div key={index} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4 group">
                         <div className="text-slate-300 cursor-move"><GripVertical size={20} /></div>
                         <div className="flex flex-col items-center justify-center w-10 gap-1">
                           <div className="flex items-center justify-center w-6 h-6 rounded-full bg-slate-100 text-slate-500 text-xs font-bold border border-slate-200">
                             {index + 1}
                           </div>
                         </div>

                         <div className="flex-1 grid grid-cols-12 gap-4 items-center">
                            <div className="col-span-5">
                              <label className="block text-[10px] text-slate-400 mb-0.5">任務名稱</label>
                              <input 
                                type="text" 
                                value={step.name}
                                onChange={(e) => updateStep(index, 'name', e.target.value)}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm font-medium text-slate-800 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">工期 (天)</label>
                               <input 
                                type="number" 
                                min="1"
                                value={step.durationDays}
                                onChange={(e) => updateStep(index, 'durationDays', parseInt(e.target.value))}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                              />
                            </div>
                            <div className="col-span-4">
                               <label className="block text-[10px] text-slate-400 mb-0.5">開始時間 (偏移天數)</label>
                               <div className="flex items-center gap-2">
                                 <span className="text-xs text-slate-400 font-mono">Day</span>
                                 <input 
                                  type="number" 
                                  min="0"
                                  value={step.offsetStart}
                                  onChange={(e) => updateStep(index, 'offsetStart', parseInt(e.target.value))}
                                  className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                                />
                               </div>
                            </div>
                         </div>

                         <button 
                           onClick={() => removeStep(index)}
                           className="text-slate-300 hover:text-red-500 p-2 opacity-0 group-hover:opacity-100 transition-opacity"
                         >
                           <Trash2 size={16} />
                         </button>
                      </div>
                    ))}
                    {editSteps.length === 0 && (
                      <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-lg text-slate-400">
                         請點選上方按鈕新增第一個流程步驟
                      </div>
                    )}
                  </div>
               </div>

               {/* Enhanced Gantt Preview */}
               <div className="h-48 border-t border-slate-200 bg-slate-50 p-4 flex flex-col overflow-hidden">
                  <h4 className="text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">流程預覽 (甘特圖)</h4>
                  <div className="flex-1 relative border border-slate-200 bg-white rounded overflow-y-auto custom-scrollbar">

                     {/* Time Grid (Background) */}
                     <div className="absolute inset-0 flex pointer-events-none">
                        {Array.from({ length: 10 }).map((_, i) => (
                           <div key={i} className="flex-1 border-r border-slate-100 h-full relative">
                              <span className="absolute top-1 left-1 text-[9px] text-slate-300">D{Math.floor((maxDays / 10) * i)}</span>
                           </div>
                        ))}
                     </div>

                     {/* Task Bars */}
                     <div className="relative py-2 space-y-2 min-h-full">
                        {editSteps.map((step, i) => {
                           const style = getStyle(step);
                           return (
                              <div key={i} className="relative h-6 w-full flex items-center">
                                 {/* Connector line could go here */}
                                 <div 
                                    className="absolute h-5 bg-blue-100 border border-blue-300 rounded text-[10px] text-blue-800 flex items-center px-2 whitespace-nowrap overflow-hidden shadow-sm hover:bg-blue-200 transition-colors cursor-default"
                                    style={style}
                                    title={`${step.name} (Day ${step.offsetStart} - ${step.offsetStart + step.durationDays})`}
                                 >
                                    <span className="font-bold mr-1">{i+1}.</span> {step.name}
                                 </div>
                              </div>
                           )
                        })}
                     </div>
                  </div>
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

export default TemplateEditor;

import React, { useState, useEffect } from 'react';
import { TaskTemplate, TemplateStep, User } from '../types';
import { Plus, Trash2, Save, GripVertical, ChevronRight, ArrowRight, LayoutList, Workflow, ArrowDownToLine, GitMerge, Square } from 'lucide-react';

interface TemplateEditorProps {
  templates: TaskTemplate[];
  users: User[];
  onAddTemplate: (template: TaskTemplate) => void;
  onUpdateTemplate: (template: TaskTemplate) => void;
  onDeleteTemplate: (id: string) => void;
}

const TemplateEditor: React.FC<TemplateEditorProps> = ({ templates, users, onAddTemplate, onUpdateTemplate, onDeleteTemplate }) => {
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);

  // Editing State
  const [editName, setEditName] = useState('');
  const [editDept, setEditDept] = useState('');
  const [editSteps, setEditSteps] = useState<TemplateStep[]>([]);
  const [isDirty, setIsDirty] = useState(false);

  // Derive Departments from Users
  const departments: string[] = Array.from(new Set(users.map(u => u.department))).sort();

  useEffect(() => {
    if (selectedTemplateId) {
      const t = templates.find(t => t.id === selectedTemplateId);
      if (t) {
        setEditName(t.name);
        setEditDept(t.department);
        setEditSteps([...t.steps]); // Clone to avoid direct mutation
        setIsDirty(false);
      }
    } else {
       // Reset or keep blank
       setEditName('');
       setEditDept(departments[0] || '');
       setEditSteps([]);
       setIsDirty(false);
    }
  }, [selectedTemplateId, templates]); // Note: departments is derived from users, users change might trigger this if added to deps, but typically users don't change often in this context.

  const handleSelectTemplate = (id: string) => {
    if (isDirty && !window.confirm("您有未儲存的變更，確定要切換模板嗎？")) {
      return;
    }
    setSelectedTemplateId(id);
  };

  const handleCreateNew = () => {
     if (isDirty && !window.confirm("您有未儲存的變更，確定要建立新模板嗎？")) {
      return;
    }
    const newId = `tmpl-${Date.now()}`;
    const newTemplate: TaskTemplate = {
      id: newId,
      name: '新流程模板',
      department: departments[0] || '一般',
      steps: [
        { name: '第一階段', durationDays: 7, offsetStart: 0 }
      ]
    };
    onAddTemplate(newTemplate);
    setSelectedTemplateId(newId);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("確定要刪除此模板嗎？此動作無法復原。")) {
      onDeleteTemplate(id);
      if (selectedTemplateId === id) setSelectedTemplateId(null);
    }
  };

  const handleSave = () => {
    if (!selectedTemplateId) return;
    const updated: TaskTemplate = {
      id: selectedTemplateId,
      name: editName,
      department: editDept,
      steps: editSteps
    };
    onUpdateTemplate(updated);
    setIsDirty(false);
    alert('模板已儲存！');
  };

  // --- Flexible Step Addition ---

  const getLastStep = () => editSteps[editSteps.length - 1];

  // 1. Sequential: Start after the last step ends
  const addStepSequential = () => {
    const last = getLastStep();
    const newOffset = last ? last.offsetStart + last.durationDays : 0;
    setEditSteps([...editSteps, { name: '新序列步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  // 2. Parallel: Start at the same time as the last step
  const addStepParallel = () => {
    const last = getLastStep();
    const newOffset = last ? last.offsetStart : 0;
    setEditSteps([...editSteps, { name: '新同步步驟', durationDays: 5, offsetStart: newOffset }]);
    setIsDirty(true);
  };

  // 3. Independent: Start at Day 0 (or allow manual)
  const addStepIndependent = () => {
    setEditSteps([...editSteps, { name: '新獨立步驟', durationDays: 5, offsetStart: 0 }]);
    setIsDirty(true);
  };

  const updateStep = (index: number, field: keyof TemplateStep, value: any) => {
    const newSteps = [...editSteps];
    newSteps[index] = { ...newSteps[index], [field]: value };
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  const removeStep = (index: number) => {
    const newSteps = [...editSteps];
    newSteps.splice(index, 1);
    setEditSteps(newSteps);
    setIsDirty(true);
  };

  // Sort templates for list
  const sortedTemplates = [...templates].sort((a, b) => a.department.localeCompare(b.department));

  // --- Gantt Preview Logic ---
  const maxDays = editSteps.length > 0 
    ? Math.max(...editSteps.map(s => s.offsetStart + s.durationDays)) + 5 
    : 30;

  // Calculate relative positions for preview
  const getStyle = (step: TemplateStep) => {
    const left = (step.offsetStart / maxDays) * 100;
    const width = (step.durationDays / maxDays) * 100;
    return { left: `${left}%`, width: `${width}%` };
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
          <Workflow className="text-brand-600" /> 任務流程模板編輯器
        </h2>
        <button 
          onClick={handleCreateNew}
          className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
        >
          <Plus size={16} /> 建立新模板
        </button>
      </div>

      <div className="flex-1 grid grid-cols-12 gap-6 min-h-0">

        {/* Sidebar List */}
        <div className="col-span-4 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden">
           <div className="p-4 border-b border-slate-100 bg-slate-50">
             <h3 className="font-semibold text-slate-700">現有模板 ({templates.length})</h3>
           </div>
           <div className="flex-1 overflow-y-auto p-2 space-y-2">
             {sortedTemplates.map(t => (
               <div 
                 key={t.id}
                 onClick={() => handleSelectTemplate(t.id)}
                 className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedTemplateId === t.id ? 'bg-brand-50 border-brand-200 shadow-sm' : 'bg-white border-slate-100 hover:bg-slate-50'}`}
               >
                 <div className="flex justify-between items-start">
                   <div>
                     <h4 className={`font-bold text-sm ${selectedTemplateId === t.id ? 'text-brand-700' : 'text-slate-700'}`}>{t.name}</h4>
                     <p className="text-xs text-slate-500 mt-1">{t.department} • {t.steps.length} 步驟</p>
                   </div>
                   {selectedTemplateId === t.id && <ChevronRight size={16} className="text-brand-400 mt-1" />}
                 </div>
               </div>
             ))}
           </div>
        </div>

        {/* Main Editor Area */}
        <div className="col-span-8 bg-white rounded-xl shadow-sm border border-slate-100 flex flex-col overflow-hidden relative">
           {!selectedTemplateId ? (
             <div className="flex-1 flex flex-col items-center justify-center text-slate-400">
               <Workflow size={48} className="mb-4 opacity-20" />
               <p>請選擇左側模板或建立新模板</p>
             </div>
           ) : (
             <>
               {/* Header Controls */}
               <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex justify-between items-start">
                  <div className="flex-1 grid grid-cols-2 gap-4 mr-8">
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">模板名稱</label>
                       <input 
                         type="text" 
                         value={editName}
                         onChange={(e) => { setEditName(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm font-bold text-slate-800 focus:ring-2 focus:ring-brand-500"
                       />
                     </div>
                     <div>
                       <label className="block text-xs font-bold text-slate-500 mb-1">所屬部門</label>
                       <select 
                         value={editDept}
                         onChange={(e) => { setEditDept(e.target.value); setIsDirty(true); }}
                         className="w-full border border-slate-300 rounded px-3 py-2 text-sm text-slate-700 focus:ring-2 focus:ring-brand-500"
                       >
                         {departments.map(d => <option key={d} value={d}>{d}</option>)}
                       </select>
                     </div>
                  </div>
                  <div className="flex gap-2">
                     <button 
                       onClick={() => handleDelete(selectedTemplateId)}
                       className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded"
                       title="刪除模板"
                     >
                       <Trash2 size={18} />
                     </button>
                     <button 
                       onClick={handleSave}
                       disabled={!isDirty}
                       className={`flex items-center gap-2 px-4 py-2 rounded text-sm font-bold shadow-sm transition-all ${isDirty ? 'bg-brand-600 text-white hover:bg-brand-700' : 'bg-slate-200 text-slate-400 cursor-default'}`}
                     >
                       <Save size={16} /> 儲存
                     </button>
                  </div>
               </div>

               {/* Steps List */}
               <div className="flex-1 overflow-y-auto p-6 bg-slate-50">
                  <div className="flex flex-wrap justify-between items-center mb-4 gap-2">
                     <h3 className="font-bold text-slate-700 flex items-center gap-2"><LayoutList size={18}/> 流程步驟定義</h3>

                     <div className="flex bg-slate-100 p-1 rounded-lg">
                        <button onClick={addStepSequential} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="接續上一個步驟">
                           <ArrowDownToLine size={14} className="text-blue-500"/> 新增序列
                        </button>
                        <div className="w-px bg-slate-300 my-1 mx-1"></div>
                        <button onClick={addStepParallel} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="與上一個步驟同時開始">
                           <GitMerge size={14} className="text-purple-500 rotate-90"/> 新增同步
                        </button>
                        <div className="w-px bg-slate-300 my-1 mx-1"></div>
                        <button onClick={addStepIndependent} className="flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-white hover:shadow-sm rounded-md transition-all" title="從第0天開始">
                           <Square size={14} className="text-amber-500"/> 新增獨立
                        </button>
                     </div>
                  </div>

                  <div className="space-y-3">
                    {editSteps.map((step, index) => (
                      <div key={index} className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm flex items-center gap-4 group">
                         <div className="text-slate-300 cursor-move"><GripVertical size={20} /></div>
                         <div className="flex flex-col items-center justify-center w-10 gap-1">
                           <div className="flex items-center justify-center w-6 h-6 rounded-full bg-slate-100 text-slate-500 text-xs font-bold border border-slate-200">
                             {index + 1}
                           </div>
                         </div>

                         <div className="flex-1 grid grid-cols-12 gap-4 items-center">
                            <div className="col-span-5">
                              <label className="block text-[10px] text-slate-400 mb-0.5">任務名稱</label>
                              <input 
                                type="text" 
                                value={step.name}
                                onChange={(e) => updateStep(index, 'name', e.target.value)}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm font-medium text-slate-800 bg-transparent"
                              />
                            </div>
                            <div className="col-span-3">
                               <label className="block text-[10px] text-slate-400 mb-0.5">工期 (天)</label>
                               <input 
                                type="number" 
                                min="1"
                                value={step.durationDays}
                                onChange={(e) => updateStep(index, 'durationDays', parseInt(e.target.value))}
                                className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                              />
                            </div>
                            <div className="col-span-4">
                               <label className="block text-[10px] text-slate-400 mb-0.5">開始時間 (偏移天數)</label>
                               <div className="flex items-center gap-2">
                                 <span className="text-xs text-slate-400 font-mono">Day</span>
                                 <input 
                                  type="number" 
                                  min="0"
                                  value={step.offsetStart}
                                  onChange={(e) => updateStep(index, 'offsetStart', parseInt(e.target.value))}
                                  className="w-full border-b border-slate-200 focus:border-brand-500 focus:outline-none py-1 text-sm text-slate-700 bg-transparent"
                                />
                               </div>
                            </div>
                         </div>

                         <button 
                           onClick={() => removeStep(index)}
                           className="text-slate-300 hover:text-red-500 p-2 opacity-0 group-hover:opacity-100 transition-opacity"
                         >
                           <Trash2 size={16} />
                         </button>
                      </div>
                    ))}
                    {editSteps.length === 0 && (
                      <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-lg text-slate-400">
                         請點選上方按鈕新增第一個流程步驟
                      </div>
                    )}
                  </div>
               </div>

               {/* Enhanced Gantt Preview */}
               <div className="h-48 border-t border-slate-200 bg-slate-50 p-4 flex flex-col overflow-hidden">
                  <h4 className="text-xs font-bold text-slate-500 mb-2 uppercase tracking-wider">流程預覽 (甘特圖)</h4>
                  <div className="flex-1 relative border border-slate-200 bg-white rounded overflow-y-auto custom-scrollbar">

                     {/* Time Grid (Background) */}
                     <div className="absolute inset-0 flex pointer-events-none">
                        {Array.from({ length: 10 }).map((_, i) => (
                           <div key={i} className="flex-1 border-r border-slate-100 h-full relative">
                              <span className="absolute top-1 left-1 text-[9px] text-slate-300">D{Math.floor((maxDays / 10) * i)}</span>
                           </div>
                        ))}
                     </div>

                     {/* Task Bars */}
                     <div className="relative py-2 space-y-2 min-h-full">
                        {editSteps.map((step, i) => {
                           const style = getStyle(step);
                           return (
                              <div key={i} className="relative h-6 w-full flex items-center">
                                 {/* Connector line could go here */}
                                 <div 
                                    className="absolute h-5 bg-blue-100 border border-blue-300 rounded text-[10px] text-blue-800 flex items-center px-2 whitespace-nowrap overflow-hidden shadow-sm hover:bg-blue-200 transition-colors cursor-default"
                                    style={style}
                                    title={`${step.name} (Day ${step.offsetStart} - ${step.offsetStart + step.durationDays})`}
                                 >
                                    <span className="font-bold mr-1">{i+1}.</span> {step.name}
                                 </div>
                              </div>
                           )
                        })}
                     </div>
                  </div>
               </div>
             </>
           )}
        </div>
      </div>
    </div>
  );
};

export default TemplateEditor;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  ENGINEER = 'ENGINEER',
}

export enum ProjectStatus {
  PLANNING = 'PLANNING',
  QUOTE_NEEDED = 'QUOTE_NEEDED',
  QUOTED = 'QUOTED',
  IN_PROGRESS = 'IN_PROGRESS',
  ACCEPTANCE = 'ACCEPTANCE',
  COMPLETED = 'COMPLETED',
  CANCELLED = 'CANCELLED',
}

export enum TaskStatus {
  NOT_STARTED = 'NOT_STARTED',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  OVERDUE = 'OVERDUE',
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  department: string;
  avatar: string;
}

export interface Task {
  id: string;
  projectId: string;
  name: string;
  assigneeId: string;
  startDate: string;
  endDate: string;
  status: TaskStatus;
  dependencies: string[]; // IDs of tasks that must be completed before this one
  department: string;
  isAdHoc?: boolean;
  notes?: string;
}

export interface Project {
  id: string;
  name: string;
  client: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  managerId: string;
  description: string;
  departments: string[];
}

export interface MeetingNote {
  id: string;
  projectId: string;
  date: string;
  attendees: string[];
  content: string;
  actionItems: string;
}

export interface ScheduleEvent {
  id: string;
  title: string;
  date: string; // ISO String
  time: string;
  relatedProjectId?: string;
  attendees: string[];
}

export interface Asset {
  id: string;
  name: string;
  status: 'AVAILABLE' | 'IN_USE';
  borrower?: string;
  returnDate?: string;
}

export interface Notice {
  id: string;
  title: string;
  date: string;
  content: string;
  type: 'SYSTEM' | 'ANNOUNCEMENT';
}

export interface TemplateStep {
  name: string;
  durationDays: number;
  offsetStart: number; // calculated automatically based on preceding step
  precedingStepIndex?: number; // -1 or undefined means independent (start day 0), otherwise index of parent
}

export interface TaskTemplate {
  id: string;
  name: string;
  department: string;
  steps: TemplateStep[];
}

