                      value={formData.status}
                      onChange={(e) => setFormData({...formData, status: e.target.value as 'ACTIVE' | 'INACTIVE'})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                    >
                      <option value="ACTIVE">活躍 (Active)</option>
                      <option value="INACTIVE">停用 (Inactive)</option>
                    </select>
                    <p className="text-xs text-slate-400 mt-2">停用的客戶將不會顯示在新增專案的選單中。</p>
                 </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                <button 
                  type="button" 
                  onClick={() => setIsModalOpen(false)} 
                  className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium"
                >
                  取消
                </button>
                <button 
                  type="submit" 
                  className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
                >
                  <Save size={16} /> 儲存
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

