import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import ProjectHub from './components/ProjectHub';
import TaskManager from './components/TaskManager';
import ScheduleStats from './components/ScheduleStats';
import AssetBooking from './components/AssetBooking';
import TeamManagement from './components/TeamManagement';
import TemplateEditor from './components/TemplateEditor';
import CustomerManagement from './components/CustomerManagement';
import { 
  getProjects, getTasks, getUsers, getEvents, getNotices, getAssets, getTaskTemplates, getCustomers,
  getUserById, addTask, updateTaskStatus, updateUser, addEvent, addProject, updateProject,
  addTasksFromTemplate, updateTask, addNotice, updateNotice, deleteNotice,
  addTemplate, updateTemplate, deleteTemplate,
  addCustomer, updateCustomer, deleteCustomer
} from './services/mockService';
import { User, Project, Task, ScheduleEvent, Notice, Asset, TaskStatus, UserRole, TaskTemplate, Customer } from './types';

const App: React.FC = () => {
  // Global App State
  const [currentUser, setCurrentUser] = useState<User | undefined>(undefined);
  const [projects, setProjects] = useState<Project[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [events, setEvents] = useState<ScheduleEvent[]>([]);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [templates, setTemplates] = useState<TaskTemplate[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);

  // Initialization
  useEffect(() => {
    // Load mock data
    const allUsers = getUsers();
    setUsers(allUsers);
    setCurrentUser(allUsers[0]); // Default to Admin
    setProjects(getProjects());
    setTasks(getTasks());
    setEvents(getEvents());
    setNotices(getNotices());
    setAssets(getAssets());
    setTemplates(getTaskTemplates());
    setCustomers(getCustomers());
  }, []);

  const handleSwitchUser = (userId: string) => {
    const user = users.find(u => u.id === userId);
    if (user) setCurrentUser(user);
  };

  const handleAddTask = (newTask: Task) => {
    addTask(newTask);
    setTasks([...getTasks()]); // Refresh from service
  };

  const handleUpdateTask = (id: string, status: TaskStatus) => {
    updateTaskStatus(id, status);
    setTasks([...getTasks()]); // Refresh
  };

  const handleFullUpdateTask = (task: Task) => {
    updateTask(task);
    setTasks([...getTasks()]);
  };

  const handleUpdateUser = (updatedUser: User) => {
    updateUser(updatedUser);
    setUsers([...getUsers()]); // Refresh
    // If updating current user self
    if (currentUser && currentUser.id === updatedUser.id) {
      setCurrentUser(updatedUser);
    }
  };

  const handleAddProject = (newProject: Project) => {
    addProject(newProject);
    setProjects([...getProjects()]);
  };

  const handleUpdateProject = (updatedProject: Project) => {
    updateProject(updatedProject);
    setProjects([...getProjects()]);
  };

  const handleAddEvent = (newEvent: ScheduleEvent) => {
    addEvent(newEvent);
    setEvents([...getEvents()]);
  }

  const handleImportTemplate = (projectId: string, templateId: string, startDate: string, assigneeId: string) => {
    addTasksFromTemplate(projectId, templateId, startDate, assigneeId);
    setTasks([...getTasks()]);
  };

  const handleAddNotice = (notice: Notice) => {
    addNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleUpdateNotice = (notice: Notice) => {
    updateNotice(notice);
    setNotices([...getNotices()]);
  };

  const handleDeleteNotice = (id: string) => {
    deleteNotice(id);
    setNotices([...getNotices()]);
  };

  // Template Handlers
  const handleAddTemplate = (template: TaskTemplate) => {
    addTemplate(template);
    setTemplates([...getTaskTemplates()]);
  };

  const handleUpdateTemplate = (template: TaskTemplate) => {
    updateTemplate(template);
    setTemplates([...getTaskTemplates()]);
  };

  const handleDeleteTemplate = (id: string) => {
    deleteTemplate(id);
    setTemplates([...getTaskTemplates()]);
  };

  // Customer Handlers
  const handleAddCustomer = (customer: Customer) => {
    addCustomer(customer);
    setCustomers([...getCustomers()]);
  };

  const handleUpdateCustomer = (customer: Customer) => {
    updateCustomer(customer);
    setCustomers([...getCustomers()]);
  };

  const handleDeleteCustomer = (id: string) => {
    deleteCustomer(id);
    setCustomers([...getCustomers()]);
  };

  if (!currentUser) return <div className="flex items-center justify-center h-screen">載入中...</div>;

  return (
    <HashRouter>
      <Layout currentUser={currentUser} onSwitchUser={handleSwitchUser} users={users}>
        <Routes>
          <Route 
            path="/" 
            element={
              <Dashboard 
                user={currentUser} 
                users={users}
                projects={projects} 
                tasks={tasks} 
                events={events} 
                notices={notices} 
                onAddNotice={handleAddNotice}
                onUpdateNotice={handleUpdateNotice}
                onDeleteNotice={handleDeleteNotice}
              />
            } 
          />
          <Route 
            path="/projects" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser} 
                templates={templates}
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
                onAddTask={handleAddTask}
              />
            } 
          />
          <Route 
            path="/projects/:id" 
            element={
              <ProjectHub 
                projects={projects} 
                tasks={tasks} 
                users={users}
                currentUser={currentUser}
                templates={templates} 
                onAddProject={handleAddProject} 
                onUpdateProject={handleUpdateProject}
                onImportTemplate={handleImportTemplate}
                onUpdateTask={handleFullUpdateTask}
                onAddTask={handleAddTask}
              />
            } 
          />
          <Route path="/tasks" element={<TaskManager tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddTask={handleAddTask} onUpdateTask={handleUpdateTask} />} />
          <Route path="/schedule" element={<ScheduleStats events={events} tasks={tasks} users={users} projects={projects} currentUser={currentUser} onAddEvent={handleAddEvent} />} />
          <Route path="/assets" element={<AssetBooking assets={assets} />} />

          {/* Admin & Manager Routes */}
          {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MANAGER) && (
             <>
               <Route 
                 path="/customers" 
                 element={
                   <CustomerManagement 
                     customers={customers}
                     onAddCustomer={handleAddCustomer}
                     onUpdateCustomer={handleUpdateCustomer}
                     onDeleteCustomer={handleDeleteCustomer}
                   />
                 } 
               />
               <Route 
                 path="/templates" 
                 element={
                   <TemplateEditor 
                     templates={templates} 
                     users={users} 
                     onAddTemplate={handleAddTemplate}
                     onUpdateTemplate={handleUpdateTemplate}
                     onDeleteTemplate={handleDeleteTemplate}
                   />
                 } 
               />
             </>
          )}

          {/* Admin Only Route */}
          {currentUser.role === UserRole.ADMIN && (
             <Route path="/team" element={<TeamManagement users={users} onUpdateUser={handleUpdateUser} />} />
          )}

          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </Layout>
    </HashRouter>
  );
};

export default App;

export enum UserRole {
  ADMIN = 'ADMIN',
  MANAGER = 'MANAGER',
  ENGINEER = 'ENGINEER',
}

export enum ProjectStatus {
  PLANNING = 'PLANNING',
  QUOTE_NEEDED = 'QUOTE_NEEDED',
  QUOTED = 'QUOTED',
  IN_PROGRESS = 'IN_PROGRESS',
  ACCEPTANCE = 'ACCEPTANCE',
  COMPLETED = 'COMPLETED',
  CANCELLED = 'CANCELLED',
}

export enum TaskStatus {
  NOT_STARTED = 'NOT_STARTED',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  OVERDUE = 'OVERDUE',
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  department: string;
  avatar: string;
}

export interface Task {
  id: string;
  projectId: string;
  name: string;
  assigneeId: string;
  startDate: string;
  endDate: string;
  status: TaskStatus;
  dependencies: string[]; // IDs of tasks that must be completed before this one
  department: string;
  isAdHoc?: boolean;
  notes?: string;
}

export interface Project {
  id: string;
  name: string;
  client: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  managerId: string;
  description: string;
  departments: string[];
}

export interface MeetingNote {
  id: string;
  projectId: string;
  date: string;
  attendees: string[];
  content: string;
  actionItems: string;
}

export interface ScheduleEvent {
  id: string;
  title: string;
  date: string; // ISO String
  time: string;
  relatedProjectId?: string;
  attendees: string[];
}

export interface Asset {
  id: string;
  name: string;
  status: 'AVAILABLE' | 'IN_USE';
  borrower?: string;
  returnDate?: string;
}

export interface Notice {
  id: string;
  title: string;
  date: string;
  content: string;
  type: 'SYSTEM' | 'ANNOUNCEMENT';
}

export interface TemplateStep {
  name: string;
  durationDays: number;
  offsetStart: number; // calculated automatically based on preceding step
  precedingStepIndex?: number; // -1 or undefined means independent (start day 0), otherwise index of parent
}

export interface TaskTemplate {
  id: string;
  name: string;
  department: string;
  steps: TemplateStep[];
}

export interface Customer {
  id: string;
  name: string; // Company Name
  contactPerson: string;
  email: string;
  phone: string;
  industry: string;
  address?: string;
  notes?: string;
}

