export const addTasksFromTemplate = (projectId: string, templateId: string, startDateStr: string, assigneeId: string) => {
  const template = TASK_TEMPLATES.find(t => t.id === templateId);
  if (!template) return;

  // We rely on the stored offsetStart which is calculated by the editor
  // precedingStepIndex is mainly for the editor's UI logic, but could be used to link dependencies here if desired.

  const baseDate = new Date(startDateStr);
  const createdTaskIds: string[] = [];

  template.steps.forEach((step, index) => {
    // Calculate start date
    const start = new Date(baseDate);
    start.setDate(baseDate.getDate() + step.offsetStart);

    // Calculate end date
    const end = new Date(start);
    end.setDate(start.getDate() + step.durationDays);

    // Determine dependencies from template
    const taskDeps: string[] = [];
    if (step.precedingStepIndex !== undefined && step.precedingStepIndex >= 0 && step.precedingStepIndex < createdTaskIds.length) {
       taskDeps.push(createdTaskIds[step.precedingStepIndex]);
    }

    const newTask: Task = {
      id: `t-${Date.now()}-${index}`,
      projectId: projectId,
      name: step.name,
      assigneeId: assigneeId, // Default to manager initially or specific person
      startDate: start.toISOString().split('T')[0],
      endDate: end.toISOString().split('T')[0],
      status: TaskStatus.NOT_STARTED,
      department: template.department,
      dependencies: taskDeps, 
      isAdHoc: false
    };

    TASKS.push(newTask);
    createdTaskIds.push(newTask.id);
  });
};

