  // NEW: Create Task Modal State
  const [isCreateTaskModalOpen, setCreateTaskModalOpen] = useState(false);
  const [newTaskData, setNewTaskData] = useState<Partial<Task>>({});

  // Form Data State
  const [formData, setFormData] = useState<Partial<Project>>({
    name: '', client: '', description: '', startDate: '', endDate: '', departments: []
  });

  // Template Form State
  const [templateId, setTemplateId] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateAssignee, setTemplateAssignee] = useState('');

  // Task Edit State
  const [editingTask, setEditingTask] = useState<Task | null>(null);

  // Extract all known departments from existing projects for suggestions
  const allKnownDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Extract all unique departments from projects for filter
  // MOVED UP before conditional return to avoid React Error #300
  const filterDepartments = useMemo(() => Array.from(new Set(projects.flatMap(p => p.departments))).sort(), [projects]);

  // Filter projects based on selection and view mode
  // MOVED UP before conditional return to avoid React Error #300
  const filteredProjects = useMemo(() => {
    return projects.filter(p => {
      // 1. Department Filter
      const deptMatch = selectedDept === 'ALL' || p.departments.includes(selectedDept);

      // 2. View Mode Filter (All vs Mine)
      let viewMatch = true;
      if (viewFilter === 'MINE') {
        if (currentUser.role === UserRole.MANAGER || currentUser.role === UserRole.ADMIN) {
           // Manager sees projects they manage OR projects where they have tasks
           viewMatch = p.managerId === currentUser.id;
        } else {
           // Engineer sees projects where they have at least one task assigned
           const userTasks = tasks.filter(t => t.projectId === p.id && t.assigneeId === currentUser.id);
           viewMatch = userTasks.length > 0;
        }
      }

      return deptMatch && viewMatch;
    });
  }, [projects, tasks, selectedDept, viewFilter, currentUser]);

  const toggleColumn = (status: ProjectStatus) => {
    setCollapsedStatuses(prev => 
      prev.includes(status) ? prev.filter(s => s !== status) : [...prev, status]
    );
