  };


  // --- DETAIL VIEW ---
  if (id) {
    const project = projects.find(p => p.id === id);
    if (!project) return <div>Project not found</div>;

    const projectTasks = tasks.filter(t => t.projectId === id);
    const isDeptManager = currentUser.role === UserRole.MANAGER && project.departments.includes(currentUser.department);
    const canEditTasks = isDeptManager || currentUser.role === UserRole.ADMIN;
    const canEditStatus = currentUser.role === UserRole.ADMIN;

    // ALLOW ALL TEMPLATES - Removed Filter based on prompt request
    const availableTemplates = templates; 

    return (
      <div className="space-y-6 animate-in fade-in duration-300">
        {/* Breadcrumb */}
        <button onClick={() => navigate('/projects')} className="flex items-center text-sm text-slate-500 hover:text-brand-600 mb-4">
          <ArrowLeft size={16} className="mr-1" /> 返回專案列表
        </button>

        {/* Project Header */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex justify-between items-start">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-slate-900">{project.name}</h1>
              {/* Quick Status Selector in Detail View */}
              <QuickStatusSelector 
                project={project} 
                canEdit={canEditStatus} 
                onUpdateStatus={(s) => onUpdateProject({...project, status: s})} 
              />
            </div>
            <p className="text-slate-500 mt-2">{project.description}</p>
            <div className="flex items-center gap-6 mt-4 text-sm text-slate-500">
               <span className="flex items-center gap-1"><Calendar size={14} /> {project.startDate} - {project.endDate}</span>
               <span className="flex items-center gap-1"><UserCircle size={14} /> 客戶: {project.client}</span>
            </div>
            <div className="flex gap-2 mt-4">
              <span className="text-xs font-bold text-slate-400 py-1">參與部門:</span>
              {project.departments.map(d => (
                <span key={d} className="px-2 py-1 bg-slate-100 text-slate-600 text-xs rounded border border-slate-200">
                  {d}
                </span>
              ))}
            </div>
          </div>
          <div className="flex gap-2">
            {isDeptManager && (
              <button 
                onClick={() => {
                   setTemplateStartDate(new Date().toISOString().split('T')[0]);
                   setTemplateAssignee(currentUser.id);
                   setTemplateModalOpen(true);
                }}
                className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm hover:bg-brand-700 flex items-center gap-2"
              >
                <Workflow size={16} /> 匯入任務流程
              </button>
            )}
            {currentUser.role === UserRole.ADMIN && (
               <button 
                  onClick={() => openEditModal(project)}
                  className="px-4 py-2 bg-slate-900 text-white rounded-lg text-sm hover:bg-slate-800 flex items-center gap-2"
               >
                 <Edit size={16} /> 編輯專案
               </button>
            )}
          </div>
        </div>

        {/* View Switcher & Content */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 min-h-[500px]">
           <div className="flex justify-between items-center mb-6">
             <div className="flex items-center gap-4">
                <h3 className="text-lg font-semibold text-slate-800">專案任務</h3>

                {/* View Tabs */}
                <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button 
                    onClick={() => setDetailViewMode('LIST')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'LIST' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <List size={16} /> 列表
                  </button>
                  <button 
                    onClick={() => setDetailViewMode('GRAPH')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'GRAPH' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <Network size={16} /> 流程圖
                  </button>
                   <button 
                    onClick={() => setDetailViewMode('GANTT')}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${detailViewMode === 'GANTT' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <CalendarRange size={16} /> 甘特圖
                  </button>
                </div>
             </div>
           </div>

           {/* Render Content based on View Mode */}
           {detailViewMode === 'GRAPH' && (
              <SimpleDependencyGraph 
                  tasks={projectTasks} 
                  onTaskClick={canEditTasks ? openEditTaskModal : undefined}
                  onAddClick={canEditTasks ? openCreateTaskModal : undefined}
              />
           )}

           {detailViewMode === 'GANTT' && (
              <ProjectGanttChart 
                 tasks={projectTasks} 
                 users={users}
                 onTaskClick={canEditTasks ? openEditTaskModal : undefined}
              />
           )}

           {detailViewMode === 'LIST' && (
             <div className="overflow-x-auto">
               <table className="w-full text-sm text-left">
                 <thead className="bg-slate-50 text-slate-500">
                   <tr>
                     <th className="px-4 py-2">任務</th>
                     <th className="px-4 py-2">負責人</th>
                     <th className="px-4 py-2">日期</th>
                     <th className="px-4 py-2">狀態</th>
                     <th className="px-4 py-2">操作</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                   {projectTasks.length === 0 ? (
                     <tr><td colSpan={5} className="text-center py-4 text-slate-400">暫無任務</td></tr>
                   ) : (
                     projectTasks.map(t => (
                       <tr key={t.id} className="hover:bg-slate-50 group">
                         <td className="px-4 py-3 font-medium">
                           {t.name}
                           {t.department === currentUser.department && (
                             <span className="ml-2 text-[10px] text-brand-600 bg-brand-50 px-1 rounded border border-brand-100">本部門</span>
                           )}
                         </td>
                         <td className="px-4 py-3 flex items-center gap-2">
                           <img src={users.find(u=>u.id===t.assigneeId)?.avatar} className="w-6 h-6 rounded-full"/>
                           {users.find(u=>u.id===t.assigneeId)?.name.split(' ')[0]}
                         </td>
                         <td className="px-4 py-3 text-slate-500">{t.startDate} - {t.endDate}</td>
                         <td className="px-4 py-3">
                           <span className={`px-2 py-0.5 rounded text-xs ${t.status === TaskStatus.COMPLETED ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'}`}>
                             {TASK_STATUS_MAP[t.status]}
                           </span>
                         </td>
                         <td className="px-4 py-3">
                           {(currentUser.role === UserRole.MANAGER && t.department === currentUser.department) || currentUser.role === UserRole.ADMIN ? (
                             <button onClick={() => openEditTaskModal(t)} className="text-slate-400 hover:text-brand-600 opacity-0 group-hover:opacity-100 transition-opacity">
                               <Edit size={14} />
                             </button>
                           ) : null}
                         </td>
                       </tr>
                     ))
                   )}
                 </tbody>
               </table>
             </div>
           )}
        </div>

        {/* Import Template Modal */}
        {isTemplateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6 animate-in fade-in zoom-in duration-200">
               <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">匯入標準任務流程</h3>
                <button onClick={() => setTemplateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleTemplateSubmit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">選擇流程模板</label>
                  <select 
                    value={templateId} 
                    onChange={e => setTemplateId(e.target.value)}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    required
                  >
                    <option value="">請選擇...</option>
                    {availableTemplates.map(t => (
                      <option key={t.id} value={t.id}>{t.name} ({t.department})</option>
                    ))}
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">流程開始日期</label>
                    <input 
                      type="date"
                      value={templateStartDate}
                      onChange={e => setTemplateStartDate(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                      required
                    />
                  </div>
                   <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">預設負責人</label>
                    <select 
                      value={templateAssignee}
                      onChange={e => setTemplateAssignee(e.target.value)}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                    >
                      {users.filter(u => u.department === currentUser.department && u.role === UserRole.ENGINEER).map(u => (
                        <option key={u.id} value={u.id}>{u.name}</option>
                      ))}
                      <option value={currentUser.id}>我自己 (主管)</option>
                    </select>
                  </div>
                </div>

                <div className="bg-slate-50 p-3 rounded text-xs text-slate-500 border border-slate-200 mt-2">
                  <p>匯入後，系統將自動建立所有相關任務並設定依賴關係。您可以在列表中點擊編輯按鈕來微調每個任務的日期與負責人。</p>
                </div>

                <div className="flex justify-end gap-3 mt-6">
                  <button type="button" onClick={() => setTemplateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Workflow size={16} /> 確認匯入
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Create Task Modal */}
        {isCreateTaskModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
             <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200 flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-center mb-6 border-b border-slate-100 pb-4">
                <div>
                  <h3 className="text-lg font-bold text-slate-800">新增任務節點</h3>
                  <p className="text-xs text-slate-400 mt-1">專案: {project.name}</p>
                </div>
                <button onClick={() => setCreateTaskModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleCreateTaskSubmit} className="space-y-6 overflow-y-auto pr-2">
                 <div className="grid grid-cols-1 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-slate-700 mb-1">任務名稱</label>
                      <input 
                        type="text" 
                        value={newTaskData.name || ''} 
                        onChange={(e) => setNewTaskData({...newTaskData, name: e.target.value})}
                        className="w-full border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-brand-500 focus:outline-none"
                        placeholder="輸入任務名稱..."
                        required
                      />
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">負責人</label>
                        <select 
                          value={newTaskData.assigneeId || ''}
                          onChange={e => setNewTaskData({...newTaskData, assigneeId: e.target.value})}
                          className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                          required
                        >
                          <option value="">請選擇...</option>
                          {users.filter(u => u.department === newTaskData.department || u.role === UserRole.ENGINEER).map(u => (
                            <option key={u.id} value={u.id}>{u.name} - {u.department}</option>
                          ))}
                        </select>
                    </div>
                     <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">部門</label>
                        <input 
                          type="text" 
                          value={newTaskData.department || ''} 
                          readOnly
                          className="w-full border border-slate-200 bg-slate-50 rounded-lg px-3 py-2 text-sm text-slate-500"
                        />
                    </div>
                 </div>

                 {/* Dependencies Selection for New Task */}
                 <div className="bg-slate-50 p-4 rounded-lg border border-slate-200">
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-sm font-bold text-slate-700 flex items-center gap-2">
                        <Link size={14} /> 設定前置任務 (連線)
                      </label>
                    </div>
                    <div className="space-y-2 max-h-32 overflow-y-auto border border-slate-300 bg-white rounded p-2">
                        {projectTasks.map(t => (
                          <label key={t.id} className="flex items-center gap-2 text-sm p-1 hover:bg-slate-50 rounded cursor-pointer">
                             <input 
                                type="checkbox" 
                                checked={newTaskData.dependencies?.includes(t.id)}
                                onChange={() => toggleDependencyForNewTask(t.id)}
                                className="rounded text-brand-600 focus:ring-brand-500"
                             />
                             <span className="flex-1">{t.name} <span className="text-slate-400 text-xs">({t.endDate})</span></span>
                             {newTaskData.dependencies?.includes(t.id) && <ArrowRight size={12} className="text-brand-500"/>}
                          </label>
                        ))}
                        {projectTasks.length === 0 && <div className="text-xs text-slate-400 italic text-center">無前置任務可選</div>}
                    </div>
                 </div>

                 <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">開始日期</label>
                    <input 
                      type="date"
                      value={newTaskData.startDate || ''}
                      onChange={e => setNewTaskData({...newTaskData, startDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">結束日期</label>
                    <input 
                      type="date"
                      value={newTaskData.endDate || ''}
                      onChange={e => setNewTaskData({...newTaskData, endDate: e.target.value})}
                      className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                      required
                    />
                  </div>
                </div>

                <div className="flex justify-end gap-3 mt-6 border-t border-slate-100 pt-4">
                  <button type="button" onClick={() => setCreateTaskModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Plus size={16} /> 建立節點
                  </button>
                </div>
              </form>
             </div>
          </div>
        )}

        {/* Edit Project Modal (Existing) */}
        {isEditModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">編輯專案</h3>
                <button onClick={() => setEditModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleEditSubmit} className="space-y-4">
                {renderFormFields()}

                {/* Status Field (Only for Edit) */}
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">專案狀態</label>
                  <select 
                    value={formData.status} 
                    onChange={e => setFormData({...formData, status: e.target.value as ProjectStatus})}
                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm"
                  >
                    {Object.entries(STATUS_CONFIG).map(([key, conf]) => (
                      <option key={key} value={key}>{conf.label}</option>
                    ))}
                  </select>
                </div>

                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setEditModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Save size={16} /> 儲存變更
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- LIST VIEW (Main Kanban Board) ---

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center flex-shrink-0">
        <h2 className="text-2xl font-bold text-slate-900">專案中心</h2>
        {currentUser.role === UserRole.ADMIN && (
          <button 
            onClick={openCreateModal}
            className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2"
          >
            <Plus size={16} /> 新增專案
          </button>
        )}
      </div>

      {/* Control Bar: View Mode & Filters */}
      <div className="flex flex-wrap items-center justify-between gap-4 pb-2 flex-shrink-0 bg-white p-3 rounded-xl border border-slate-100 shadow-sm">

        {/* Left: View Mode Toggle */}
        <div className="flex items-center gap-2">
           <div className="flex bg-slate-100 p-1 rounded-lg">
             <button
               onClick={() => setViewFilter('ALL')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'ALL' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <Layers size={16} />
               全部專案
             </button>
             <button
               onClick={() => setViewFilter('MINE')}
               className={`flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all ${
                 viewFilter === 'MINE' ? 'bg-white text-brand-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <UserIcon size={16} />
               {currentUser.role === UserRole.ENGINEER ? '我參與的' : '我負責的'}
             </button>
           </div>

           <div className="h-6 w-px bg-slate-200 mx-2"></div>

           {/* Department Filters */}
           <div className="flex items-center gap-2">
              <span className="text-xs text-slate-400 font-bold uppercase tracking-wider">部門過濾:</span>
              <select 
                value={selectedDept}
                onChange={(e) => setSelectedDept(e.target.value)}
                className="text-sm border-none bg-transparent font-medium text-slate-600 focus:ring-0 cursor-pointer hover:text-slate-900"
              >
                <option value="ALL">全部部門</option>
                {filterDepartments.map(dept => (
                  <option key={dept} value={dept}>{dept}</option>
                ))}
              </select>
           </div>
        </div>

        {/* Right: Legend or Help text */}
        <div className="hidden md:flex items-center gap-3 text-xs text-slate-400">
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-slate-400"></span> 規劃</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-blue-500"></span> 進行</span>
           <span className="flex items-center gap-1"><span className="w-2 h-2 rounded-full bg-green-500"></span> 完成</span>
        </div>
      </div>

      {/* New Tiered Kanban Layout */}
      <div className="space-y-8 pb-12">
        {filteredProjects.length === 0 ? (
          <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300 w-full h-40 flex items-center justify-center">
             <div className="flex flex-col items-center gap-2">
                <p className="text-slate-500 font-medium">沒有符合條件的專案。</p>
                <p className="text-xs text-slate-400">請嘗試切換「檢視模式」或「部門過濾器」。</p>
             </div>
          </div>
        ) : (
          <>
            {/* Row 1: Active Work (In Progress, Acceptance) */}
            <div>
              <div className="mb-3 mt-2 flex items-center gap-2 text-slate-800 font-bold text-sm bg-slate-50/50 p-2 rounded-lg border border-slate-100 inline-block">
                  <Activity size={16} className="text-brand-600"/>
                  <span>執行與驗收 (Active)</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 h-[450px]">
                 {renderColumn(ProjectStatus.IN_PROGRESS)}
                 {renderColumn(ProjectStatus.ACCEPTANCE)}
              </div>
            </div>

            {/* Row 2: Pipeline (Planning, Quote Needed, Quoted) */}
            <div>
              <div className="mb-3 flex items-center gap-2 text-slate-800 font-bold text-sm bg-slate-50/50 p-2 rounded-lg border border-slate-100 inline-block">
                  <FileText size={16} className="text-amber-600"/>
                  <span>規劃與報價 (Pipeline)</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-[450px]">
                 {renderColumn(ProjectStatus.PLANNING)}
                 {renderColumn(ProjectStatus.QUOTE_NEEDED)}
                 {renderColumn(ProjectStatus.QUOTED)}
              </div>
            </div>

            {/* Row 3: Archives (Completed, Cancelled) - Collapsible */}
            <div className="border-t border-slate-200 pt-6">
               <button 
                 onClick={() => setIsArchiveOpen(!isArchiveOpen)}
                 className="flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-slate-800 transition-colors mb-4 w-full"
               >
                 <Archive size={18} />
                 歸檔專案 (完成/取消)
                 <div className="flex-1 h-px bg-slate-200 ml-4"></div>
                 {isArchiveOpen ? <ChevronUp size={16}/> : <ChevronDown size={16}/>}
               </button>

               {isArchiveOpen && (
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6 h-[450px] animate-in fade-in slide-in-from-top-4 duration-300">
                    {renderColumn(ProjectStatus.COMPLETED)}
                    {renderColumn(ProjectStatus.CANCELLED)}
                 </div>
               )}
            </div>
          </>
        )}
      </div>

      {/* Create Project Modal */}
      {isCreateModalOpen && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-lg w-full p-6 animate-in fade-in zoom-in duration-200">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold text-slate-800">建立新專案</h3>
                <button onClick={() => setCreateModalOpen(false)}><X className="text-slate-400 hover:text-slate-600" /></button>
              </div>
              <form onSubmit={handleCreateSubmit} className="space-y-4">
                {renderFormFields()}
                <div className="flex justify-end gap-3 mt-6 pt-4 border-t border-slate-100">
                  <button type="button" onClick={() => setCreateModalOpen(false)} className="px-4 py-2 text-slate-600 hover:bg-slate-100 rounded-lg text-sm font-medium">取消</button>
                  <button type="submit" className="px-4 py-2 bg-brand-600 text-white rounded-lg text-sm font-medium hover:bg-brand-700 flex items-center gap-2">
                    <Plus size={16} /> 建立專案
                  </button>
                </div>
              </form>
            </div>
          </div>
      )}
    </div>
  );
};

